local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["zone:stockade"] = {n="O Cárcere",s="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da cidade, perto do Distrito dos Magos. Construído para deter os criminosos mais perigosos, insurgentes políticos e inimigos do estado capturados do reino, as instalações colapsaram recentemente em uma anarquia violenta. O Carcereiro-chefe Thelágua foi forçado a recuar para a entrada, recrutando desesperadamente aventureiros capazes para esmagar a rebelião por dentro antes que ela se espalhe para a capital.",h="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da...",kw={"basílio taborda","bruegal ferroque","canais","defias","flávio lúcio","ramoque","kam fundafúria","rebelião","o cárcere","ventobravo","targorr","carcereiro-chefe thelágua"},ang={["class:Mage"]="Localizada bem na beira do canal do Distrito dos Magos, a prisão contém brigões físicos vulneráveis a magias de lentidão, enquanto o ogro mago Ramoque pode liberar uma Cadeia de Raios.",["class:Rogue"]="O layout da prisão apresenta uma rede complexa de celas de ferro trancadas e conexões com a Irmandade Défias, oferecendo prática única de arrombamento de fechaduras e informações sobre o sindicato do submundo de Basílio Taborda.",["faction:Alliance"]="A rebelião ameaça o próprio coração da capital; conter a revolta preserva a segurança interna de Ventobravo enquanto honra recompensas não oficiais para Montanhas Cristarrubra, Floresta do Crepúsculo e Altaforja.",["race:Dwarf"]="A presença de Kam Fundafúria nas celas de Ventobravo é uma afronta a Dun Modr; o Reino de Altaforja exige a cabeça dele para vingar as vidas anãs perdidas nas Pantanal."},sec={{t="Uma Prisão sob Cerco",b="Sob os canais tranquilos de Ventobravo, O Cárcere tornou-se uma zona de guerra. Quando o exército regular marchou para lutar em frentes distantes, a prisão, com falta de pessoal, passou a depender de jovens inexperientes — incluindo recrutas de catorze anos — para manter a ordem. Não funcionou. Os detentos iniciaram uma rebelião sangrenta e coordenada, rasgando seus cobertores de lã para fazer bandanas de gangue e eliminando os guardas restantes. O Carcereiro-chefe Thelágua mal conseguiu manter o controle da entrada, deixando as celas, corredores e blocos de detenção nas mãos impiedosas dos condenados."},{t="Nobres e Assassinos",b="A rebelião expôs o lado feio da máquina política de Ventobravo. Territórios externos há muito estavam frustrados com a Casa dos Nobres suspendendo execuções para sua própria vantagem. O Guarda Berto, de Cristarrubra, queria que o orc capturado Targorr, o Horror fosse executado por suas atrocidades, apenas para ver os nobres congelarem a sentença. O Conselheiro Bonfá-lobos, de Vila Sombria, viu o ladrão de túmulos Flávio Lúcio ser poupado da forca, apesar de profanar túmulos para o necromante Morbent Fel. Até os anões de Dun Modr enviaram mensagens exigindo a morte do sabotador Ferro Negro Kam Fundafúria. Com O Cárcere em caos, as autoridades locais contrataram silenciosamente aventureiros para realizar as execuções que os tribunais da capital se recusaram a aplicar."},{t="O Mentor e os Rebeldes",b="Por trás do colapso sincronizado da prisão está Basílio Taborda, um criminoso astuto ligado diretamente à Irmandade Défias, que orquestrou a revolta de sua cela. Entre os rebeldes está Bruegal Ferroque, um perigoso brigão anão. Ele é um dos vários condenados endurecidos que os aventureiros podem encontrar enquanto ajudam Thelágua a retomar a prisão."}},faq={{q="Por que O Cárcere está em rebelião aberta?",a="A Irmandade Défias orquestrou uma rebelião em toda a prisão enquanto as instalações estavam com falta de pessoal. Com o Exército de Ventobravo destacado para frentes de batalha distantes, voluntários adolescentes foram deixados guardando assassinos endurecidos. Os condenados emboscaram a equipe, apreenderam armas e forçaram o Carcereiro-chefe Thelágua a sair dos blocos de celas.",al={"por que a rebelião","o que aconteceu no cárcere","causa da rebelião no cárcere"}},{q="Quem está comandando a revolta lá dentro?",a="O mentor por trás da revolta é Basílio Taborda, um influente criminoso da Irmandade Défias encarcerado no bloco de celas leste. Outros prisioneiros perigosos incluem Bruegal Ferroque, Ramoque e Kam Fundafúria.",al={"chefe do cárcere","quem lidera a rebelião","quem comanda o cárcere"}},{q="Por que prisioneiros como Targorr e Flávio Lúcio ainda estão vivos?",a="Ambos foram condenados à morte, mas políticos corruptos dentro da Casa dos Nobres impuseram impedimentos burocráticos às suas execuções para usá-los como alavancagem política. Essa interferência indignou aliados em Vila Plácida e Vila Sombria, levando-os a enviar aventureiros para eliminar os prisioneiros durante o caos.",al={"por que targorr não foi executado","julgamento de flávio lúcio","corrupção da casa dos nobres"}},{q="O que derrotar Bruegal Ferroque significa para a prisão?",a="Bruegal Ferroque é um perigoso brigão anão entre os rebeldes. Derrotá-lo remove uma ameaça da prisão enquanto os aventureiros trabalham para conter a rebelião.",al={"história de bruegal ferroque","matar bruegal","quem é bruegal"}},{q="Por que há anões Ferro Negro e orcs numa prisão humana?",a="O Cárcere serve como uma prisão de segurança máxima para prisioneiros de guerra de alto valor. Targorr, o Horror liderou ataques de orcs Rocha Negra em Montanhas Cristarrubra, enquanto Kam Fundafúria realizou sabotagem para o clã Ferro Negro nas Pantanal antes de ambos serem capturados e transferidos para a capital.",al={"por que os anões Ferro Negro estão aqui","história de Kam Fundafúria","Targorr no Cárcere"}},{q="Jogadores da Horda podem entrar em O Cárcere?",a="Sim, mas é excepcionalmente perigoso. A entrada da masmorra fica diretamente dentro de Ventobravo, perto dos canais do Distrito dos Magos. Infiltrados da Horda devem passar furtivamente pelos guardas da cidade e pelos defensores da capital para alcançar o portal.",al={"a horda pode fazer o cárcere","horda na prisão de ventobravo"}}},fx={["07af5e0b"]={q="O que é o Cárcere?",a="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, construído sob o distrito de Canals da capital. Ele serve como local de detenção para pequenos ladrões, assassinos, insurgentes políticos e inimigos de alto perfil do reino que aguardam julgamento.",al={"o que é o carcere de ventobravo","prisão o carcere","cadeia de ventobravo"}},["2fc364a6"]={q="O Cárcere é apenas para a Irmandade Défias?",a="Não. Embora a Irmandade Défias componha o núcleo da revolta, as celas abrigam pequenos ladrões, saqueadores de túmulos como Flávio Lúcio, orcs do Rocha Negra capturados como Targorr, o Horror, e até mesmo sabotadores Ferro Negro como Kam Fundafúria.",al={"o carcere é só para a irmandade défias","quem está no Cárcere","todos os prisioneiros são da irmandade défias"}},["0d433487"]={q="Por que há tantos integrantes da Irmandade Défias presos aqui?",a="As autoridades de Ventobravo capturaram agentes da irmandade por toda Cerro Oeste, Floresta de Elwynn e na própria cidade. Em vez de executá-los imediatamente, a coroa os levou para o Cárcere, concentrando uma rede volátil de insurgentes bem debaixo das tábuas do assoalho da cidade.",al={"por que tantos integrantes da irmandade défias aqui","por que a irmandade défias no Cárcere","prisioneiros da Irmandade Défias"}},e96a18b2={q="Quem é o responsável por esta prisão?",a="O Carcereiro-chefe Thelágua comanda a instalação. Quando a revolta estourou, seus guardas foram sobrecarregados e expulsos dos blocos de celas. Thelágua mal conseguiu manter a entrada, deixando-o desesperado para recrutar aventureiros capazes para retomar os corredores.",al={"quem comanda o Cárcere","carcereiro do Cárcere","carcereiro-chefe thelágua"}},["06cbacdc"]={q="Por que os guardas do Carcereiro-chefe Thelágua não conseguem conter o motim?",a="A guarda prisional já estava extremamente reduzida, recorrendo até a voluntários com apenas quatorze anos para vigiar detentos perigosos. Quando a Irmandade Défias se uniu e atacou, a equipe foi pega totalmente de surpresa, massacrada ou forçada a fugir para o saguão de entrada.",al={"por que os guardas não impedem o motim","onde estão os guardas da prisão","guardas do Cárcere"}},["7c158547"]={q="Por que Ventobravo está me enviando em vez do exército?",a="Grande parte das forças militares de Ventobravo está posicionada em frentes distantes, e a burocracia corrupta na Casa dos Nobres paralisa ações municipais rápidas. Além disso, as autoridades da cidade estão desesperadas para manter o motim em segredo para evitar pânico total nas ruas.",al={"por que enviar aventureiros","por que não o exército no Cárcere","onde está o exército de ventobravo"}},a2006c52={q="Os guardas do lado de fora sabem o que está acontecendo lá dentro?",a="Os guardas contêm os amotinados no limiar da masmorra, e o Carcereiro-chefe Thelágua busca ajuda para restaurar a ordem no interior. As autoridades da cidade mantêm a perturbação discreta para evitar alarmar os cidadãos comuns.",al={"os guardas externos sabem do motim","Ventobravo sabe do motim","segredo do Cárcere"}},b1798127={q="Qual é a diferença entre os prisioneiros, condenados e insurgentes aqui dentro?",a="Os detentos variam de criminosos comuns e batedores de carteira tirados das ruas a criminosos condenados e insurgentes radicais da Irmandade Défias. Enquanto os condenados comuns aproveitaram a chance para se amotinar e saquear, os insurgentes recebem ordens ativamente de Basílio Taborda para derrubar a prisão.",al={"prisioneiros insurgentes","tipos de inimigos do Cárcere","quem são os detentos"}},["378bbf14"]={q="Como os detentos conseguiram armas e se organizaram?",a="A revolta foi meticulosamente planejada pelo líder da Irmandade Défias, Basílio Taborda. Sob sua direção, os prisioneiros rasgaram seus cobertores de lã em lenços vermelhos de gangue, atacaram guardas com pouco contingente, roubaram suas armas e chaves, e metodicamente libertaram celas em todas as alas.",al={"como os prisioneiros conseguiram armas","como a irmandade défias se organizou","quem armou os prisioneiros"}},["855deb71"]={q="Por que colocar uma prisão bem debaixo da cidade?",a="O complexo prisional fica sob os canais de Ventobravo. Sua localização original não é explicada.",al={"por que há uma prisão sob Ventobravo","localização do Cárcere","prisão sob os canais"}},caa2e4bf={q="Como eu acabei no Cárcere?",a="Você atravessou as pesadas portas de ferro perto dos canais ao norte em Ventobravo. Um motim massivo estourou sob as ruas, e os guardas restantes do Carcereiro-chefe Thelágua foram forçados a recuar até o limiar, deixando os detentos no controle. Desesperado para manter o caos escondido dos cidadãos lá em cima, o carcereiro recrutou aventureiros aptos para marchar direto para dentro dos blocos de celas e retomar a instalação à força.",al={"como eu cheguei aqui","por que eu vim aqui","como eu entrei no Cárcere"}},["45edc40e"]={q="O que devo fazer no Cárcere?",a="Sua missão principal é acabar com a rebelião e eliminar seu líder, o mentor da Irmandade Défias, Basílio Taborda. No entanto, aliados por todo o reino aproveitaram este momento de caos para acertar contas pendentes: Vila Sombria busca retribuição contra o saqueador de túmulos Flávio Lúcio, Vila Plácida quer que o impiedoso orc Targorr, o Horror seja morto, e Altaforja exige a cabeça do sabotador Kam Fundafúria.",al={"qual é minha missão aqui","o que eu faço aqui","por que estou aqui"}}},fp="12,455,20.556.0,20.705.1,30.341.1,38.314.0,35.198.0,60.303.0,60.167.0,61.278.0,37.226.0"}
P.entries["zone:stonetalon"] = {n="Cordilheira das Torres de Pedra",s="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira com o Vale Gris, os Sertões e Desolação. Venerada tanto pelos elfos noturnos quanto pelos taurens como um santuário sagrado, as alturas consagradas da região contrastam fortemente com a fumaça e o maquinário que sufocam seus cânions inferiores. Hoje, as montanhas estão assoladas pelo desmatamento, pela devastação elemental instável e por crescentes hostilidades de fronteira.",h="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira...",kw={"vale carbonizado","hanfritz schaventorck","malaka'jin","cordilheira das torres de pedra","morro das torres de pedra","retiro rocha do sol","talondeep pass","rochedo cortavento"},ang={["class:Druid"]="A profanação do Rochedo Cortavento e a corrupção calcinada do Vale Carbonizado servem como um grave chamado para druidas que buscam acalmar espíritos da natureza enfurecidos e proteger ninhos sagrados.",["class:Shaman"]="O clamor dos espíritos da montanha sob o ataque das perfuratrizes dos goblins pode ser ouvido até em Orgrimmar, chamando xamãs para conter elementais da terra enfurecidos e restaurar o equilíbrio dos picos.",["faction:Alliance"]="Estacionada no alto do Morro das Torres de Pedra e em acampamentos ocultos ao redor do Rochedo Cortavento, a Aliança defende covis ancestrais kaldorei de máquinas goblins e de rivais territoriais invasores.",["faction:Horde"]="Os aventureiros da Horda contam com o refúgio isolado do Retiro Rocha do Sol e o posto troll meridional de Malaka'jin para frear a poluição industrial dos Empreendimentos S.A. e erradicar os perigosos foras da lei do Totem Sombrio."},sec={{t="Os Maus Ventos e os Picos",b="Erguendo-se abruptamente da região central de Kalimdor, a cordilheira das Torres de Pedra retém a umidade trazida dos mares ocidentais, originando tempestades repentinas e trilhas traiçoeiras de arenito escorregadio pela chuva. A característica mais marcante dos vales inferiores é o vento cortante e incessante conhecido como os Maus Ventos, capaz de cegar viajantes com poeira ou atirar os desatentos diretamente de penhascos íngremes. Mais acima, florestas de coníferas cobrem as encostas ao redor do Morro das Torres de Pedra, onde os elfos noturnos cuidam de covis ancestrais e clareiras, vigiando os ninhos sagrados de mantícoras e hipogrifos que habitam o Lago Mirkfallon."},{t="Indústria e Intrusão",b="A solidão pacífica da cordilheira foi violentamente interrompida pela chegada dos Empreendimentos S.A. Montando extensos acampamentos de extração de madeira e escavando profundas minas a céu aberto no Rochedo Cortavento, os goblins — auxiliados pelo demente gnomo leproso Hanfritz Schaventorck — desmataram árvores centenárias, escureceram os céus com fumaça de fornalhas e despejaram detritos industriais nas águas da montanha. A ganância deles provocou uma retaliação rápida: xamãs locais de Orgrimmar responderam aos gritos agoniados dos espíritos da montanha, enquanto pequenos acampamentos da Aliança nas proximidades lutam contra os profanadores para proteger o que resta das terras altas."},{t="Cicatrizes do Passado",b="Ao sul fica o Vale Carbonizado, outrora uma natureza exuberante, agora reduzido a uma terra devastada coberta de cinzas e tomada por elementais do fogo rebeldes, dracônicos negros e harpias. Embora os picos tenham sido o local histórico onde a Horda e a Aliança forjaram uma frágil trégua durante a Terceira Guerra sob a orientação do misterioso Oráculo, as relações atuais estão se deteriorando. Taurens renegados do Totem Sombrio operam a partir de acampamentos capturados, e trolls Lançanegra em Malaka'jin entram em conflito com incursões da Aliança vindas dos Sertões e do Vale Gris."}},faq={{q="Como chego à Cordilheira das Torres de Pedra?",a="A maioria dos viajantes entra pelo Desfiladeiro da Garra Profunda, uma trilha na montanha que corta a cordilheira a partir do sudoeste do Vale Gris. Também há trilhas elevadas que levam ao sul para Desolação e caminhos que descem a leste diretamente para as extensões setentrionais dos Sertões.",al={"entrada da cordilheira das torres de pedra","como chegar à cordilheira das torres de pedra","estrada da cordilheira das torres de pedra"}},{q="Por que o Vale Carbonizado está queimado e arruinado?",a="O Vale Carbonizado já foi um refúgio luxuriante, mas uma devastação cataclísmica consumiu o vale em chamas. Ele foi reduzido a uma ruína fumegante infestada de agressivos elementais do fogo, draconetes rebeldes e harpias mortais.",al={"fogo no vale carbonizado","o que aconteceu com o vale carbonizado","por que o vale carbonizado queimou"}},{q="O que os Empreendimentos S.A. estão fazendo no Rochedo Cortavento?",a="Os Empreendimentos S.A. estão desmatando árvores impiedosamente e perfurando fundo a encosta da montanha em busca de riquezas minerais. Suas operações poluíram o Lago do Rochedo com graxa de motor, devastaram os vales e enfureceram os espíritos locais e os habitantes nativos.",al={"empreendimentos s.a. cordilheira das torres de pedra","goblins do rochedo cortavento","por que goblins cortam arvores"}},{q="Onde ficam os principais mestres de voo?",a="Os heróis da Aliança usam o mestre de voo situado no santuário elevado do Morro das Torres de Pedra, ao norte, enquanto os aventureiros da Horda se estabelecem na aldeia montanhosa central do Retiro Rocha do Sol.",al={"rota de voo da cordilheira das torres de pedra","onde fica o ponto de voo da cordilheira das torres de pedra","ponto de voo cordilheira das torres de pedra"}},{q="O que aconteceu no Morro das Torres de Pedra durante a Terceira Guerra?",a="Guiados por visões do Profeta Medivh, Thrall e Jaina Proudmore subiram as cavernas do Morro das Torres de Pedra em busca do Oráculo. Lá, os líderes das duas facções forjaram a histórica aliança temporária que se uniu contra a Legião Ardente no Monte Hyjal.",al={"historia do morro das torres de pedra","o oraculo da cordilheira das torres de pedra","terceira guerra cordilheira das torres de pedra"}},{q="Quem são os Totem Sombrio na Cordilheira das Torres de Pedra?",a="Os Totem Sombrio são uma tribo tauren implacável e renegada, hostil a influências externas. Na Cordilheira das Torres de Pedra, eles ocuparam um posto montanhoso perto da fronteira com os Sertões, aterrorizando viajantes locais e fazendo prisioneiros.",al={"aldeia do temível totem","totem sombrio cordilheira das torres de pedra"}}},fx={["5a5a6e9c"]={q="Por que os tauren se estabeleceram no Retiro Rocha do Sol?",a="Por gerações, os tauren reverenciaram este vale como um lugar com uma conexão profunda com o reino espiritual. Lendas antigas dizem que o deus sol An'she beijou o pico sobre o qual o retiro se ergue. Os tauren fizeram peregrinações sagradas aqui por muito tempo para comungar com espíritos e acender grandes fogueiras rituais para iluminar as montanhas sombreadas.",al={"por que tauren se instalam em rocha do sol","história do retiro rocha do sol","an'she rocha do sol"}},["51d42c77"]={q="O que é o Rochedo Cortavento?",a="O Rochedo Cortavento já foi uma floresta virgem verdejante, mas foi devastado pela exploração industrial. A Empreendimentos S.A. desmatou o vale, transformando-o em uma extensão árida de tocos, terra e maquinário fumegante. Entre o desmatamento da Empreendimentos S.A., o escoamento sujo no Lago do Rochedo e os kobolds infestando a mina local, ele se destaca como um monumento arruinado à ganância desenfreada.",al={"sobre o rochedo cortavento","zona do rochedo cortavento","lore do rochedo cortavento"}},d850bc0a={q="O que há na Mina Cortavento?",a="A Mina Cortavento, localizada nos penhascos do sudeste do Rochedo Cortavento, está tomada por kobolds Cortavento agressivos. Expulsos ou abandonados pelos mineradores regulares, os kobolds agora escavam furiosamente veios de Lingotes de Ferro Fumegante, atacando ferozmente qualquer um que tente invadir suas escavações subterrâneas.",al={"kobolds da mina cortavento","o que há na mina cortavento","ferro fumegante mina cortavento"}},d3863c46={q="O que é o Retiro do Gadanho no Morro das Torres de Pedra?",a="O Retiro do Gadanho é uma antiga toca de túmulo dos elfos noturnos esculpida nas alturas do Morro das Torres de Pedra. Ele é mantido por druidas Cenarianos que comungam com os espíritos da natureza e o Sonho Esmeralda. Lá no fundo, druidas tradicionalmente dormiam em contemplação sagrada, protegidos por dríades, guardiões e pelas proteções mágicas do pico.",al={"retiro do gadanho","a toca morro das torres de pedra","toca de túmulo torres de pedra"}},a547ffd6={q="O Vale Gris se conecta à Cordilheira das Torres de Pedra?",a="Sim. O robusto Túnel Garracava conecta diretamente o sudoeste do Vale Gris ao nordeste da Cordilheira das Torres de Pedra através de uma passagem montanhosa cavernosa. Viajantes e aventureiros frequentemente passam entre as florestas imaculadas e contestadas do Vale Gris e as alturas áridas da Cordilheira das Torres de Pedra enquanto rastreiam ameaças da Empreendimentos S.A. ou os conflitos de facções em andamento.",al={"como o vale gris se conecta às torres de pedra","túnel garracava vale gris","fronteira do vale gris torres de pedra"}},a5c2784c={q="Como vim parar na Cordilheira das Torres de Pedra?",a="A maioria dos viajantes chega a essas alturas irregulares através do Túnel Garracava, um antigo túnel montanhoso esculpido no sudoeste do Vale Gris. Outros andarilhos sobem pelas trilhas acidentadas que levam para o oeste saindo dos Sertões, ascendendo as passagens varridas pelo vento em direção aos rochedos. Seja enviado para o sul pelos comandantes elfos noturnos em Astranaar ou despachado para o oeste através da fronteira chamuscada da Encruzilhada, os cânions altos e os Ventos Uivantes saúdam qualquer um que faça a árdua jornada pela cordilheira.",al={"como vim parar aqui","como chego às torres de pedra","chegada às torres de pedra"}},["4abc7ef6"]={q="O que devo fazer na Cordilheira das Torres de Pedra?",a="Você está aqui para enfrentar as ameaças crescentes que estão destruindo essas alturas sagradas. No Rochedo Cortavento, os implacáveis goblins da Empreendimentos S.A. derrubam florestas antigas e poluem os rios com maquinário, atraindo a ira de ambas as facções. Enquanto isso, a tribo Totem Sinistro causa conflitos ao longo da fronteira leste, enquanto harpias cruéis e elementais do fogo enfurecidos infestam a bacia chamuscada do Vale Carbonizado. Você deve ajudar seus aliados a repelir esses poluidores e monstros para proteger a terra.",al={"o que devo fazer aqui","por que estou aqui","qual é minha missão nas torres de pedra"}},["4946a833"]={q="O que é a Cordilheira das Torres de Pedra?",a="A Cordilheira das Torres de Pedra é uma cordilheira acidentada e esculpida pelo vento na região central de Kalimdor, situada a oeste dos Sertões, ao sul do Vale Gris e ao norte da Desolação. Conhecida por ventos extremos, abismos profundos e picos de arenito íngremes criados durante a Grande Cisão, a região forma uma zona fronteiriça histórica onde elfos noturnos e taurens coexistiram por gerações. Seus cumes altos e sagrados permanecem exuberantes com coníferas, enquanto os vales mais baixos são secos, rochosos e fortemente marcados pela indústria.",al={"zona da cordilheira das torres de pedra","o que é a cordilheira das torres de pedra","sobre a cordilheira das torres de pedra"}},["4e995438"]={q="A Cordilheira das Torres de Pedra é perigosa?",a="Sim, os viajantes enfrentam perigos naturais e hostis ferozes. Ventos violentos e chuvas repentinas podem tornar os altos penhascos de arenito escorregadios o suficiente para fazer as pessoas caírem para a morte. Além do clima, as montanhas estão cheias de harpias Fúria-de-sangue agressivas, serpes predatórias, aranhas, kobolds e elementais enfurecidos. Além disso, o maquinário implacável e os executores armados da Empreendimentos S.A. tornam vales disputados como o Rochedo Cortavento excepcionalmente perigosos.",al={"perigo na cordilheira das torres de pedra","a cordilheira das torres de pedra é segura","perigos da cordilheira das torres de pedra"}},["9d849e11"]={q="Quem vive na Cordilheira das Torres de Pedra?",a="A região abriga facções dispersas em vez de um único poder governante. Os elfos noturnos mantêm o Morro das Torres de Pedra e guardam locais sagrados por todas as alturas, enquanto a Horda mantém assentamentos no Retiro Rocha do Sol e a aldeia troll de Malaka'jin. Harpias Fúria-de-sangue nativas aninham-se nas fendas, taurens da Tribo do Totem Sinistro hostis ocupam postos próximos, e a Empreendimentos S.A., operada por goblins, ocupa trechos desmatados ao redor do Rochedo Cortavento.",al={"quem vive na cordilheira das torres de pedra","facções da cordilheira das torres de pedra","habitantes da cordilheira das torres de pedra"}},a4f73e64={q="Por que a Empreendimentos S.A. está explorando madeira no Rochedo Cortavento?",a="A Empreendimentos S.A. é um conglomerado mercantil implacável que busca lucro através da exploração desenfreada de recursos. No Rochedo Cortavento, eles realizam cortes rasos em florestas antigas usando maquinário pesado como o Super Reaper 6000 e explodem a terra em busca de minério precioso. Seu desprezo pela natureza enche o ar com fuligem e envenena as águas locais com lodo e óleo, ganhando a oposição furiosa tanto dos druidas locais quanto da Horda.",al={"extração de madeira da empreendimentos s.a.","por que os goblins estão cortando árvores","madeira da empreendimentos s.a. cordilheira das torres de pedra"}},["66935983"]={q="Quem comanda a Empreendimentos S.A. no Rochedo Cortavento?",a="As operações locais de extração de madeira e mineração no Rochedo Cortavento são dirigidas por um gnomo leproso chamado Gerenzo Wrenchwhistle. Supervisionando o corte raso de uma plataforma construída bem acima do Lago do Rochedo, Gerenzo emprega sua experiência mecânica para maximizar a destruição. Suas operações desonestas até atraíram a ira de inventores goblins rivais da União dos Funileiros, que buscam eliminá-lo.",al={"quem comanda o rochedo cortavento","gerenzo wrenchwhistle","líder da empreendimentos s.a. na cordilheira das torres de pedra"}},ff0da62d={q="Quem são as harpias Fúria-de-sangue?",a="As harpias Fúria-de-sangue são uma tribo cruel de mulheres-pássaro nativas da Cordilheira das Torres de Pedra. Historicamente, essas montanhas eram seu coração ancestral antes de se espalharem pelos Sertões e além. Elas defendem agressivamente seu território de estranhos, capturando bestas locais e entrando em conflito violento com peregrinos taurens e maquinários goblins invasores em locais como o Vale Carbonizado.",al={"harpias fúria-de-sangue","harpias da cordilheira das torres de pedra","quem são as harpias aqui"}},["66599fe7"]={q="O que é o Retiro Rocha do Sol?",a="O Retiro Rocha do Sol é um assentamento pacífico da Horda aninhado em um vale montanhoso isolado ao sul do Lago Mirkfallon. Ele serve como a base principal para taurens e orcs na região, abrigando xamãs e druidas dedicados a restaurar a terra da poluição da Empreendimentos S.A. e combater as ameaças que invadem as montanhas sagradas.",al={"lore do retiro rocha do sol","o que é o retiro rocha do sol","taurens do retiro rocha do sol"}}},fp="20,410,27.610.0,22.630.0,17.537.0,41.251.0,42.215.0,52.258.0,42.193.0,54.257.0,36.219.0"}
P.entries["zone:stormwind"] = {n="Ventobravo",s="Ventobravo é a movimentada capital do Reino de Ventobravo e o principal bastião humano no mundo após a queda de Lordaeron. Reconstruída das cinzas pela Guilda dos Pedreiros após sua destruição na Primeira Guerra, seus magníficos distritos de pedra branca agora abrigam o coração da Grande Aliança. Sob seus majestosos canais e catedrais, no entanto, a cidade enfrenta o súbito desaparecimento do Rei Varian Wrynn e a crescente intriga política.",h="Ventobravo é a movimentada capital do Reino de Ventobravo e o principal bastião humano no mundo após a queda...",kw={"anduin","bolvar","catedral","correfundo","prestor","pedreiros","ventobravo","vancleef","wrynn"},ang={["class:Paladin"]="A Catedral da Luz serve como o santuário supremo da sua fé no sul, treinando cavaleiros do Punho de Prata e defendendo a justiça.",["class:Rogue"]="Sob as ruas imaculadas de pedra fica o quartel-general da AVIN na Cidade Velha, operando a principal rede de inteligência e espionagem da Aliança.",["faction:Alliance"]="Como a metrópole mais populosa da Grande Aliança, Ventobravo fornece poder naval, base espiritual e uma liderança diplomática vital.",["race:Dwarf"]="Por meio do Metrô Correfundo, seus parentes no Distrito dos Anões mantêm profundos laços comerciais e forjam laços militares fraternos com o reino humano.",["race:Human"]="Ventobravo se ergue como a última grande sede de poder soberano do seu povo após a destruição de Lordaeron, Alterac e Dalaran no norte."},sec={{t="Erguendo-se das Cinzas",b="Fundada há mais de um milênio pelos descendentes dos Arathi, Ventobravo manteve-se por gerações como um reino próspero e autossuficiente. Essa era de ouro terminou quando a Horda Órquica atravessou o Portal Negro, assolando o continente meridional e arrasando a capital até o chão na Primeira Guerra. Sobreviventes liderados por Sir Anduin Lothar fugiram para o norte, cruzando O Grande Oceano rumo a Lordaeron. Após a derrota da Horda na Segunda Guerra, o Rei Terenas Menethil II e a Aliança financiaram uma reconstrução completa. A Guilda dos Pedreiros reconstruiu minuciosamente a capital como a Nova Ventobravo — uma cidadela reluzente de pedra branca polida e bairros entrelaçados por canais."},{t="Uma Corte Dividida",b="Apesar de sua majestade exterior, a capital encontra-se travada em um tumulto interno. Uma disputa entre a Casa dos Nobres e a Guilda dos Pedreiros sobre salários deixou o reino paralisado por dívidas. Os protestos decorrentes empurraram os artesãos exilados para a criminalidade como a Irmandade Défias. Agora, o Rei Varian Wrynn desapareceu misteriosamente a caminho de uma conferência diplomática. Para conter o pânico, a coroa foi posta sobre seu jovem filho, o Príncipe Anduin Wrynn, de dez anos, com o Grão-lorde Bolvar Fordragon governando como Regente e comandante militar ao lado da conselheira real Lady Katrana Prestor."},{t="Coração da Grande Aliança",b="Com Lordaeron tomada pelo Flagelo, Ventobravo herdou o manto de maior refúgio da humanidade e epicentro da Aliança. Ela se conecta diretamente ao reino anão de Altaforja através do subterrâneo Metrô Correfundo do Grão-mecânico Mekkatorque. Visitantes que cruzam o Vale dos Heróis são recebidos por imponentes estátuas dos Filhos de Lothar que desapareceram além do Portal Negro. Do farol espiritual da Catedral da Luz aos estudos arcanos no Sacrário dos Teurgos, Ventobravo permanece como o centro supremo de comércio, cultura e defesa pelos mares do sul."},{t="Sombras na Bastilha",b="A discórdia que aflige o reino não é mero acidente administrativo. Lady Katrana Prestor vem guiando secretamente as decisões da Casa dos Nobres, inflamando a hostilidade contra os pedreiros e deliberadamente negligenciando apelos por socorro militar de assentamentos periféricos como Cerro Oeste e as Montanhas Cristarrubra. Sussurrando veneno aos ouvidos do Grão-lorde Bolvar e dividindo a atenção do reino, ela trabalha para manter as legiões de Ventobravo ociosas e desunidas, enquanto a agitação que se fermenta além das muralhas da cidade ameaça o próprio trono."}},faq={{q="Quem governa Ventobravo no momento?",a="O Príncipe Anduin Wrynn, de dez anos de idade, detém a coroa, mas o governo de fato é conduzido pelo Grão-lorde Bolvar Fordragon, que atua como Regente de Ventobravo e comandante supremo de suas forças armadas. Bolvar depende fortemente dos conselhos da conselheira real Lady Katrana Prestor enquanto o Rei Varian Wrynn permanece desaparecido.",al={"rei atual","quem é o rei","quem lidera ventobravo","rei de ventobravo"}},{q="O que aconteceu com o Rei Varian Wrynn?",a="O Rei Varian desapareceu sob circunstâncias suspeitas enquanto viajava de navio para uma conferência diplomática em Theramore. Seu sumiço foi mantido em segredo para preservar a estabilidade, embora rumores corram soltos pelas ruas e pelo campo.",al={"onde está varian","rei desaparecido","sumiço de varian","varian wrynn desaparecido"}},{q="Por que a cidade foi reconstruída, e por quem?",a="A cidade original foi completamente queimada pela Horda Órquica durante a Primeira Guerra. Após a Segunda Guerra, a Guilda dos Pedreiros, liderada pelo mestre artífice Edwin VanCleef, reconstruiu minuciosamente a capital em pedra branca reluzente, com apoio financeiro da Aliança de Lordaeron.",al={"quem reconstruiu ventobravo","guilda dos pedreiros","nova ventobravo","reconstrução da cidade"}},{q="Por que os pedreiros se rebelaram contra a coroa?",a="A Casa dos Nobres acumulou dívidas vultosas expandindo as forças armadas de Ventobravo e se recusou a pagar os salários prometidos à Guilda dos Pedreiros. Quando Edwin VanCleef exigiu a compensação, os nobres dissolveram a guilda. Os trabalhadores se amotinaram, e os pedreiros exilados formaram a Irmandade Défias.",al={"origem dos défias","por que os défias estão revoltados","revolta dos pedreiros"}},{q="Quem são as estátuas gigantes no Vale dos Heróis?",a="As estátuas homenageiam os Filhos de Lothar: General Turalyon, Capitã-patrulheira Alleria Correventos, Arquimago Hadggar, Kurdran Martelo Feroz e Danath Matatroll. Elas foram erguidas para homenagear os heróis que se aventuraram pelo Portal Negro rumo a Draenor para selar a fenda e proteger Azeroth.",al={"estátuas na entrada","estátuas do vale dos heróis","estátuas dos filhos de lothar"}},{q="Como Ventobravo se conecta a Altaforja?",a="Ventobravo é conectada a Altaforja pelo Metrô Correfundo, uma ferrovia subterrânea construída pelo Grão-mecânico Gelbin Mekkatorque e encomendada pelo Rei Magni Barbabronze para viabilizar o comércio ágil e o rápido reforço militar entre ambas as capitais.",al={"metrô correfundo","trem para altaforja","como chegar a altaforja"}},{q="Por que Ventobravo não está enviando tropas para ajudar Cerro Oeste e as Montanhas Cristarrubra?",a="A corte real, sob forte aconselhamento de Lady Katrana Prestor, insiste que a cidade não pode dispensar tropas de suas próprias muralhas e fronteiras imediatas. Com as finanças do reino sob pressão e disputas políticas paralisando a Casa dos Nobres, as cidades regionais foram abandonadas à própria sorte, dependendo de milícias locais.",al={"exército de ventobravo desaparecido","por que não há ajuda para cerro oeste","reforços recusados"}}},fx={["9beefbfb"]={q="O que é Ventobravo?",a="Ventobravo é a capital do reino humano de Ventobravo e o maior bastião da humanidade que resta em Azeroth. Construída ao norte da Floresta de Elwynn ao longo da costa, ela serve como o coração pulsante, porto principal e centro cultural da Grande Aliança. Reconstruída das cinzas da Primeira Guerra, suas muralhas de pedra fortificadas abrigam artesãos, estudiosos, soldados e refugiados que veem a cidade como um símbolo da perseverança humana.",al={"sobre ventobravo","capital ventobravo","o que é ventobravo"}},edb1c1aa={q="O que aconteceu com Ventobravo no passado?",a="Originalmente fundada há mais de mil anos pelos descendentes da linhagem de Arathor, o reino prosperou por séculos através de conflitos com gnolls e trolls da selva. No entanto, durante a Primeira Guerra, a Horda Orc sitiou a capital. Após o trágico assassinato do Rei Llane Wrynn, a cidade foi invadida, saqueada e queimada até o chão. Sir Anduin Lothar liderou os refugiados sobreviventes para o norte através do mar até Lordaeron, retornando apenas após a Segunda Guerra para recuperar sua terra natal e reconstruí-la.",al={"história de ventobravo","destruição de ventobravo","primeira guerra ventobravo"}},d0a4b7c8={q="Ventobravo é perigosa?",a="Atrás de seus portões colossais e da vigilante Guarda da Cidade, Ventobravo é um dos santuários mais fortemente fortificados do mundo. No entanto, perigos ocultos permanecem dentro. O Cárcere vizinho viu motins violentos, cultistas e ladrões rondam os canais sombrios, e a agitação política provocada pela Irmandade Défias mantém a Casa dos Nobres inquieta. Embora a guerra aberta raramente rompa os muros, corrupção, traição e conspirações ocultas sussurram tanto na Fortaleza quanto nos becos.",al={"ventobravo é seguro","perigo em ventobravo","ameaças a ventobravo"}},["163d181d"]={q="O que é a Irmandade Défias?",a="A Irmandade Défias é uma guilda impiedosa de fora da lei, bandidos, ladrões e piratas que ameaçam abertamente a estabilidade do reino. Eles são reconhecíveis por suas bandanas vermelhas características, usadas para simbolizar o sangue derramado por sua causa. Embora operem fortemente a partir de Cerro Oeste, Montanhas Cristarrubra e das Minas Mortas, seu alcance se estende diretamente até Ventobravo, onde seus espiões e simpatizantes minam a autoridade da coroa e semeiam a discórdia entre as classes trabalhadoras.",al={"irmandade défias","quem são os defias","gangue defias"}},b1d432aa={q="O que é a Catedral da Luz?",a="Elevando-se acima da Praça da Catedral, a Catedral da Luz é o centro espiritual proeminente para a humanidade e a Grande Aliança. Reconstruída após a Segunda Guerra sob o Arcebispo Alonsus Faol e o então bispo Benedictus, ela serve como a sede da Igreja da Sagrada Luz e um quartel-general para a Ordem do Punho de Prata. Paladinos e sacerdotes viajam de todos os reinos para treinar, buscar sabedoria e meditar dentro de seus grandes e pacíficos salões.",al={"catedral da luz","catedral de ventobravo","igreja da luz ventobravo"}},["3414b788"]={q="Como vim parar em Ventobravo?",a="Se você começou sua jornada em Vila Norte e trabalhou seu caminho pela Floresta de Elwynn, a estrada principal o levou direto pelo Vale dos Heróis para os portões fortificados da capital. Se você vem de Dun Morogh ou de Altaforja, provavelmente embarcou no Metrô Correfundo, a maravilha da engenharia gnomica que liga a fortaleza anã diretamente ao Distrito dos Anões sob as montanhas. Viajantes de outros lugares de Azeroth chegam aos portões de Ventobravo após longas jornadas pelos reinos do sul, buscando o último grande bastião da humanidade.",al={"como vim parar aqui","como cheguei a ventobravo","como vou para ventobravo"}},["68c43aeb"]={q="O que devo fazer em Ventobravo?",a="Ventobravo é o coração pulsante da Aliança e um refúgio para descansar, treinar e se abastecer. Sob suas muralhas brancas reluzentes, no entanto, o reino está profundamente fraturado. O Rei Varian Wrynn desapareceu sob circunstâncias misteriosas, deixando o jovem rei Anduin e o Grão-lorde Bolvar Fordragon lutando contra a paralisia política na Fortaleza. Enquanto isso, as fronteiras circundantes em Cerro Oeste e nas Montanhas Cristarrubra clamam por ajuda contra o banditismo desenfreado, e a Irmandade Défias conspira nas sombras. Você está aqui para aprimorar seu ofício, reportar aos líderes de sua facção e emprestar sua espada a um reino sitiado.",al={"por que estou aqui","o que faço aqui","qual meu propósito em ventobravo"}}},fp="14,461,19.657.0,15.562.0,27.577.0,19.516.2,30.299.0,35.231.0,38.286.0,48.285.0,50.279.0,40.240.0,65.292.0"}
P.entries["zone:stranglethorn"] = {n="Selva do Espinhaço",s="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da Floresta do Crepúsculo. Outrora a sede do grande Império Gurubashi, a floresta tropical agora está repleta de ruínas de trolls em ruínas, feras selvagens e acampamentos rivais de goblins, piratas e soldados. O controle da região é disputado ferozmente por tribos de trolls locais, pela Empreendimentos S.A. e por facções rivais que tentam estabelecer pontos de apoio no calor da selva.",h="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da...",kw={"vela sangrenta","angra do butim","grom'gol","gurubashi","kurzen","nesingwary","rezingada","selva do espinhaço","empreendimentos s.a.","zul'gurub"},ang={["class:Hunter"]="A margem norte do rio abriga o famoso caçador de caça grossa Rosarães Guima, que desafia atiradores a testar sua coragem rastreando os mais ferozes raptores, panteras e crocoliscos da selva.",["faction:Alliance"]="Os esforços históricos de Ventobravo para conquistar e pacificar a selva sobrecarregaram o reino com pesadas dívidas e, hoje, seus interesses são defendidos apenas por amotinados em apuros no Acampamento dos Rebeldes.",["faction:Horde"]="O Acampamento Grom'gol oferece à Horda uma fortaleza estratégica indispensável no continente meridional, abastecida diretamente por zepelins de Durotar e da Cidade Baixa.",["profession:Herbalism"]="A copa úmida da floresta nutre uma flora valiosa, tornando as margens dos rios e as costas locais ideais para colher Ácera-agreste, Folha-da-névoa, Espinheira-dourada e Lótus Roxo.",["race:Troll"]="O Espinhaço é o berço ancestral dos trolls da selva, cujo antigo império Gurubashi sucumbiu à guerra civil após adorar Hakkar, o Esfolador de Almas, empurrando tribos como a Lançanegra para além dos mares."},sec={{t="Ruínas de um Império",b="Por milênios, a selva foi governada pelo poderoso Império Gurubashi a partir de sua capital, Zul'Gurub. Esse domínio se desfez quando sacerdotes radicais evocaram Hakkar, o Esfolador de Almas, mergulhando a região em uma guerra civil catastrófica. Embora os Zandalari tenham intervindo para esmagar a revolta do deus de sangue, o império se fragmentou de forma irreparável. Hoje, a selva está infestada por facções sucessoras em guerra — principalmente os Bloodscalp no noroeste e os Rachacrânio no leste —, ambas massacrando forasteiros com fervor para recuperar seu lar ancestral."},{t="Piratas e Exploradores",b="Onde as ruínas antigas jazem em silêncio, a ganância comercial preenche o vazio. No extremo sul fica a Angra do Butim, um refúgio movimentado construído pelo Cartel Bondebico e administrado pelos Blackwater Raiders sob o comando do Barão Rezingada. O porto serve como o principal centro do comércio do sul e do transporte marítimo, embora seja perpetuamente sitiado pelos rivais Bucaneiros da Vela Sangrenta, ancorados ao longo da costa. Mais para o interior, a Empreendimentos S.A. desmata a selva agressivamente em busca de madeira e minera as colinas atrás de raros cristais cantantes."},{t="Uma Terra Selvagem Disputada",b="A Selva do Espinhaço serve como uma das fronteiras mais voláteis do mundo. A Horda comanda o Acampamento Grom'gol na costa oeste, ligado por zepelins goblins a Durotar e às Clareiras de Tirisfal, enquanto legalistas da Aliança operam a partir do Acampamento dos Rebeldes para caçar o Coronel Kurzen, que desertou. Entre a folhagem densa, o lendário caçador Rosarães Guima lidera audaciosas expedições de caça grossa, atraindo viajantes a encontros perigosos com panteras à espreita, macacos enormes e soldados inimigos."},{t="A Loucura na Selva",b="Nem todas as ameaças no norte do Espinhaço são feras selvagens. O Coronel Kurzen, outrora um comandante condecorado enviado por Ventobravo, enlouqueceu na mata e estabeleceu um reduto mercenário tirânico. Na verdade, a mente de Kurzen foi enredada pela feitiçaria do Olho da Mente, um artefato empunhado pelo ogro mago Mai'Zoth, da vizinha Gruta de Mosh'Ogg, mergulhando a expedição em pura insanidade e levando seus antigos homens a formar o dissidente Acampamento dos Rebeldes."}},faq={{q="Quem controla a Selva do Espinhaço?",a="Nenhum poder único governa a selva. A região é dividida entre tribos rivais de trolls da selva, como os Bloodscalp e os Rachacrânio, acampamentos renegados como o Complexo do Kurzen, os mercenários da Empreendimentos S.A. e postos militares dispersos da Horda e da Aliança. O maior assentamento urbano é o porto goblin neutro da Angra do Butim, governado pelo Barão Rezingada e pelos Blackwater Raiders.",al={"quem controla a selva do espinhaço","quem governa a selva do espinhaço","facções da selva do espinhaço"}},{q="O que é a Angra do Butim?",a="A Angra do Butim é uma ampla cidade portuária construída nos penhascos ao sul do Cabo do Espinhaço. Originalmente um assentamento humano conhecido como Angra Aguanegra, foi capturada por trolls e, com o tempo, garantida pelo Cartel Bondebico. Hoje, o Barão Rezingada e o Mestre de Frota Chifre do Mar a administram como um porto comercial neutro que conecta viajantes à Vila Catraca através do Grande Oceano.",al={"o que é angra do butim","porto de angra do butim","quem comanda angra do butim"}},{q="Por que o Coronel Kurzen desertou?",a="O Coronel Kurzen liderou uma expedição à selva em nome de Ventobravo, mas sua mente sucumbiu à influência de Mai'Zoth, um ogro mago que empunhava uma poderosa relíquia chamada Olho da Mente. Kurzen tornou-se cada vez mais errático e despótico, forçando soldados leais, como o Tenente Doren, a romper laços e formar o Acampamento dos Rebeldes para detê-lo.",al={"por que kurzen é mau","o que aconteceu com kurzen","história de kurzen"}},{q="O que é Zul'Gurub?",a="Zul'Gurub é a antiga capital do Império Gurubashi, repleta de templos e encravada no nordeste da Selva do Espinhaço. Foi o epicentro da guerra civil que destruiu o império quinze séculos atrás, após sacerdotes radicais evocarem o deus de sangue Hakkar, o Esfolador de Almas. Embora abandonada há muito tempo às trepadeiras e ruínas, rituais sombrios continuam a ameaçar seus salões.",al={"o que é zg","história de zul'gurub","capital dos gurubashi"}},{q="O que era a Pedra das Marés?",a="A Pedra das Marés é uma relíquia lendária da história antiga dos Gurubashi, descoberta na costa por um guerreiro troll. Ela concedia ao seu portador domínio sobre a água e invocações elementais semelhantes às de um poderoso mago, rendendo ao usuário o título de 'Portador das Marés'. No entanto, carregava uma maldição que fazia o portador desaparecer lentamente do reino físico, levando cada usuário a caminhar em direção ao mar e sumir para sempre.",al={"pedra das marés","lenda do portador das marés","pedra da água gurubashi"}},{q="Como viajo até a Selva do Espinhaço?",a="Os viajantes podem caminhar para o sul atravessando a fronteira do rio a partir da Floresta do Crepúsculo até o norte da Selva do Espinhaço. A Horda mantém torres diretas de zepelim conectando o Acampamento Grom'gol a Durotar e às Clareiras de Tirisfal. Viajantes de Kalimdor também podem embarcar na embarcação mercante regular que navega entre a Vila Catraca, nos Sertões, e a Angra do Butim.",al={"como chegar à selva do espinhaço","chegar à selva do espinhaço","viagem selva do espinhaço"}}},fp="18,435,18.552.0,22.509.0,22.494.0,25.463.1,32.373.0,18.360.0,32.325.1,18.354.0,32.393.0,38.317.0"}
P.entries["zone:swampofsorrows"] = {n="Pântano das Mágoas",s="O Pântano das Mágoas é uma área úmida turva e salobra situada entre a Trilha do Vento Morto e a árida Barreira do Inferno. Antigamente a extensão norte do antigo Pântano Negro, seus pântanos incrustados de sal abrigam uma fauna perigosa, dragonspawn verdes e o arruinado Templo de Atal'Hakkar, submerso sob o Poço de Lágrimas. Enquanto a Horda mantém a guarnição fortificada de Pedregal, a Aliança não possui nenhum refúgio seguro no lodaçal, deixando a vastidão selvagem em grande parte indomada.",h="O Pântano das Mágoas é uma área úmida turva e salobra situada entre a Trilha do Vento Morto e a árida...",kw={"black morass","broken","o refúgio","os perdidos","poço de lágrimas","penumbra das mágoas","pedregal","templo submerso","pântano das mágoas","templo de atal'hakkar"},ang={["faction:Alliance"]="Sem um posto avançado para servir de base, viajar pelo pântano é uma empreitada isolada e hostil que exige preparação cuidadosa a partir de Vila Sombria ou da Bastilha de Etergarde.",["faction:Horde"]="Pedregal serve como seu reduto avançado vital no continente meridional, oferecendo rotas diretas de mantícora para Karrath, Monte Candente, Acampamento Grom'gol, Angra do Butim e Rog'mar nas Sendas do Rio.",["profession:Blacksmithing"]="Aventureiros resistentes podem coletar ferro, ouro, mithril e truesilver ao longo dos penhascos montanhosos que emolduram as bordas norte e sul do pântano.",["profession:Herbalism"]="O pântano é um dos poucos lugares em Azeroth rico em blindweed, além de generosas vegetações de liferoot, fadeleaf e stranglekelp.",["race:Troll"]="As ruínas submersas de Atal'Hakkar permanecem como uma terrível lembrança da magia de sangue sombria que fragmentou o Império Gurubashi e atraiu a ira dos Aspectos Dragônicos."},sec={{t="Uma História Submersa",b="Muito antes da chegada da Horda dos Orcs, estes pântanos formavam a metade norte de uma enorme área úmida conhecida como Pântano Negro. Após a fragmentação do Império Gurubashi, os fanáticos trolls Atal'ai fugiram para o lodaçal para erguer o Templo de Atal'Hakkar, com a intenção de evocar seu sanguinário loa, Hakkar, o Esfolador de Almas. Pressentindo a catástrofe, o Aspecto Ysera libertou seus poderes, afundando a pirâmide amaldiçoada sob as águas do Poço de Lágrimas. Guardiões da Revoada Dragônica Verde liderados por Eranikus foram posicionados para vigiar atentamente a estrutura submersa. Mais tarde, quando o cataclismo do Portal Negro crestou o pântano meridional, transformando-o na Barreira do Inferno, este charco ao norte ganhou seu atual e melancólico nome."},{t="Postos Avançados e Exilados Broken",b="Pedregal serve como o principal ponto de apoio civilizado no pântano. Originalmente estabelecido durante a First War ao lado dos assentamentos agora arruinados de Rockard e Kyross, o posto avançado foi reconstruído sob o comando de Thrall para servir como o ponto de concentração mais ao sul da Horda nos Reinos do Leste. Além das paliçadas de Pedregal, viajantes estranhos vagam pelo charco. Um grupo de retardatários draenei isolados em Azeroth sucumbiu à saudade de casa e à loucura, degenerando em ferozes Perdidos. No entanto, um pequeno enclave de exilados Broken lúcidos resiste no Refúgio, cautelosos, mas dispostos a negociar pacificamente com viajantes."},{t="O Lodaçal que Afunda",b="Sobreviver no pântano exige vigilância constante contra sua fauna predatória. Pântanos profundos escondem crocoliscos em investida, aranhas venenosas, jaguares-do-pântano à espreita e bestas-do-lodo errantes incrustadas de detritos pantanosos. Cavernas costeiras e a Praia Brumalga estão infestadas de murlocs ferozes, enquanto a maré carregada de sal avança continuamente terra adentro, preservando troncos podres sob grossas crostas salobras. Mais ao leste fica a Penumbra das Mágoas, onde dragonspawn de elite agressivos guardam ferozmente os acessos ao Templo Submerso, atacando qualquer um que se aproxime de sua vigília."}},faq={{q="Como chego ao Pântano das Mágoas?",a="A rota terrestre mais comum segue para o leste a partir de Vila Sombria, na Floresta do Crepúsculo, atravessando o perigoso e assombrado desfiladeiro da Trilha do Vento Morto e descendo direto para o pântano. Como alternativa, viajantes vindos do sul podem caminhar para o norte pela estrada principal que sai da Barreira do Inferno.",al={"como chegar ao pântano das mágoas","estrada do pântano das mágoas","como chegar a pedregal"}},{q="Por que o Templo de Atal'Hakkar está debaixo d'água?",a="Séculos atrás, o sacerdócio Atal'ai tentou evocar Hakkar, o Esfolador de Almas para Azeroth. Ysera, o Aspecto Dragônico da Revoada Verde, descobriu seus ritos de sangue demoníacos e afundou o templo inteiro no pântano para evitar o desastre, deixando para trás dragonspawn verdes para guardar os salões submersos.",al={"por que o templo submerso afundou","quem afundou o templo","história do templo submerso"}},{q="O que é Pedregal?",a="Pedregal foi um dos primeiros assentamentos construídos pela Horda dos Orcs após cruzar o Portal Negro durante a First War. Embora tenha sido devastado durante os combates, foi recentemente retomado e reconstruído sob as ordens de Thrall para ancorar a logística da Horda perto da Barreira do Inferno.",al={"história de pedregal","base orc no pântano","quem construiu pedregal"}},{q="Existe algum assentamento da Aliança aqui?",a="Não. A Aliança não mantém cidades, guardas ou rotas de voo no Pântano das Mágoas. Aventureiros da Aliança operando na área devem se estabelecer a partir de Vila Sombria, na Floresta do Crepúsculo, a oeste, ou da Bastilha de Etergarde, na Barreira do Inferno, ao sul.",al={"base da aliança no pântano das mágoas","rota de voo da aliança no pântano","onde fica o acampamento da aliança"}},{q="Quem são os estranhos humanoides mutantes no pântano?",a="Eles são draenei que ficaram isolados em Azeroth após o colapso do Portal Negro. Separados de seu mundo, a maioria enlouqueceu de desespero e se transformou em hostis Perdidos. Um pequeno grupo de exilados Broken sãos se refugiou a noroeste, no Refúgio, escolhendo a sobrevivência neutra em vez da fúria cega.",al={"quem são os perdidos","o que é o refúgio","draenei no pântano"}},{q="O que é a Penumbra das Mágoas?",a="A Penumbra das Mágoas é a densa faixa de pântano situada diretamente a leste do Poço de Lágrimas. Ela serve como área de patrulha para dragonspawn verdes de elite e filhotes que repelem mortais violentamente para proteger os segredos do Templo Submerso.",al={"área dos dragões no pântano das mágoas","dragões da penumbra das mágoas","dragonspawn verdes no pântano"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris é um deserto vasto e sufocante que se estende pelos limites meridionais de Kalimdor, caracterizado por dunas de areia ondulantes e um calor abrasador. No seu coração fica Geringontzan, um entreposto comercial neutro administrado pelos goblins do Cartel Bondebico. Além dos povoados movimentados, as dunas ocultam trolls da areia hostis, perigosas colmeias de silitídeos e o domínio oculto da revoada dragônica bronze.",h="Tanaris é um deserto vasto e sufocante que se estende pelos limites meridionais de Kalimdor, caracterizado...",kw={"cavernas do tempo","deserto","freebooters","geringontzan","nozdormu","fúria da areia","silitídeo","bondebico","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Sem grandes fortalezas da Aliança entre o Pântano Vadeoso e Feralas, o mestre de voo da Aliança na neutra Geringontzan serve como um ponto de apoio vital para viagens pelo sul de Kalimdor.",["faction:Horde"]="Geringontzan oferece aos batedores da Horda um conveniente entreposto comercial que liga as rotas da Aldeia Vento Livre e da Aldeia Mojache diretamente aos ermos infestados de silitídeos do extremo sul.",["profession:Herbalism"]="O calor seco nutre a esquiva Ignídea pelas dunas movediças, enquanto ruínas sombreadas e oásis úmidos fornecem abrigo para o valioso Lótus Roxo.",["profession:Mining"]="Os penhascos áridos e afloramentos rochosos que cercam as dunas oferecem ricas jazidas de Mítril, Veraprata, Ferro e Ouro, além de depósitos dispersos de Tório Pequeno nas regiões mais profundas.",["race:Troll"]="Ver os Sandfury de Zul'Farrak oferece aos trolls um vislumbre cru de seus primos ancestrais, que se endureceram em uma cultura brutal no isolamento do deserto."},sec={{t="Um Mar de Dunas",b="Tanaris é uma vastidão árida e crestada pelo sol. Dentro da cidade murada de Zul'Farrak, os calejados trolls Sandfury guardam seu domínio isolado. Hoje, o chão do deserto é dominado por hienas, basiliscos e escorpidídeos, enquanto túneis subterrâneos serpenteiam sob a terra escaldante."},{t="Empreendimento Goblin",b="Como Tanaris fica tão perto de Kezan, sua terra natal insular, quanto o continente permite, o Cartel Bondebico estabeleceu um próspero empreendimento aqui. Do oásis murado de Geringontzan às docas litorâneas do Porto de Bondebico, os goblins mantêm estrita neutralidade, acolhendo as moedas tanto da Aliança quanto da Horda. Sua paz é mantida pela força bruta dos seus capangas, embora ameaças desonestas como os Southsea Freebooters hostilizem constantemente o transporte marítimo e os sítios de escavação ao longo da costa."},{t="Mistérios Antigos e Perigos Crescentes",b="As areias escondem poderes muito mais antigos do que os impérios mortais. Nos confins orientais ficam as Cavernas do Tempo, o domínio ancestral de Nozdormu e de sua revoada dragônica bronze, cujos draconídeos ocasionalmente podem ser vistos planando nas correntes térmicas do deserto. Ao sul, imponentes portões de pedra marcam o complexo titânico de Uldum. No entanto, um perigo mais sombrio se agita em ninhos subterrâneos como a Fenda Hazzali e o Covil Nóxio, onde enxames rastejantes de silitídeos começaram a cavar para fora através das areias."}},faq={{q="Como viajo para Tanaris?",a="Viajantes a pé viajam através das Mil Agulhas até a Chapada Cintilante. Uma passagem na montanha esculpida através dos penhascos no extremo sul das salinas leva diretamente para baixo no deserto, deixando você imediatamente à vista das muralhas de Geringontzan. Um navio também navega do Porto Detonapavio nas Sendas do Rio até o Porto de Bondebico na costa leste.",al={"como chegar a tanaris","chegando a tanaris","entrada de tanaris"}},{q="Por que Geringontzan é neutra para ambas as facções?",a="Geringontzan é governada pelo Cartel Bondebico, cuja única lealdade é ao lucro. Para maximizar o comércio e proteger as rotas comerciais pelo deserto, os goblins impõem uma neutralidade estrita, empregando capangas para espancar qualquer um tolo o bastante para iniciar brigas de facção dentro dos muros de sua cidade.",al={"por que geringontzan é neutra","a horda e a aliança podem ir a geringontzan","neutralidade dos goblins em geringontzan"}},{q="O que é Zul'Farrak?",a="Zul'Farrak é a capital desértica fortificada dos trolls Sandfury. Isolada há muito tempo no deserto, a tribo Sandfury tornou-se hostil a todos os forasteiros, guardando suas piscinas sagradas e santuários misteriosos contra aventureiros invasores.",al={"o que é zul'farrak","quem vive em zul'farrak","cidade dos trolls da areia"}},{q="O que são as criaturas insetoides que fazem ninhos pelo deserto?",a="As criaturas insetoides são silitídeos, escavadores coloniais monstruosos que constroem vastas colmeias como a Fenda Hazzali e o Covil Nóxio. Sua presença emergente em Tanaris inquietou observadores como o Topógrafo Sênior Secamolha, lembrando os horrores antigos da Guerra das Areias Movediças.",al={"o que são os insetos em tanaris","colmeias de insetos em tanaris","silitídeos em tanaris"}},{q="O que há por trás das gigantescas portas de pedra no sul?",a="Os portões monumentais no Vale dos Vigilantes marcam a entrada para Uldum, uma lendária instalação de pesquisa e propriedade dos antigos titãs. A entrada permanece firmemente selada, guardada por colossais sentinelas de pedra e examinada de longe por estudiosos curiosos e goblins.",al={"portões gigantes no sul de tanaris","portões de ruínas de Uldum","portão dos titãs em tanaris"}},{q="Quem habita as Cavernas do Tempo?",a="As Cavernas do Tempo servem como o covil ancestral da revoada dragônica bronze e de seu aspecto, Nozdormu. A partir dessas profundezas ocultas e sinuosas, os dragões atemporais vigiam o fluxo da história, ocasionalmente patrulhando os céus bem acima das dunas do sul.",al={"história das cavernas do tempo","o que há nas cavernas do tempo","dragões em tanaris"}}},fp="7,385,14.269.0,17.488.0,35.467.0,27.355.0,42.292.0,19.228.0,56.294.0,52.271.0,38.255.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste de Kalimdor. Cultivada pelos druidas no rescaldo da Terceira Guerra, seus galhos monumentais sustentam uma vasta natureza selvagem sob a penumbra e Darnassus, a capital dos elfos noturnos. No entanto, sob sua copa tranquila e banhada pelo luar, uma corrupção rastejante começou a se agitar.",h="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste...",kw={"círculo dos ancientes","coroa da terra","darnassus","dolanaar","fandral guenelmo","rut'theran","umbravale","teldrassil","arvore do mundo"},ang={["class:Druid"]="Com Malfurion preso no Sonho Esmeralda, o Arquidruida Fandral Guenelmo lidera o Círculo Cenariano aqui, embora muitos druidas temam que Teldrassil tenha sido erguida às pressas.",["faction:Alliance"]="Teldrassil serve como o reduto mais ao norte da Aliança em Kalimdor, ancorando a comunicação naval e o comércio entre Darnassus e os reinos do continente.",["profession:Herbalism"]="Sem nenhum mineral ou minério, a copa verdejante da árvore compensa isso ao funcionar como um paraíso para coletores de Botão-da-paz, Folha-prata e Raiz-da-terra.",["race:NightElf"]="Esta árvore colossal é o novo recomeço do seu povo após a devastação do Monte Hyjal, mas a ausência das bênçãos dos Aspectos torna sua defesa um dever urgente."},sec={{t="Uma Copa Sobre o Mar",b="Teldrassil não é apenas uma árvore; é um ecossistema elevado que se ergue imponente em meio às águas do Mar Velado. Seus galhos descomunais abrigam colinas ondulantes, rios caudalosos alimentados pelo orvalho da manhã, lagos enevoados e clareiras ancestrais densas. Em sua extremidade ocidental fica Darnassus, a grandiosa capital dos kaldorei. Na base de seu tronco monumental está a Vila de Rut'theran, conectada à copa por um portal místico e servindo como o principal porto da ilha."},{t="A Recusa dos Aspectos",b="Após o sacrifício de Nordrassil durante a Terceira Guerra e o misterioso desaparecimento do Shan'do Malfurion Tempesfúria no Sonho Esmeralda, o Arquidruida Fandral Guenelmo convenceu o Círculo dos Ancientes a plantar uma substituta. Guenelmo esperava devolver aos kaldorei sua imortalidade perdida. No entanto, Nozdormu e os Aspectos Dragônicos consideraram a iniciativa arrogante e recusaram suas bênçãos. Sem essa proteção vital, o crescimento de Teldrassil sofreu com imperfeições não naturais."},{t="Uma Enfermidade Rastejante",b="Apesar de sua majestade exterior, a jovem Árvore do Mundo abriga uma enfermidade sombria. A fauna local se tornou violenta: tribos outrora pacíficas de furbolgs caíram na loucura, grells deformados se multiplicam nos túmulos e sátiros vis realizam ritos sombrios em recessos como a Pedra Vil. Mais abaixo, nas praias de Costa Negra, gigantes do mar, debulhadores e tartarugas encalham para fugir das águas contaminadas ao redor da árvore. Naturalistas e sentinelas agora trabalham freneticamente pela copa para identificar a sombra que lentamente estrangula seu novo lar."}},faq={{q="Por que Teldrassil foi cultivada?",a="Depois que Nordrassil foi devastada no final da Terceira Guerra, os elfos noturnos perderam sua imortalidade. O Arquidruida Fandral Guenelmo pressionou o Círculo dos Ancientes e os druidas cenarianos a plantar uma nova Árvore do Mundo no mar, com o objetivo de restaurar o que seu povo havia perdido.",al={"por que foi feita","quem criou teldrassil","origem de teldrassil"}},{q="Por que Teldrassil não restaurou a imortalidade dos elfos noturnos?",a="Nordrassil concedia a imortalidade originalmente porque Nozdormu, o Atemporal, a abençoou. Quando Teldrassil foi erguida, Nozdormu julgou o desejo dos elfos noturnos como arrogante e se recusou a conceder sua bênção à nova árvore.",al={"imortalidade","por que nao sao imortais","bencao de nozdormu"}},{q="Como sair de Teldrassil?",a="Os viajantes devem atravessar Darnassus até o portal rosa nos Jardins do Templo, que os transporta para a Vila de Rut'theran na base do tronco. De Rut'theran, um navio navega pelo mar até Auberdine, no continente de Costa Negra, além das rotas de hipogrifos disponíveis.",al={"como sair","sair da arvore","barco de teldrassil"}},{q="Por que não há jazidas de mineração em Teldrassil?",a="Toda a zona se situa sobre os galhos vivos e a madeira de uma colossal Árvore do Mundo, em vez de rocha continental natural. Como não há crosta subterrânea rochosa, veios de metal ou depósitos de minério não se formam aqui, embora as ervas floresçam em grande abundância.",al={"onde tem cobre","sem minerio","mineracao em teldrassil"}},{q="O que está fazendo os furbolgs e as feras enlouquecerem?",a="Uma presença sinistra começou a se infiltrar nas raízes não abençoadas de Teldrassil. A doença corrompeu as águas e a flora locais, levando os outrora pacíficos lenhosos e a tribo furbolg Gnarlpine a uma agressividade frenética, enquanto remanescentes de sátiros cultivam ativamente a corrupção.",al={"furbolgs corrompidos","gnarlpine loucos","o que e a corrupcao"}},{q="O que é Umbravale?",a="Umbravale é um vale protegido e isolado nos galhos orientais de Teldrassil, ao redor da grande árvore Aldrassil. Ele serve como um santuário tranquilo onde os jovens elfos noturnos iniciam seu treinamento antes de se aventurarem pelo mundo afora.",al={"umbravale","area inicial","zona de aldrassil"}}},fx={["11a6d5e5"]={q="O que é Teldrassil?",a="Teldrassil é uma imensa Árvore do Mundo cultivada em uma ilha na costa noroeste de Kalimdor. Seu tronco gigantesco ergue-se do Mar Velado, espalhando-se em galhos tão vastos que sustentam um reino florestal inteiro de lagos, rios e a capital de Darnassus no topo de sua copa.",al={"o que é este lugar","sobre teldrassil","me conte sobre teldrassil"}},["313cd5a2"]={q="O que aconteceu em Teldrassil?",a="Após a Terceira Guerra e os danos causados a Nordrassil do Monte Hyjal, o druida Malfurion Tempesfúria desapareceu. Na ausência dele, o Arquidruida Fandral Guenelmo convenceu o Círculo dos Anciões a cultivar uma nova Árvore do Mundo para substituir o que foi perdido. Embora tenha crescido com sucesso, uma corrupção rastejante começou desde então a manchar seus galhos.",al={"história de teldrassil","como teldrassil foi criada","eventos de teldrassil"}},c5e34e84={q="Quem vive ou administra Teldrassil?",a="Teldrassil é o refúgio ancestral e a atual pátria dos elfos noturnos. Espiritual e civicamente, a Alta Sacerdotisa Tyrande Murmuréolo e o Arquidruida Fandral Guenelmo guiam seu povo a partir da capital de Darnassus, apoiados pela Irmandade de Eluna, druidas Cenarianos e guerreiros Sentinelas protegendo os assentamentos na floresta.",al={"quem lidera teldrassil","líderes de teldrassil","quem vive aqui"}},b86e706e={q="Teldrassil é perigosa?",a="Embora protegida pelas Sentinelas, Teldrassil é cada vez mais perigosa. Uma aflição sombria enlouqueceu as feras nativas e os furbolgs locais, enquanto sátiros maliciosos, harpias sanguinárias e timberlings desenfreados ameaçam os assentamentos além das estradas patrulhadas.",al={"é seguro aqui","ameaças em teldrassil","perigos de teldrassil"}},["2863bed2"]={q="Por que se chama Teldrassil?",a="Na língua Darnassiana dos elfos noturnos, Teldrassil traduz-se diretamente como 'coroa da terra'. Foi nomeada em homenagem ao seu papel como uma Árvore do Mundo monumental destinada a acolher e proteger sua civilização.",al={"o que significa teldrassil","significado do nome teldrassil"}},["514d23b0"]={q="Quem é Fandral Guenelmo?",a="Fandral Guenelmo é o Arquidruida que assumiu a liderança dos druidas elfos noturnos após o desaparecimento de Malfurion Tempesfúria no Sonho Esmeralda. Apaixonado, teimoso e agressivo, Fandral defendeu o plantio de Teldrassil e frequentemente entra em conflito com a Alta Sacerdotisa Tyrande Murmuréolo sobre políticas.",al={"quem é o arquidruida","lore de fandral guenelmo","guenelmo"}},["52c333ac"]={q="Quem é Tyrande Murmuréolo?",a="Tyrande Murmuréolo é a Suma Sacerdotisa da deusa Eluna e líder suprema do povo elfo noturno. Tendo guiado seu povo por dez mil anos através da Longa Vigília e da Terceira Guerra, ela agora governa a partir do Templo da Lua em Darnassus.",al={"quem é tyrande","suma sacerdotisa tyrande","quem lidera os elfos noturnos"}},["29b1e9e4"]={q="Como vim parar em Teldrassil?",a="Se você é um elfo noturno, esta colossal Árvore do Mundo é o novo lar do seu povo. Após sacrificar Nordrassil e sua antiga imortalidade no topo do Monte Hyjal para derrotar a Legião Ardente, os kaldorei se realocaram na costa noroeste de Kalimdor. O Arquidruida Fandral Guenelmo e o Círculo dos Anciões cultivaram Teldrassil no Mar Velado para dar à sua raça um refúgio renovado, e você começou sua jornada dentro de seus galhos verdejantes em Umbravale. Se você viajou para cá do exterior, provavelmente navegou até o porto da Vila de Rut'theran na base da árvore vindo da Costa Negra, depois passou pelo portal brilhante que leva os viajantes diretamente para a copa.",al={"como cheguei a teldrassil","como cheguei aqui","por que estou começando aqui"}},["8381279f"]={q="O que devo fazer em Teldrassil?",a="Você foi chamado para proteger a jovem Árvore do Mundo e descobrir a doença sombria que perturba seus galhos. Apesar de suas florestas exuberantes, uma corrupção sinistra está se instalando: os timberlings estão se tornando agressivos, os furbolgs pacíficos da tribo Pinho Retorcido estão caindo na loucura, e sátiros vis espreitam em matagais sombrios como Pedra Vil. Começando em Umbravale e ajudando assentamentos como Dolanaar, você deve ajudar as Sentinelas e druidas a restaurar o equilíbrio. Você reabastecerá os Poços da Lua sagrados, erradicará a praga corrompida e aprenderá a história do seu povo antes de se aventurar na capital de Darnassus e atravessar o mar até o continente de Kalimdor.",al={"o que fazer em teldrassil","por que estou aqui","qual minha missão aqui"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="Mil Agulhas",s="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul de Kalimdor. Tribos de taurens se apegam a povoados no topo de imponentes platôs para escapar de bandos agressivos de centauros, enquanto engenhoqueiros gnomos e goblins pilotam carros-foguete em alta velocidade pelo leito marinho seco da Chapada Cintilante.",h="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul...",kw={"vigia do rochedo chifre longo","pináculo da nuvem negra","xabu latafuso","aldeia vento livre","o grande elevador","totem sombrio","kravel barbakarvão","circuito da ilusão","relé","chapada cintilante","mil agulhas"},ang={["faction:Horde"]="O Grande Elevador conecta os Sertões à sua fortaleza na Aldeia Vento Livre, funcionando como uma fronteira estratégica ao sul contra os clãs de centauros e os taurens rebeldes.",["profession:Engineering"]="As planícies de sal são um destino de peregrinação para engenhoqueiros que procuram estudar combustível de foguete, peças de veículos e propulsão de alta velocidade no Circuito da Ilusão.",["race:Gnome"]="O Circuito da Ilusão, na Chapada Cintilante, é a principal chance de sua facção demonstrar a precisão e a elegância da engenharia gnômica contra as engenhocas grosseiras dos goblins.",["race:Tauren"]="A Aldeia Vento Livre ergue-se como um lembrete do quão alto seu povo precisou subir para escapar do massacre dos centauros, servindo também de ponto de apoio contra os traiçoeiros Totem Sombrio no Pináculo da Nuvem Negra."},sec={{t="Uma floresta de pedra",b="Antes que a Grande Cisão despedaçasse a antiga Kalimdor, este território era um cânion fluvial verdejante alimentado por cursos d'água continentais que fluíam em direção ao mar. O cataclismo rasgou o continente, empurrando o leito do rio acima do lençol freático e alterando seu curso até restarem apenas pedra seca e pináculos de arenito. Hoje, dezenas de esguias colunas cilíndricas erguem-se do fundo do cânion como uma floresta petrificada. Os taurens se estabeleceram nos cumes, estendendo pontes de corda precárias entre os picos para criar aldeias fora do alcance dos saqueadores centauros hostis que patrulham o fundo sombrio do desfiladeiro."},{t="Perigo nos platôs",b="No topo dos pináculos em forma de agulha, a vida está longe de ser pacífica. Na Aldeia Vento Livre, os taurens leais à Horda enfrentam não apenas serpentes aladas predatórias e mantícoras de Alcândora, mas também seus próprios parentes traiçoeiros: o belicoso clã Totem Sombrio, entrincheirado no Pináculo da Nuvem Negra. O Vigia do Rochedo Chifre Longo supervisiona a defesa do platô, em busca de combatentes corajosos para atacar os agitadores Totem Sombrio e proteger as frágeis pontes que conectam os picos. Ao norte, os enormes guinchos mecânicos d'O Grande Elevador transportam viajantes a partir dos Sertões Meridionais, embora cruzar o fundo do cânion continue sendo uma empreitada mortal."},{t="O Circuito da Ilusão",b="A sudeste, os paredões do cânion se abrem para a Chapada Cintilante, uma enorme e ressecada planície de sal situada abaixo do nível do mar. Nessa extensão árida e de uma brancura ofuscante, gnomos e goblins mantêm uma neutralidade incômoda ao redor do Circuito da Ilusão. Engenheiros rivais, Relé e Xabu Latafuso, disputam corridas de carros-foguete experimentais sobre o sal duro para decidir qual raça detém a superioridade tecnológica. Essa parada atrai canalhas, vigaristas como Kravel Barbakarvão e caçadores em busca dos resistentes escorpiões, tartarugas e basiliscos que vagam pela bacia causticante."}},faq={{q="Como Mil Agulhas recebeu esse nome?",a="A zona deve seu nome às dezenas de pináculos cilíndricos colossais de arenito que brotam do fundo do cânion. Esculpidas originalmente pelas correntes caudalosas dos rios antes da Grande Cisão, essas torres geológicas hoje parecem uma floresta de agulhas gigantes.",al={"por que se chama mil agulhas","origem dos pilares de agulha","história dos pináculos"}},{q="Como se desce até Mil Agulhas vindo dos Sertões?",a="Os viajantes utilizam O Grande Elevador, uma imensa estrutura com duas cabines operada por guardas da Horda na fronteira sul dos Sertões. Saltar da beirada é fatal, portanto é essencial aguardar a plataforma. Os viajantes da Aliança também podem chegar a pé pelo oeste, passando por Thalanaar, em Feralas.",al={"como chegar em mil agulhas","entrada d'o grande elevador","elevador para mil agulhas"}},{q="Por que os taurens vivem no topo dos platôs?",a="Os bandos de guerra centauros quase levaram os nômades taurens à extinção no passado. Construir postos avançados como a Aldeia Vento Livre no alto de pilares de pedra inacessíveis os manteve a salvo de investidas terrestres. Eles conectaram os platôs por meio de pontes pênseis de madeira, possibilitando viagens em grandes altitudes, muito acima dos predadores e saqueadores lá embaixo.",al={"por que taurens ficam nos pilares","história da aldeia vento livre","terreno elevado dos taurens"}},{q="O que é o Circuito da Ilusão?",a="O Circuito da Ilusão é um campo de provas de engenharia situado na planície de sal da Chapada Cintilante. Engenhoqueiros gnomos e goblins apostam corrida com carros experimentais movidos a foguete pelo leito plano de sal para resolver a rivalidade de longa data sobre qual raça constrói as melhores máquinas.",al={"pista da chapada cintilante","corrida de gnomos e goblins","pista de carro-foguete"}},{q="Qual é a presença do Totem Sombrio no cânion?",a="O clã Totem Sombrio ocupa o Pináculo da Nuvem Negra, um conjunto fortificado de torres rochosas que se opõe diretamente à Aldeia Vento Livre. Ao contrário das demais tribos taurens que juraram lealdade à Horda, o Totem Sombrio ataca ativamente outros taurens e conspira para tomar o controle dos platôs.",al={"totem sombrio em mil agulhas","taurens do pináculo da nuvem negra","taurens malignos de agulhas"}},{q="O que é a Chapada Cintilante?",a="A Chapada Cintilante é o leito de um vasto lago seco a leste dos platôs do cânion. A crosta de sal formou-se quando as antigas águas continentais evaporaram após a Cisão. O calor escaldante, o sal de brancura ofuscante e os predadores implacáveis transformam o local em um deserto inóspito, utilizado principalmente para testes de veículos em alta velocidade.",al={"deserto de sal","deserto branco de mil agulhas","deserto oriental"}}},fx={d1fb42e2={q="O que são as Mil Agulhas?",a="Mil Agulhas é um cânion vasto e árido que divide o centro e o sul de Kalimdor. O chão do cânion é repleto de imponentes pináculos de arenito que se estendem em direção ao céu como uma floresta petrificada, ligados acima por delicadas pontes de corda e madeira. A leste, o cânion dá lugar à Chapada Cintilante, uma planície de sal branca e ofuscante.",al={"o que é este lugar","sobre mil agulhas","me conte sobre mil agulhas"}},["98fcff4e"]={q="Por que tudo são cânions e pilares?",a="Eras atrás, antes da Grande Fragmentação, esta região era um cânion fluvial verdejante esculpido por águas correntes que fluíam para o leste de Feralas até um mar interior. Quando o mundo se despedaçou, o cataclismo empurrou o leito do rio para cima e alterou o curso do rio. Privada de água, a terra secou, deixando para trás imponentes pilares de arenito e um leito de sal ressecado.",al={"por que existem pináculos","como as agulhas se formaram","por que pilares de arenito"}},["05d5c74f"]={q="As Mil Agulhas são perigosas?",a="É bastante perigoso. Centauros Galak bárbaros patrulham o chão do cânion em bandos de invasores, enquanto abutres predatórios, escorpídeos e harpias ladinas assombram os penhascos. Até mesmo as pontes de corda entre os pináculos altos carregam perigo, já que aves de rapina frequentemente descem sobre viajantes incautos ou danificam as extensões.",al={"quão perigosas são as mil agulhas","perigos aqui","é seguro"}},["1b8e8bea"]={q="Por que a Horda me enviou para as Mil Agulhas?",a="A Horda mantém uma presença vital aqui para ajudar as tribos tauren locais que estão sob ataque implacável. A Aldeia Vento Livre ergue-se como um baluarte crítico que conecta os Sertões aos desertos do sul, e a Horda precisa de bravos campeões para repelir os centauros saqueadores e suprimir ameaças internas.",al={"missão da horda em mil agulhas","por que estou aqui horda","o que a horda quer aqui"}},a7c3b539={q="Esta é uma terra tauren?",a="Sim. Os cânions áridos e as mesas altas das Mil Agulhas têm sido tradicionalmente o território ancestral de várias tribos tauren por inúmeras gerações, embora clãs cruéis de centauros os tenham levado à beira da sobrevivência antes da chegada da Horda.",al={"os tauren possuem mil agulhas","território tauren","isto é terra shu'halo"}},fef8bf7c={q="O que é a Aldeia Vento Livre?",a="A Aldeia Vento Livre é o principal posto avançado da Horda nas Mil Agulhas. Construída no topo de uma mesa enorme bem acima do chão do vale, ela possui elevadores de madeira, uma torre de voo e uma rede de pontes suspensas que alcançam os pináculos adjacentes.",al={"aldeia vento livre","o que é a aldeia vento livre"}},["6ac472b0"]={q="Quem são os centauros Galak e por que eles estão nos atacando?",a="A tribo Galak são os centauros locais que reivindicam o chão do cânion. Como todos os centauros, eles são ferozmente territoriais, nômades e violentos. Eles caçam qualquer viajante que passe pelas gargantas e buscam erradicar completamente os assentamentos tauren.",al={"centauros galak","por que centauros atacam","tribo galak"}},["9f0b1de8"]={q="Por que eles odeiam os tauren?",a="A inimizade entre tauren e centauros é antiga e implacável. Por gerações através das planícies de Kalimdor, centauros itinerantes caçavam tauren por esporte e lançavam guerras brutais e não provocadas que mantinham as tribos pacíficas constantemente em fuga.",al={"por que centauros odeiam tauren","rixa entre centauros e tauren","rancor dos centauros"}},["0eee4587"]={q="Por que goblins e gnomos estão correndo com carros foguete no deserto?",a="O sal plano e aberto da Chapada Cintilante fornece o campo de provas perfeito para testar motores de alta velocidade. Gnomos e goblins estabeleceram o Circuito da Ilusão para resolver permanentemente a longa disputa sobre qual raça possui a engenharia superior.",al={"por que carros de corrida","corrida de goblin e gnomo","rivalidade de carros foguete"}},e421f132={q="Qual é a história do Pináculo da Nuvem Negra e daquelas notas secretas?",a="O Pináculo da Nuvem Negra é a fortaleza fortemente guardada da tribo Totem Sinistro nas mesas a leste de O Grande Elevador. Correspondências secretas descobertas lá revelam contato secreto entre líderes dos Totem Sinistro, como Arnak Totem Sinistro, e uma força sombria desconhecida, sugerindo ambições traiçoeiras muito além de simples disputas tribais.",al={"notas do pináculo da nuvem negra","notas dos totem sinistro","mistério do pináculo da nuvem negra"}},["7b560411"]={q="O que os Totem Sinistro estão planejando?",a="Os Totem Sinistro rejeitam fundamentalmente a liderança de Caerne Casco Sangrento e as mudanças culturais trazidas pela adesão à Horda. Eles buscam depor Caerne, minar a autoridade da Horda e até mesmo manter contato com poderes sinistros e invocar entidades de vingança para afirmar seu domínio.",al={"plano dos totem sinistro","o que os totem sinistro querem","conspiração dos totem sinistro"}},["853c4dd1"]={q="O que é Alcândora e por que queremos ovos de serpe?",a="Alcândora é o local de nidificação ancestral de serpes selvagens nas Mil Agulhas. Tauren da Aldeia Vento Livre escalam esses puleiros altos para coletar ovos férteis de serpe para que possam ser cuidadosamente criados e treinados como montarias voadoras leais para a Horda.",al={"serpes de alcândora","por que coletar ovos de serpe","ovos de alcândora"}},dc3189d8={q="Como vim parar nas Mil Agulhas?",a="A maioria dos viajantes chega do norte cavalgando para o sul através dos Sertões, passando pelo Acampamento Taurajo, eventualmente alcançando a borda do penhasco íngreme onde o enorme O Grande Elevador, projetado pelos tauren, leva você diretamente para o chão do cânion. Alternativamente, aventureiros que caminham para o leste através das densas florestas de Feralas entram na garganta ocidental a pé, enquanto exploradores ousados que enfrentam os perigos do Pântano Vadeoso ou navegam até Theramore passam pelas lacunas disputadas. Uma longa marcha por terra ao norte dos desertos de Tanaris também o leva diretamente para a extensa planície de sal da Chapada Cintilante.",al={"como cheguei aqui","como chego às mil agulhas","chegando às mil agulhas"}},["16801326"]={q="O que devo fazer nas Mil Agulhas?",a="Sua presença aqui depende de suas lealdades e ambições. Campeões da Horda têm a tarefa de ajudar a Aldeia Vento Livre: repelir os bandos de centauros Galak que vagam pelo chão do cânion, monitorar os ninhos de harpias, coletar ovos de serpe de Alcândora e combater a traiçoeira tribo Totem Sinistro entrincheirada no topo do Pináculo da Nuvem Negra. Para andarilhos não alinhados e viajantes da Aliança, a extensão dramática serve como uma encruzilhada terrestre perigosa entre o centro e o sul de Kalimdor, levando à Chapada Cintilante, onde temerários goblins e gnomos pagam boas moedas por peças, combustível e assistência com sua eterna rivalidade de carros foguete.",al={"por que estou aqui","qual meu propósito aqui","o que fazer nas mil agulhas"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="Penhasco do Trovão",s="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha fustigados pelo vento que se erguem sobre as pradarias de Mulgore. Fundada pelo Grande Chefe Caerne Casco Sangrento após unir as tribos nômades com a ajuda da Nova Horda, ela serve como o coração cultural, espiritual e mercantil de seu povo. Conectada por pontes de corda oscilantes e elevadores de madeira, a cidade oferece proteção contra saqueadores centauros e um santuário pacífico para viajantes por toda Kalimdor.",h="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha...",kw={"caerne casco sangrento","platô dos anciãos","elevadores","hamuul runa totem","platô dos caçadores","magatha temível totem","mulgore","poços das visões","platô dos espíritos","penhasco do trovão"},ang={["class:Druid"]="O Platô dos Anciãos serve como o santuário supremo de magia da natureza da Horda, liderado pelo Arquidruida Hamuul Runa Totem, o primeiro druida tauren instruído em milhares de anos.",["class:Shaman"]="O Platô dos Espíritos e os subterrâneos Poços das Visões oferecem um elo sereno onde os espíritos elementais e os espíritos dos ancestrais taurens são reverenciados e ouvidos.",["faction:Horde"]="Muito mais tranquilo e espiritual do que as fortificações austeras de Orgrimmar, o Penhasco do Trovão atua como o alicerce pastoral da influência da Nova Horda no sul de Kalimdor.",["race:Tauren"]="O Penhasco do Trovão representa a duramente conquistada união e o renascimento do seu povo após gerações de vida nômade e perseguição pelos centauros, sob o comando do Grande Chefe Caerne Casco Sangrento."},sec={{t="Um Refúgio Permanente",b="Por incontáveis gerações, os taurens viveram como andarilhos nômades por toda Kalimdor, travando uma luta brutal pela sobrevivência contra tribos vorazes de centauros. Essa era desesperadora terminou durante a Terceira Guerra, quando Caerne Casco Sangrento uniu forças com o Chefe Guerreiro Thrall. Juntos, os orcs e taurens repeliram as investidas dos centauros e garantiram as pastagens verdejantes de Mulgore. Para proteger o futuro deles, Caerne conduziu as tribos aliadas à segurança desses bastiões de pedra naturais, fundando o Penhasco do Trovão como o primeiro lar unificado e permanente dos taurens em séculos."},{t="Uma Cidade nas Nuvens",b="Estendendo-se por vários platôs elevados conectados por pontes de corda suspensas, o Penhasco do Trovão mescla com perfeição a arquitetura natural com a praticidade tauren. Os platôs centrais abrigam os movimentados mercados, o banco, a estalagem e o imponente poleiro de Mantícoras, enquanto três platôs especializados se ramificam sobre o abismo. O Platô dos Caçadores serve aos batedores e rastreadores da cidade; o Platô dos Anciãos abriga os guardiões da história e o Círculo Cenariano sob a liderança do Arquidruida Hamuul Runa Totem; e o Platô dos Espíritos é dedicado à comunhão espiritual, acolhendo xamãs, sacerdotes e as misteriosas cavernas subterrâneas conhecidas como os Poços das Visões."},{t="União Inquieta",b="Embora Caerne Casco Sangrento imponha imenso respeito de quase todas as tribos, governar um povo orgulhoso e recém-estabelecido traz seus atritos. Notavelmente, a tribo Temível Totem — liderada pela perspicaz e mordaz Matriarca Magatha Temível Totem — mantém uma presença sombria no Platô dos Anciãos. Magatha questiona abertamente os métodos conciliatórios de Caerne e sua lealdade às raças estrangeiras da Horda. Embora a paz se mantenha sob o olhar vigilante do chefe, fendas ideológicas murmuram entre as fogueiras do conselho sobre as planícies."}},faq={{q="Quem governa o Penhasco do Trovão?",a="O Grande Chefe Caerne Casco Sangrento governa o Penhasco do Trovão e lidera as tribos taurens unidas. Reverenciado por sua sabedoria, paciência e força colossal, Caerne fundou a cidade após se aliar à Horda de Thrall e expulsar os centauros de Mulgore.",al={"líder do penhasco do trovão","quem governa","chefe do penhasco do trovão","caerne"}},{q="Como se sobe até o Penhasco do Trovão?",a="Visitantes que chegam a pé ou em kodos precisam usar elevadores maciços com plataformas de madeira localizados nos lados sudoeste e nordeste do platô central. Como alternativa, a cidade conta com um poleiro de Mantícoras com rotas de voo por toda Kalimdor.",al={"elevador do penhasco do trovão","como entrar","entrada do penhasco do trovão","como subir"}},{q="Por que os taurens construíram no topo de platôs em vez de no chão?",a="Séculos de existência nômade foram marcados por ataques implacáveis de guerrilha desferidos por clãs agressivos de centauros. Os penhascos íngremes dos platôs de Mulgore oferecem defesa natural, protegendo as habitações, ferrarias e sábios anciãos dos taurens contra emboscadas terrestres, permitindo que eles se estabeleçam de forma permanente em paz.",al={"por que platôs","por que ficam em penhascos","penhascos do penhasco do trovão","posição elevada dos taurens"}},{q="Quais são os diferentes platôs da cidade?",a="A cidade abrange um platô central (dividido em níveis inferior, intermediário e superior) cercado por três platôs periféricos. O Platô dos Caçadores é dedicado aos guerreiros, caçadores e alojamentos de rastreamento. O Platô dos Anciãos é o lar de druidas, sábios e da facção Temível Totem. O Platô dos Espíritos abriga santuários para a Mãe Terra, instrutores de xamãs, sacerdotes e magos, e as cavernas dos Poços das Visões.",al={"áreas do penhasco do trovão","o que são os platôs","distritos do penhasco do trovão"}},{q="O que são os Poços das Visões?",a="Os Poços das Visões são cavernas subterrâneas sagradas ocultas sob o Platô dos Espíritos. Videntes, andarilhos espirituais e praticantes do arcano taurens se reúnem nessas águas serenas e envoltas em névoa para comungar com os elementos e interpretar presságios sobre o futuro de seu povo.",al={"poços das visões","caverna do platô dos espíritos","caverna do penhasco do trovão"}},{q="Quem é Magatha Temível Totem?",a="Magatha Temível Totem é a matriarca do formidável clã Temível Totem. Embora resida no Platô dos Anciãos e participe externamente do conselho de Caerne, ela é ferozmente tradicionalista, desconfia de forasteiros e desafia veladamente a postura branda da tribo Casco Sangrento em relação à Horda.",al={"magatha","matriarca","quem é o líder dos temível totem"}}},fx={["6fa5b073"]={q="O que é o Penhasco do Trovão?",a="O Penhasco do Trovão é a capital dos tauren, situada no topo das mesas varridas pelo vento ao norte de Mulgore. Estabelecida pelo Grão-chefe Caerne Casco Sangrento após repelir os centauros com a Horda de Thrall, ela oferece um santuário seguro e permanente para um povo que viveu como nômades errantes por gerações.",al={"o que é esta cidade","me conte sobre o penhasco do trovão","cidade do penhasco do trovão"}},fc90632b={q="Caerne Casco Sangrento é um rei?",a="Não. Caerne Casco Sangrento detém o título de Grão-chefe das tribos tauren unidas. A sociedade tauren não coroa monarcas; Caerne governa através do profundo respeito, sabedoria e força que demonstrou ao longo de décadas, em vez de direito divino real hereditário.",al={"caerne casco sangrento rei","caerne é um rei","rei tauren"}},["047fa056"]={q="Caerne Casco Sangrento responde a Thrall?",a="Thrall é o Chefe Guerreiro da Horda, mas seu vínculo com Caerne baseia-se em honra mútua e aliança, não em subjugação estrita. Caerne comprometeu seu povo com a Horda por gratidão e visão compartilhada, posicionando-se como um dos conselheiros e iguais mais confiáveis de Thrall.",al={"caerne responde a thrall","thrall é chefe de caerne","caerne e thrall"}},["85c1a10f"]={q="Por que os tauren se juntaram à Horda?",a="Saqueadores centauros haviam empurrado os tauren nômades à beira da extinção pelos Sertões. Quando o Chefe Guerreiro Thrall e os orcs desembarcaram em Kalimdor, eles ajudaram o povo de Caerne a romper o cerco centauro e a proteger Mulgore, forjando um vínculo inquebrável entre suas culturas.",al={"por que se juntar à horda","tauren horda aliança","como os tauren se juntaram"}},["3180b5ca"]={q="Qual é a situação da tribo Grimtotem?",a="Os Grimtotem são um clã feroz e agressivo liderado pela anciã Magatha. Ao contrário dos pacíficos Casco Sangrento, eles nutrem profunda suspeita em relação a forasteiros e questionam abertamente a liderança pacífica de Caerne, acreditando que os tauren deveriam conquistar Kalimdor e expulsar as outras raças.",al={"tribo grimtotem","quem são os grimtotem","tauren grimtotem"}},ca8246e8={q="Os Grimtotem são inimigos de Caerne?",a="Abertamente, eles permanecem parte da nação unida dos tauren, e Magatha até reside no Platô dos Anciãos. Sob a superfície, no entanto, uma amarga rivalidade política ferve, pois Magatha trama constantemente e acredita que ela, sozinha, possui a visão correta para governar os tauren.",al={"grimtotem são maus","grimtotem contra caerne","magatha vs caerne"}},["54829977"]={q="O Penhasco do Trovão é perigoso?",a="Dentro da cidade, os bravos guardas mantêm a ordem e a segurança contra as feras e javatus que rondam as planícies abaixo. O maior perigo imediato para os visitantes é a queda abrupta — um passo em falso descuidado das bordas do platô ou das pontes de madeira será fatal.",al={"o penhasco do trovão é seguro","ameaças no penhasco do trovão","perigo aqui"}},["7db56847"]={q="Como vim parar no Penhasco do Trovão?",a="Se você é um jovem tauren, sua jornada começou ao sul, nas pastagens protegidas da Chapada Nuvem Vermelha, e passou pela Aldeia Casco Sangrento antes de trazê-lo aqui. A estrada leva à base desses platôs imponentes, onde grandes elevadores de corda de madeira içam viajantes a centenas de pés de altura no céu. Alternativamente, visitantes que viajam de terras distantes por Kalimdor frequentemente chegam de serpe no Poleiro dos Cavaleiros do Vento central, no topo dos penhascos.",al={"como cheguei aqui","como cheguei ao penhasco do trovão","como chego ao penhasco do trovão"}},["347b5cac"]={q="O que devo fazer no Penhasco do Trovão?",a="O Penhasco do Trovão é o coração espiritual e cultural das tribos tauren unidas. Aqui, você pode buscar treinamento avançado com xamãs, druidas, caçadores e guerreiros anciãos reunidos por todos os platôs. O Alto Chefe Caerne Casco Sangrento e os anciãos tribais também contam com campeões capazes para proteger Mulgore de ameaças persistentes — incluindo saqueadores centauros, a invasora Empreendimentos S.A., harpias e javatus rebeldes — antes de enviá-lo para o leste, para as provações mais amplas da Horda.",al={"o que devo fazer no penhasco do trovão","por que estou aqui","qual é meu propósito aqui"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:tirisfal"] = {n="Clareiras de Tirisfal",s="Clareiras de Tirisfal é o território assombrado ao norte de Lordaeron, agora servindo como o coração de Lady Sylvanas e dos Renegados. Sob céus assolados pela praga e galhos apodrecidos jazem mansões caídas, criptas adormecidas e a vasta capital subterrânea da Cidade Baixa. Cercado pelo Flagelo sem mente e pelos zelosos cruzados Escarlates, é um reino perigoso onde mortos-vivos com livre-arbítrio lutam por sua sobrevivência.",h="Clareiras de Tirisfal é o território assombrado ao norte de Lordaeron, agora servindo como o coração de Lady...",kw={"agamand","balnir","montalvo","plangemortis","renegados","clareiras","lordaeron","cruzada escarlate","sylvanas","tirisfal","cidade baixa"},ang={["class:Priest"]="Terras sagradas históricas como o Repouso de Faol — o túmulo do Arcebispo Alonsus Faol, fundador da Mão de Prata — jazem aqui, distorcidas pela morte e disputadas entre fanáticos e sacerdotes das Sombras.",["faction:Alliance"]="Para as nações sobreviventes da Aliança, Tirisfal é um monumento trágico à queda de Lordaeron, repleto dos túmulos profanados de antigos irmãos e irmãs na fé.",["faction:Horde"]="Tirisfal é o bastião vital da Horda nos Reinos do Leste ao norte, ancorando laços diplomáticos com os Renegados enquanto afasta extremistas humanos e o Flagelo.",["race:Undead"]="Esta é a sua terra natal ancestral duas vezes: o reino que você construiu em vida e o santuário precário que você deve defender na morte sob o comando de Lady Sylvanas."},sec={{t="Uma Terra no Crepúsculo",b="Outrora o berço fértil da humanidade, Clareiras de Tirisfal definhou sob a maldição da praga do Lich King. O sol raramente penetra a escuridão sombria, lançando uma palidez doentia eterna sobre bosques moribundos, plantações de abóboras negligenciadas e colinas costeiras frias. Embora remanescentes de antigas fazendas como os Moinhos dos Agamand e a Fazenda dos Balnir permaneçam, seus antigos mestres foram em grande parte varridos para valas comuns ou ressurgiram como mortos inquietos. Apesar da devastação, uma resiliência sombria permeia o campo, ancorada por cidades como Montalvo e o santuário enclausurado de Plangemortis, onde Renegados recém-despertados aprendem a suportar sua segunda vida."},{t="Uma Guerra em Duas Frentes",b="Embora Lady Sylvanas reivindique domínio sobre a região a partir das subterrâneas Ruínas de Lordaeron, os Renegados permanecem em batalha em todos os lados. Escravos residuais do Flagelo ainda infestam grotas, campos e criptas dilapidadas, inteiramente submissos ao trono congelado de Northrend. Para o leste, a fanática Cruzada Escarlate fez do norte de Tirisfal seu bastião principal, operando a partir do Monastério Escarlate. Zelosamente devotados ao extermínio de toda criatura morta-viva, viva ou morta, seus postos avançados e patrulhas travam uma guerra de guerrilha constante contra batedores Renegados e viajantes civis."},{t="Ecos do Passado Antigo",b="Muito antes de os reinos humanos coroarem seus primeiros monarcas, as Clareiras carregavam um legado antigo. Exilados elfos superiores tentaram brevemente estabelecer-se nestes bosques antes que energias sombrias nas profundezas da terra começassem a enlouquecê-los, provocando sua migração para o norte. Em séculos posteriores, a cabala mortal secreta conhecida como Conselho de Tirisfal escolheu estes bosques sombrios para capacitar Guardiões solitários, protegendo Azeroth de intrusões demoníacas."}},faq={{q="Por que o céu é verde e a terra está apodrecendo?",a="Durante a Terceira Guerra, o Príncipe Arthas e o Flagelo desencadearam a Praga da Morte-viva por todo o Reino de Lordaeron. A praga mágica envenenou não apenas a população, mas o solo, as árvores e a própria água, deixando as Clareiras em um estado eterno de decadência sinistra e doentia.",al={"por que tirisfal está assolada pela praga","o que aconteceu com tirisfal","por que tirisfal está morrendo"}},{q="Qual é a diferença entre os Renegados e o Flagelo aqui?",a="Os Renegados são mortos-vivos que se libertaram da dominação telepática do Lich King após a Batalha do Monte Hyjal, escolhendo seguir a Grande Dama Sylvana Correventos com seu próprio livre-arbítrio. O Flagelo que vagueia pelas fazendas e ruínas permanece como escravos sem mente presos aos comandos do Lich King.",al={"renegados vs flagelo","por que zumbis atacam mortos-vivos","todos os mortos-vivos são malignos"}},{q="Quem são os soldados de armadura vermelha que atacam viajantes?",a="Eles pertencem à Cruzada Escarlate, uma ordem dissidente intransigente de antigos paladinos da Mão de Prata e sobreviventes. Convencidos de que todos os mortos-vivos são abominações irredimíveis que devem ser purificadas pela espada e pelo fogo, eles executam tanto escravos sem mente quanto Renegados com livre-arbítrio com ódio fanático.",al={"cruzada escarlate","humanos vermelhos","humanos do monastério"}},{q="De onde vem o nome Tirisfal?",a="O nome é mais antigo que qualquer reino humano, e sua verdadeira origem foi perdida na história. É mais conhecido através do Conselho de Tirisfal, a ordem secreta de magos que capacitou os Guardiões para proteger Azeroth de demônios.",al={"significado de tirisfal","origem de tirisfal"}},{q="Onde os Renegados recém-despertados começam sua jornada?",a="Os Renegados recém-despertados emergem das criptas do Sepulcro Sombrio dentro de Plangemortis, uma cidade enclausurada situada no sudoeste de Tirisfal. Lá, administradores e executores avaliam se os mortos ressuscitados possuem a sanidade e a lealdade necessárias para servir à Dama Sombria.",al={"zona inicial dos mortos-vivos","onde fica plangemortis","área inicial dos renegados"}},{q="Como os viajantes deixam Tirisfal para outros continentes?",a="Uma grande torre de zepelim operada por goblins fica na encosta ao sul de Montalvo, logo fora das Ruínas de Lordaeron. Essas aeronaves fornecem trânsito direto e regular pelos mares até Orgrimmar em Kalimdor e o Acampamento Grom'gol na Selva do Espinhaço.",al={"zepelins de tirisfal","como ir para orgrimmar","como ir para a selva do espinhaço"}}},fx={["6c272224"]={q="O que são as Clareiras de Tirisfal?",a="As Clareiras de Tirisfal são o coração dos Renegados na costa norte de Lordaeron. Antes o núcleo pacífico e fértil de um orgulhoso reino humano, foi devastado durante a Terceira Guerra pela Praga da Morte do Flagelo. Hoje, bosques assolados e uma penumbra verde perpétua cobrem as colinas, emolduradas pelas ruínas da capital de Lordaeron e cercadas por fanáticos hostis, feras selvagens e mortos-vivos persistentes.",al={"o que é tirisfal","fale-me sobre as clareiras de tirisfal","lore da zona tirisfal"}},["342b65f9"]={q="Estas terras sempre foram dos mortos-vivos?",a="Não. Por milhares de anos, Tirisfal foi o berço da civilização humana e o coração próspero do Reino de Lordaeron. Fazendas pacíficas, moinhos prósperos e pequenas aldeias floresceram sob o Rei Terenas Menethil. Essa era terminou violentamente durante a Terceira Guerra, quando o Príncipe Arthas e a Seita dos Malditos passaram por lá com a praga, transformando os habitantes em escravos mortos-vivos antes que Sylvana os libertasse.",al={"tirisfal sempre foi dos mortos-vivos","quem morava aqui antes","tirisfal antes da praga"}},["4790468d"]={q="Quem vive ou governa as Clareiras de Tirisfal?",a="Os Renegados reivindicam as Clareiras de Tirisfal sob o governo da Rainha Sylvana Correventos da Cidade Baixa. No entanto, seu domínio é constantemente contestado. A fanática Cruzada Escarlate comanda fortificações e seu grande Monastério no nordeste, enquanto o Flagelo irracional ronda fazendas abandonadas. Na fronteira leste, no Baluarte, os Renegados coordenam com a Aurora Argêntea para manter os horrores das Terras Pestilentas contidos.",al={"quem governa tirisfal","quem controla as clareiras de tirisfal","facções de tirisfal"}},["97ffdb73"]={q="As Clareiras de Tirisfal são perigosas?",a="Extremamente perigosas. Além dos muros dos postos avançados dos Renegados, você enfrentará remanescentes irracionais do Flagelo, gnolls selvagens, aracnídeos gigantes e vida selvagem viciosa contaminada pela praga. Pior ainda são os fanáticos da Cruzada Escarlate, que executam qualquer morto-vivo à vista. No extremo leste ficam as Terras Pestilentas Ocidentais, onde monstros muito mais mortais do que qualquer coisa em Tirisfal despedaçarão os incautos.",al={"quão perigosa é tirisfal","ameaças de tirisfal","é seguro aqui"}},["30e6283a"]={q="Quem está no comando em Montalvo?",a="O Magistrado Sevren supervisiona a administração civil de Montalvo, gerenciando a reconstrução e a sobrevivência diária da cidade. A autoridade militar e as operações táticas, particularmente a campanha contra Cruzada Escarlate próxima, são comandadas pelo Executor Zigano.",al={"líder de montalvo","quem lidera montalvo","no comando de montalvo"}},["3fc3649e"]={q="A quem o Magistrado Sevren responde?",a="Sevren serve à Dama Sombria, Rainha Sylvana Correventos. Como magistrado de Montalvo, ele representa a autoridade civil da coroa dos Renegados na região, operando em concerto direto com os executores reais e a Real Sociedade de Boticários sediada na Cidade Baixa.",al={"chefe de sevren","a quem sevren responde","cadeia de comando de montalvo"}},["381a9b46"]={q="Onde está a Rainha Banshee?",a="A Grande Dama Sylvana Correventos reside no Royal Quarter da Cidade Baixa, profundamente abaixo das ruínas da Cidade Capital, logo ao sul de Montalvo. De sua sala do trono, ela direciona os Renegados em sua guerra contra o Flagelo e a Cruzada Escarlate.",al={"onde está sylvana","encontrar sylvana","localização da rainha banshee"}},e7993821={q="O que é Montalvo?",a="Montalvo é a principal cidade dos Renegados nas Clareiras de Tirisfal centrais, situada ao longo das encruzilhadas ao norte da Cidade Capital. Antigamente um assentamento vivo sob a propriedade Barov, foi reconstruída após a Terceira Guerra para fornecer aos mortos-vivos recém-despertos um lugar de descanso, comércio e organização antes de se aventurarem mais pelo mundo.",al={"sobre montalvo","que tipo de cidade é montalvo","lore de montalvo"}},["529e09c8"]={q="Pessoas vivas moravam aqui antes?",a="Sim. Montalvo já foi uma comunidade humana tranquila dentro do Reino de Lordaeron. Tornou-se o marco zero para os primeiros experimentos com a praga orquestrados por Kel'Thuzad, resultando em baixas em massa e enormes sepulturas comunitárias antes mesmo de o Príncipe Arthas chegar para investigar.",al={"humanos moravam em montalvo","história de montalvo","quem morava em montalvo"}},["7b7ff5e2"]={q="O que é a Taberna Finda Forca?",a="A Taberna Finda Forca é o salão de reuniões e estalagem central de Montalvo. Oferece abrigo, bebidas imundas e descanso das clareiras sombrias lá fora. Em seus cantos mais escuros, os Renegados mantêm inimigos capturados — como fanáticos da Cruzada Escarlate — para testes sinistros de concoções da Sociedade de Boticários.",al={"taberna finda forca","estalagem de montalvo","o que é a taberna finda forca"}},["0d8014ee"]={q="Qual é a situação dos Moinhos dos Agamand?",a="Os Moinhos dos Agamand já foram a propriedade agrícola mais rica e produtiva das Clareiras de Tirisfal, famosa pela farinha e grãos. Quando a praga atingiu, todo o complexo foi invadido e o massacre aconteceu. Hoje, permanece como uma ruína apodrecida, pontilhada de moinhos de vento e sufocada por mortos-vivos persistentes do Flagelo.",al={"lore dos moinhos dos agamand","o que aconteceu aos moinhos dos agamand","moinhos dos agamand"}},["001d4abe"]={q="Quem eram os Agamand?",a="Os Agamand eram uma dinastia humana nobre e rica que desenvolveu os moinhos extensos e possuía propriedades por toda Tirisfal, incluindo Montalvo. Durante a Terceira Guerra, sua fortuna não pôde salvá-los; a família caiu para o Flagelo e seus patriarcas reanimados continuam a assombrar a propriedade.",al={"família agamand","quem morava nos moinhos dos agamand","os agamand"}},eeb96a2c={q="Por que eles são hostis conosco se eles também são mortos-vivos?",a="Os mortos-vivos que assombram os Moinhos dos Agamand nunca recuperaram seu livre-arbítrio. Ao contrário dos Renegados, que se livraram do controle mental do Lich Rei, essas criaturas permanecem escravizadas como servos irracionais do Flagelo, compelidos a destruir qualquer vivo ou morto-vivo rebelde que invada seu domínio.",al={"por que os agamand nos atacam","por que os mortos-vivos agamand são hostis","por que lutar contra outros mortos-vivos"}},a357af07={q="Onde tudo isso leva depois de Tirisfal?",a="A maioria dos Renegados viaja para o sul através da passagem da montanha até a Floresta de Pinhaprata para ajudar a garantir a fronteira sul e batalhar contra agentes de Dalaran e gnolls Couro-podre. Alternativamente, zepelins ao sul de Montalvo fornecem passagem para Orgrimmar ou para o Acampamento Grom'gol através do mar.",al={"para onde ir depois de tirisfal","próxima zona depois de tirisfal","depois das clareiras de tirisfal"}},["50336b90"]={q="O que é a Cidade Baixa?",a="A Cidade Baixa é a vasta capital subterrânea dos Renegados, construída dentro dos antigos esgotos, criptas e catacumbas sob as Ruínas de Lordaeron despedaçadas. Ela serve como a fortaleza da Rainha Sylvanas e o Command Center para as operações dos Renegados por toda Azeroth.",al={"o que é a cidade baixa","lore da cidade baixa","sobre a cidade baixa"}},ddddba9f={q="A fronteira de Floresta de Pinhaprata é a seguir?",a="Sim. Seguir a estrada para o sul saindo das Clareiras de Tirisfal leva diretamente à Floresta de Pinhaprata. É a continuação natural do seu serviço aos Renegados, onde você confronta a crescente ameaça ao longo das fronteiras do sul de Lordaeron.",al={"floresta de pinhaprata a seguir","vou para floresta de pinhaprata em seguida","fronteira da floresta de pinhaprata"}},["789ead4d"]={q="Como fui parar nas Clareiras de Tirisfal?",a="Se você é um Renegado recém-erguido, você morreu durante a queda de Lordaeron para o Flagelo e foi enterrado aqui. Com o controle do Lich King quebrado, seu livre arbítrio retornou e você saiu da cova no vale isolado de Plangemortis. Se você pertence a outras nações da Horda, você provavelmente chegou através das torres de zepelim situadas entre Montalvo e a Cidade Baixa, que conectam este reino assolado diretamente a Orgrimmar e ao Acampamento Grom'gol.",al={"como cheguei aqui","como cheguei às clareiras de tirisfal","como cheguei a este lugar"}},["89135166"]={q="O que eu devo fazer nas Clareiras de Tirisfal?",a="Seu objetivo é ajudar os Renegados a garantir seu domínio tênue sobre as terras centrais assoladas de Lordaeron. Saindo das criptas de Plangemortis em direção à cidade de Montalvo, você deve expurgar o Flagelo irracional que assombra as fazendas abandonadas, eliminar os fanáticos zelotas da Cruzada Escarlate que avançam do norte e abater as feras contaminadas que vagam pelos bosques apodrecidos. Fazer isso prova seu valor para Lady Sylvanas e prepara você para servir ao seu reino em crescimento sob as ruínas da Capital.",al={"o que devo fazer aqui","por que estou em tirisfal","qual é meu objetivo aqui"}}},fp="15,403,18.637.0,19.603.0,26.427.0,42.269.0,65.287.0,53.289.0,39.222.0,53.269.0,53.247.0"}
P.entries["zone:undercity"] = {n="Cidade Baixa",s="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza dos Renegados. Escavada originalmente a partir de antigas criptas reais e masmorras pelo Flagelo, foi tomada por Grande Dama Sylvana Correventos e transformada em um impenetrável santuário subterrâneo. Hoje, serve como a sede do poder dos Renegados e o bastião vital da Horda no norte dos Reinos do Leste.",h="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza...",kw={"boticarium","arthas","renegados","lordaeron","flagelo","sylvanas","terenas","tirisfal","cidade baixa","varimatras"},ang={["faction:Horde"]="Como a principal fortaleza da Horda nos Reinos do Leste, Cidade Baixa garante conexões diretas por zepelim com Durotar e o Acampamento Grom'gol.",["race:Human"]="Sob o solo do seu reino ancestral devastado jaz uma sombria perversão das criptas reais de Lordaeron, ocupada pelos cadáveres ambulantes dos seus antigos irmãos.",["race:Orc"]="Nas profundezas destas mesmíssimas masmorras, o lendário Chefe de Guerra Orgrim Martelo da Perdição já esteve aprisionado pela Aliança de Lordaeron antes de realizar sua fuga histórica.",["race:Undead"]="A Cidade Baixa é o seu santuário soberano e lar, esculpido por suas próprias mãos depois de quebrar o domínio de ferro do Lich Rei sobre a sua mente."},sec={{t="De Criptas Reais a Reduto do Flagelo",b="Muito antes de a peste assolar Lordaeron, as catacumbas, masmorras e esgotos sob o palácio eram conhecidos coletivamente como Cidade Baixa. O local abrigava os túmulos da nobreza, as prisões mais profundas do reino — onde o antigo Chefe de Guerra Orgrim Martelo da Perdição já esteve preso antes de fugir — e os habitantes mais indigentes da região. Quando Arthas Menethil assassinou o Rei Terenas e devastou a capital em 20 ADP, o príncipe ordenou que seus servos mortos-vivos escavassem e expandissem as passagens subterrâneas em uma sede fortificada para o domínio do Flagelo."},{t="Ascensão dos Renegados",b="O Flagelo nunca viu sua capital sombria concluída. Quando os poderes do Lich Rei diminuíram após a batalha do Monte Hyjal, Grande Dama Sylvana Correventos libertou-se do controle mental, levando consigo milhares de mortos-vivos. Ela atraiu Arthas para uma emboscada e o expulsou de volta para Northrend. Após uma violenta guerra civil tripartite contra remanescentes do Flagelo, Senhores do Medo e a resistência humana, Sylvanas reivindicou as catacumbas inacabadas. Dando ao seu povo o nome de Renegados, ela supervisionou anos de trabalho árduo para concluir a vasta cidade subterrânea."},{t="Arquitetura dos Condenados",b="Cidade Baixa é organizada em anéis concêntricos divididos em bairros funcionais. Em seu coração fica o Distrito Comercial, conectado por grandes elevadores às ruínas do palácio acima. Ao seu redor estão o Distrito Bélico, o Distrito dos Ladinos, o Distrito da Magia e o tóxico Boticarium, onde a Real Sociedade de Boticários prepara pestes virulentas em canais cheios de lodo verde. Mais abaixo ainda fica o Distrito Real, onde a Rainha Banshee governa ao lado de seu comandante Senhor do Medo, Varimatras, protegida por legiões de imponentes abominações."}},faq={{q="O que era Cidade Baixa antes de os mortos-vivos a tomarem?",a="Sob o palácio de Lordaeron ficavam as antigas criptas da realeza humana, juntamente com o complexo carcerário e a vasta rede de esgotos da cidade. Ali ficavam prisioneiros de guerra, incluindo Orgrim Martelo da Perdição, bem como cidadãos desprovidos vivendo nas sombras subterrâneas. Após saquear a capital, o Príncipe Arthas começou a transformar essas catacumbas em uma fortaleza do Flagelo antes de Sylvanas tomá-las.",al={"origens de cidade baixa","o que era cidade baixa originalmente","historia dos esgotos de lordaeron"}},{q="Por que a cidade é construída no subsolo em vez de na superfície?",a="A cidade de Lordaeron na superfície foi completamente arruinada durante a Terceira Guerra, tornando difícil defendê-la contra Cruzada Escarlate, as forças do Flagelo e os sobreviventes da Aliança. Os túneis subterrâneos ofereciam fortificação natural, pontos de estrangulamento e discrição, permitindo aos Renegados concluir a construção inicial do Flagelo e prosperar sem serem vistos.",al={"por que morar no subsolo","por que nao reconstruir lordaeron","por que cidade baixa sob as ruinas"}},{q="Quem governa Cidade Baixa?",a="A cidade é governada por Grande Dama Sylvana Correventos, a Rainha Banshee e Rainha dos Renegados. Ela lidera a partir do Distrito Real, guardada por sentinelas reais dos Renegados e por seu tenente Senhor do Medo subjugado, Varimatras.",al={"quem e o lider de cidade baixa","governante de cidade baixa","quem comanda cidade baixa"}},{q="O que é o memorial do Rei Terenas nas ruínas acima?",a="Acima dos elevadores principais da cidade encontra-se um memorial de pedra para o falecido Rei Terenas Menethil II. Não contém seu corpo, pois seus restos foram cremados e suas cinzas descartadas durante a ressurreição de Kel'Thuzad. Humanos sobreviventes da Aliança esculpiram bravamente o monumento em meio às ruínas para que a memória do último verdadeiro rei de Lordaeron perdurasse.",al={"tumulo do rei terenas","tumulo na sala do trono de lordaeron","quem construiu o tumulo acima de cidade baixa"}},{q="O que são os barulhos estranhos na sala do trono de Lordaeron?",a="Na sala do trono em ruínas acima dos elevadores de Cidade Baixa, ecos espectrais do passado ainda permanecem. Os visitantes que ficam no centro podem ouvir tênues sons fantasmagóricos: os sinos festivos e as pétalas de rosa do retorno de Arthas, as palavras de aviso do profeta Medivh e a conversa final entre o Rei Terenas e seu filho parricida.",al={"sons de fantasmas na sala do trono","sussurros na sala do trono","vozes na sala do trono de lordaeron"}},{q="Por que os Renegados permitem outros membros da Horda aqui?",a="Os Renegados formaram uma aliança de conveniência com a Horda do Chefe de Guerra Thrall para garantir sua sobrevivência, cercados como estão por fanáticos zelotes da Cruzada Escarlate e legiões do Flagelo. Embora as raças vivas da Horda achem os vapores tóxicos e os rios alquímicos sufocantes, emissários e viajantes têm acesso liberado para cultivar laços diplomáticos e militares.",al={"por que ha orcs em cidade baixa","horda em cidade baixa","por que cidade baixa faz parte da horda"}}},fx={a590d153={q="O que é a Cidade Baixa?",a="A Cidade Baixa é a capital subterrânea dos Renegados, construída diretamente sob as ruínas despedaçadas da Cidade Capital nas Clareiras de Tirisfal. Esculpida a partir de antigas criptas reais, esgotos e catacumbas, ela foi expandida pelo Príncipe Arthas como um reduto do Flagelo antes que a Grande Dama Sylvana Correventos e seus mortos-vivos renegados a tomassem durante a guerra civil. Hoje, ela permanece como um santuário fortificado para mortos-vivos com livre-arbítrio, entrecruzado por lodo tóxico e vigiado atentamente contra todos os intrusos vivos.",al={"o que é a cidade baixa","fale-me sobre a cidade baixa","lore da cidade baixa"}},c51b16b2={q="O que aconteceu com o antigo rei de Lordaeron?",a="O Rei Terenas Menethil II foi assassinado na sala do trono diretamente acima desta cidade por seu próprio filho, o Príncipe Arthas. Após retornar de Nortúndria corrompido pela lâmina rúnica Gélido Lamento, Arthas abateu seu pai e libertou o Flagelo sobre o reino. As cinzas de Terenas foram mais tarde roubadas pelo cavaleiro da morte para ressuscitar Kel'Thuzad, deixando para trás apenas a pedra memorial e o rastro seco de sangue que você ainda pode ver perto do trono arruinado.",al={"destino do rei terenas","o que aconteceu com o rei terenas","quem matou o rei terenas"}},c11144c7={q="Quem era Arthas?",a="Arthas Menethil era o Príncipe Herdeiro de Lordaeron e um celebrado Paladino da Mão de Prata. Desesperado para deter a Praga da Morte que varria sua terra natal, sua cruzada tornou-se implacável e fanática. Em Nortúndria, ele reivindicou a amaldiçoada lâmina rúnica Gélido Lamento, que devorou sua alma e o tornou o temível campeão do Lich Rei. Ele retornou para casa apenas para massacrar seu pai, arrasar Lordaeron e, eventualmente, viajar de volta para o norte para se fundir ao Trono de Gelo.",al={"quem é arthas","lore do príncipe arthas","arthas menethil"}},["7f6bbd49"]={q="Quem é Sylvana Correventos?",a="A Grande Dama Sylvana Correventos foi outrora a valente General-Patrulheira de Luaprata, defendendo Quel'Thalas contra o Flagelo durante a Terceira Guerra. Quando ela caiu, Arthas arrancou sua alma de seu cadáver e a transformou em uma banshee para torturá-la. Quando o domínio do Lich Rei enfraqueceu, ela se libertou, recuperou sua forma física e reuniu outros mortos-vivos independentes nos Renegados. Agora ela reina como sua Rainha Banshee a partir do Distrito Real.",al={"quem é a rainha banshee","lore de sylvana","quem é sylvana"}},["2a8de90f"]={q="Por que Sylvana é chamada de Dama Sombria?",a="Os Renegados homenageiam Sylvana como a Dama Sombria porque ela os libertou da escravidão sem mente do Lich Rei e lhes deu abrigo quando o restante de Azeroth buscava seu extermínio total. Reverenciado junto com seu título de Rainha Banshee, o apelido reflete tanto seu domínio sombrio sobre a morte quanto a devoção feroz e inabalável de seus súditos mortos-vivos.",al={"por que dama sombria","título dama sombria sylvana","significado de dama sombria"}},["84f18f47"]={q="Por que os Renegados fazem parte da Horda?",a="Cercados por Cruzados Escarlates hostis, o implacável Flagelo e remanescentes vingativos da Aliança, os Renegados não poderiam sobreviver sozinhos em Lordaeron. A Grande Dama Sylvana contatou o Chefe Guerreiro Thrall do outro lado do mar, forjando uma aliança pragmática de conveniência. A Horda obteve um ponto de apoio militar crucial nos Reinos do Leste, enquanto os Renegados garantiram reforços essenciais e legitimidade política em sua guerra pela sobrevivência.",al={"por que os renegados na horda","mortos-vivos juntam-se à horda","renegados horda aliança"}},["71200045"]={q="O que é o Flagelo e eles ainda estão por perto?",a="O Flagelo é o vasto e voraz exército de mortos-vivos sem mente criado pela Legião Ardente e governado pelo Lich Rei de Nortúndria. Embora os Renegados tenham arrebatado a Cidade Baixa e Tirisfal de suas garras, o Flagelo permanece um perigo imediato e letal. Suas legiões ainda sufocam as Terras Pestilentas próximas sob o comando de Kel'Thuzad e infestam fazendas abandonadas e criptas por todas as clareiras.",al={"o flagelo está por perto","o que é o flagelo","flagelo em lordaeron"}},["501548ab"]={q="Onde está o Lich Rei agora?",a="O Lich Rei reside no topo do Trono de Gelo nos distantes e gelados ermos de Nortúndria. Após a guerra civil nas Terras Pestilentas, o Príncipe Arthas fugiu de Lordaeron para proteger seu mestre enfraquecido, ascendendo à geleira e fundindo suas essências em uma única entidade aterrorizante. Daquele baluarte ártico, seu olhar gelado ainda observa Azeroth.",al={"onde está o lich rei","localização do lich rei","onde está arthas agora"}},["4cc7f971"]={q="Quem é a Cruzada Escarlate?",a="a Cruzada Escarlate é uma ordem fanática de fanáticos humanos nascida das ruínas da defesa de Lordaeron. Cegados por seu ódio justo aos mortos-vivos, eles não fazem distinção entre o Flagelo sem mente e os Renegados com livre-arbítrio, vendo qualquer um maculado pela morte-viva — e qualquer forasteiro vivo que os tolere — como abominações vis dignas apenas da pira. Seu principal baluarte em Tirisfal é o Monastério Escarlate.",al={"quem é a cruzada escarlate","cruzados escarlates","lore da cruzada escarlate"}},["271820ed"]={q="A Cidade Baixa é perigosa?",a="É extraordinariamente perigosa, especialmente para os vivos. Canais de resíduos alquímicos brutos e lodo venenoso percorrem as ruas da cidade, preenchendo os salões cavernosos com vapores tóxicos que tornam a respiração perigosa para visitantes de carne e osso. Sob os bairros pavimentados jazem esgotos infestados, e ainda mais fundo estão experimentos secretos onde alquimia sombria e assassinatos implacáveis são planejados diariamente.",al={"a cidade baixa é segura","perigo na cidade baixa","perigos da cidade baixa"}},["2539a3c3"]={q="Como fui parar na Cidade Baixa?",a="Como um Renegado, seu caminho naturalmente o levou até aqui após despertar da morte em Plangemortis e provar sua lealdade através das Clareiras de Tirisfal, seguindo as estradas após Montalvo para descer sob as ruínas despedaçadas da Cidade Capital. Se você vem de Kalimdor ou de terras distantes, provavelmente chegou a bordo de um zepelim da Horda atracando nas torres logo fora da capital, ou caminhou pelo campo assolado. A Cidade Baixa permanece como o principal reduto da Horda no norte de Lordaeron, oferecendo abrigo e propósito sob as antigas catacumbas do palácio.",al={"como cheguei aqui","como cheguei à cidade baixa","como chegar à cidade baixa"}},b63c4cf2={q="O que devo fazer na Cidade Baixa?",a="Você está aqui para ajudar os Renegados e reunir a força da Horda contra os perigos que cercam Lordaeron. Dentro dos bairros concêntricos da cidade, você pode consultar instrutores de classe, adquirir suprimentos e consultar os pesquisadores sombrios da Real Sociedade de Boticários. Além de cuidar de seu ofício, seu dever é aceitar missões para a Grande Dama Sylvana Correventos e seus tenentes. Os Renegados lutam uma guerra em múltiplas frentes: expurgando os remanescentes do Flagelo sem mente, repelindo a fanática Cruzada Escarlate e garantindo um terreno seguro para que os mortos-vivos com livre-arbítrio possam perdurar.",al={"o que estou fazendo aqui","o que devo fazer na cidade baixa","por que estou aqui"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Cratera Un’Goro",s="A Cratera Un’Goro é uma selva primordial e rebaixada, situada entre as terras áridas de Tanaris e Silithus. Dominada por dinossauros errantes, elementais vivos e um vulcão central, esta caldeira exuberante está repleta de relíquias antigas dos Titans e cristais de poder cujas origens permanecem um profundo mistério.",h="A Cratera Un’Goro é uma selva primordial e rebaixada, situada entre as terras áridas de Tanaris e Silithus.",kw={"demossauro","pico penacho de fogo","terras dos deuses","lakkari","refúgio do marshal","cristais de poder","torwa mateiro","ungoro","cratera un'goro"},ang={["class:Druid"]="Druidas do Círculo Cenariano estudam o ecossistema isolado de Un'Goro e colhem seu solo rico para propagar grão-matinal, buscando compreender a força vital pura e indomável que sustenta a caldeira.",["faction:Alliance"]="Naturalistas da Aliança reúnem-se em torno de Williden Marshal e J.D. Collie no Refúgio do Marshal, correndo contra o tempo para decifrar os pilares dos Titans enquanto protegem os pesquisadores de Darnassus que coletam amostras de solo.",["faction:Horde"]="Aventureiros da Horda costumam chegar por Tanaris para testar suas proezas contra demossauros lendários e ajudar os herboristas do Penhasco do Trovão a cultivar grão-matinal a partir da terra primitiva de Un'Goro.",["profession:Herbalism"]="A rica umidade da bacia sustenta uma flora rara, servindo como um dos poucos lugares em Kalimdor onde Blindweed, Folha-de-sonho e Sonsona-dourada florescem juntas, ao lado de Ignídea nas encostas do vulcão.",["profession:Mining"]="As paredes íngremes da cratera e os rochedos do Pico Penacho de Fogo são densos em Mithril Deposits e Rich Thorium Veins, tornando a zona um destino de primeira linha para minérios de alto nível."},sec={{t="As Terras dos Deuses",b="Espremida entre extensões desérticas, a Cratera Un’Goro desafia a geografia do sul de Kalimdor. Antigos registros de elfos noturnos detalhando a Guerra das Areias Cambiantes observam que os insectoides Qiraji foram repelidos nas bordas da cratera, incapazes de penetrar no que sua língua chamava de 'Terras dos Deuses'. Estudiosos teorizam que a caldeira serviu como campo de testes ou morada antiga para os Titans durante a formação de Kalimdor. Pilares de pedra erguem-se ao longo das cristas, zumbindo com energia, enquanto formações de cristais azuis, vermelhos, verdes e amarelos brotam pela terra primitiva."},{t="Um Ecossistema Selvagem",b="Un'Goro não contém cidades, vilas ou sociedades humanoides nativas. Em vez disso, a vida prospera em um estado selvagem e primitivo. Demossauros predadores de topo espreitam pelas planícies de Terroral, bloodpetals predatórias atacam nos Pântanos, e gosmas rastejam pelos poços de piche de Lakkari. No coração da cratera ergue-se o Pico Penacho de Fogo, um pico vulcânico ativo repleto de elementais de fogo hostis liderados pela entidade Blazerunner. Para exploradores e esfoladores, a bacia oferece uma riqueza natural inigualável — incluindo os cobiçados couros de demossauros — desde que se sobreviva à cadeia alimentar."},{t="Refúgio do Marshal",b="A presença civilizada na cratera limita-se quase inteiramente ao Refúgio do Marshal, um acampamento elevado situado nos penhascos do norte. Liderada por Williden Marshal, uma expedição de cientistas, naturalistas e caçadores de fortuna tentou catalogar os tesouros da bacia, apenas para ser castigada pela fauna monstruosa e forçada a recuar para terrenos mais altos. Hoje, o refúgio serve como um ponto de partida combatido para viajantes intrépidos que estudam os misteriosos cristais de poder da cratera, mapeiam a atividade vulcânica e mantêm A Watchful Eye nos enxames de silithídeos invasores que rompem as cristas ao sul."}},faq={{q="Como você entra na Cratera Un’Goro?",a="Os viajantes podem entrar por meio de rampas naturais que descem pelas paredes da cratera: uma acessível a partir do canto sudoeste de Tanaris, perto do Vale Moitagulhas, e outra vinda do nordeste de Silithus. Embora aventureiros imprudentes às vezes saltem dos penhascos, a queda é fatal sem assistência mágica. O Refúgio do Marshal, ao norte, oferece conexões de voo para Geringontzan e o Forte Cenariano.",al={"como entrar em ungoro","entrada de ungoro","como chegar a cratera un'goro"}},{q="Para que servem os cristais de poder coloridos?",a="Espalhados pelo chão da selva estão Cristais de Poder vermelhos, azuis, verdes e amarelos. Com a orientação da pesquisadora gnoma J.D. Collie no Refúgio do Marshal, os exploradores podem decifrar instruções para usar esses cristais nos Pylons Norte, Leste e Oeste. A combinação de cores específicas nos pilares apropriados canaliza energias latentes dos Titans para criar berloques defensivos ou restauradores.",al={"cristais de ungoro","cristais vermelhos azuis verdes amarelos ungoro","pilares de poder"}},{q="Por que Un'Goro é exuberante apesar de estar cercada por desertos?",a="Estudiosos acreditam que a vivacidade não natural de Un'Goro é artificial, originada dos Titans que moldaram o mundo. Condutos titânicos, a atividade geotérmica vulcânica quente do Pico Penacho de Fogo e a antiga energia das linhas de meridiano alimentam um ecossistema isolado e hiperacelerado que resiste às condições áridas das vizinhas Tanaris e Silithus.",al={"por que ungoro é uma selva","conexão de ungoro com o deserto","como ungoro tem plantas"}},{q="Por que os qiraji chamavam este lugar de 'Terras dos Deuses'?",a="De acordo com tabuletas traduzidas da Guerra das Areias Cambiantes, os enxames de insetos interromperam seu avanço no limiar da cratera. O Geólogo Larksbane, que traduziu o relato, vincula o nome a teorias de que os Titans outrora habitaram a cratera e se pergunta se o próprio Aman'Thul vigiava as Terras dos Deuses.",al={"significado de Terras dos Deuses","qiraji em Un'Goro","por que os silitídeos não tomaram Un'Goro"}},{q="Para que serve o Solo de Un'Goro?",a="Pilhas de terra rica e potente repousam por toda a bacia da cratera. Quando coletado, esse solo pode ser combinado com sementes de Tharlendris em um Bornal de Sempre-viva para cultivar grão-matinal, uma erva mística intensamente procurada por pesquisadores no Penhasco do Trovão, em Darnassus e no Círculo Cenariano.",al={"amostra de solo de ungoro","para que serve o solo de ungoro","solo de grão-matinal"}},{q="Existe algum assentamento humanoide ou masmorra aqui?",a="A Cratera Un’Goro abriga uma masmorra, O Terraço do Moldador, para níveis aproximados de 58 a 60, mas nenhuma sociedade humanoide nativa. O único assentamento duradouro é o Refúgio do Marshal, um pequeno posto avançado de expedição na borda norte. Além de caçadores eremitas isolados ou exploradores perdidos, o restante da caldeira é totalmente selvagem.",al={"masmorras de ungoro","quem vive em ungoro","humanoides em ungoro"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.307.0"}
P.entries["zone:wailing"] = {n="Caverna Ululante",s="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico de nascentes e fissuras subterrâneas que recebeu esse nome devido ao silvo sinistro do vapor represado. O que começou como um nobre esforço druídico para revitalizar a savana crestada pelo sol de Kalimdor transformou-se em um submundo distorcido e venenoso. As cavernas agora fervilham com uma fauna deturpada e discípulos decaídos corrompidos por um pesadelo profundo e antinatural.",h="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico...",kw={"desvirtuado","druidas da presa","pesadelo esmeralda","lady sucurina","lorde cobrahn","lorde pítias","lorde serpentis","oásis das águas claras","mutanus","naralex","verdan"},ang={["class:Druid"]="Para druidas tanto da tradição cenariana quanto da senda tauren, as cavernas são um aviso trágico dos perigos dentro do Sonho Esmeralda e um dever solene de purgar seus irmãos decaídos, os Druidas da Presa.",["race:NightElf"]="Naralex era uma figura reverenciada entre os druidas elfos noturnos, e a tragédia de sua corrupção pelo Pesadelo Esmeralda representa uma catástrofe dolorosa para seus semelhantes do outro lado do mar.",["race:Tauren"]="As águas retorcidas ameaçam os frágeis oásis que sustentam a vida pelos Sertões, tornando a purificação das nascentes vital para as tribos de Mulgore e da Encruzilhada."},sec={{t="Uma Nobre Visão Tornada Venenosa",b="O druida elfo noturno Naralex originalmente descobriu este vasto sistema de águas e concebeu um plano ambicioso: ao abrir um canal direto para o Sonho Esmeralda, ele drenaria pura essência vital primordial através das nascentes subterrâneas, transformando os ressequidos Sertões de volta em um paraíso verdejante e próspero. Nas profundezas das cavernas, Naralex entrou em comunhão com o Sonho, ancorado por seus leais acólitos. Tragicamente, em vez de extrair vitalidade pura, a mente adormecida do druida tocou o Pesadelo Esmeralda. A corrupção purulenta apoderou-se dele instantaneamente, transformando seu canal de boas intenções em uma válvula que despeja veneno e loucura nos cursos d'água subterrâneos."},{t="Os Druidas da Presa",b="À medida que a energia sombria do Pesadelo irradiava da forma indefesa de Naralex, seus pupilos sucumbiram à loucura. Abandonando a sabedoria tranquila do Círculo Cenariano, eles formaram os fanáticos Druidas da Presa. Assumindo formas reptilianas, os líderes da seita — Lady Sucurina, Lorde Cobrahn, Lorde Pítias e Lorde Serpentis — agora abraçam a mutação venenosa das cavernas em vez de combatê-la. Eles protegem ativamente seu mestre adormecido de qualquer interferência externa, acreditando que esse crescimento retorcido é a verdadeira evolução da natureza."},{t="O Pesadelo Feito Carne",b="Quebrar o domínio dos Druidas da Presa não salva Naralex automaticamente. Quando seus discípulos restantes não corrompidos iniciam o ritual para despertá-lo suavemente de seu transe em Dreamer's Rock, o subconsciente agitado do elfo adormecido expurga violentamente seu mais profundo terror. A criatura que irrompe — um murloc monstruoso e distorcido chamado Mutanus, o Devorador — é a manifestação física dos piores pesadelos de Naralex. Apenas derrotando essa abominação o canal para o Pesadelo pode ser rompido, permitindo que Naralex acorde, assuma uma forma aviária e fuja em voo das cavernas maculadas."}},faq={{q="Por que se chama Caverna Ululante?",a="A caverna recebe esse nome devido aos uivos lamentosos ouvidos por todos os túneis. Esses sons são produzidos naturalmente quando saídas subterrâneas de vapor e rajadas de vento de alta pressão forçam passagem por fissuras estreitas na rocha calcária.",al={"por que caverna ululante","origem do nome","por que elas uivam"}},{q="O que fez com que as feras de dentro se tornassem 'desvirtuadas'?",a="Quando Naralex caiu sob o domínio do Pesadelo Esmeralda, as energias oníricas maculadas vazaram diretamente para as nascentes subterrâneas. Beber e viver nessas águas contaminadas causou mutações nos raptores, crocoliscos e serpentes naturais, transformando-os em variantes 'desvirtuadas' antinaturais.",al={"corrupção desvirtuada","por que os raptores mutacionam","origem das feras desvirtuadas"}},{q="Quem são os Druidas da Presa?",a="Eles já foram os devotos acólitos elfos noturnos e taurens de Naralex. Corrompidos junto com ele pelo Pesadelo, suas mentes se despedaçaram e distorceram suas artes druídicas em adoração a serpentes e veneno, adotando títulos como Cobrahn, Pítias e Sucurina.",al={"druidas da presa","história dos druidas da presa","quem é serpentis"}},{q="Por que o último chefe é um murloc gigante chamado Mutanus?",a="Mutanus surge durante a tentativa de despertar Naralex. Sua natureza e conexão com o druida adormecido são reveladas conforme o ritual se desenrola.",al={"por que mutanus murloc","o que é mutanus","história do último chefe"}},{q="O que acontece após Mutanus ser derrotado?",a="A tentativa dos discípulos de despertar Naralex continua após o confronto. O destino do druida é revelado ao final do ritual.",al={"despertar naralex","desfecho de naralex","o que acontece com naralex"}},{q="Quem vive na caverna acima da entrada da masmorra?",a="Instalados dentro da cavidade ocular de rocha semelhante a um crânio da caverna estão lealistas do Círculo Cenariano, incluindo Nalpak e Ebru. Eles procuram viajantes corajosos para coletar Deviate Hides e purificar a corrupção antes que ela engula completamente os Sertões.",al={"caverna acima da entrada","npcs no olho do crânio de serpente","quem são nalpak e ebru"}}},fx={["3386ab3f"]={q="O que é a Caverna Ululante?",a="A Caverna Ululante é uma extensa rede de cavernas subterrâneas que passa sob os áridos Sertões, perto do Oásis das Águas Claras. Suas nascentes subterrâneas naturais canalizam água por quilômetros sob a terra, alimentando os raros oásis de superfície espalhados pela região. Descoberta pelo druida Elfo Noturno Naralex, ela deveria ser o coração de um grande projeto de regeneração natural. Em vez disso, tornou-se um epicentro de corrupção perigosa após uma catástrofe trágica atingir os druidas lá dentro.",al={"o que é a caverna ululante","visão geral da caverna ululante","sobre a caverna ululante"}},e070a543={q="Quem vive lá embaixo?",a="As cavernas fervilham com vida selvagem antinatural e druidas rebeldes. Os seguidores corrompidos de Naralex, os Druidas da Presa, reivindicaram os túneis como seu domínio ao lado de serpentes mutantes, limos, raptores e crocoliscos. Do lado de fora do portal da instância, feras selvagens, limos e até párias espreitam nas passagens úmidas, enquanto os druidas corrompidos guardam as câmaras internas e protegem seu mestre adormecido.",al={"quem está na caverna ululante","criaturas da caverna ululante","habitantes da caverna ululante"}},["49d47201"]={q="Por que a Horda me enviou aqui?",a="A estranha mutação das feras locais e as energias fétidas que borbulham do Oásis das Águas Claras ameaçam todos os Sertões. A Horda e os druidas Cenarion de Penhasco do Trovão não podem tolerar um poder sombrio incontrolável envenenando a terra e os cursos d'água bem à porta da Encruzilhada. Você foi enviado para investigar, dar um fim aos líderes rebeldes dos Druidas da Presa e ajudar a conter o perigo crescente.",al={"por que estou na caverna ululante","missão da horda na caverna ululante","por que me enviar para a caverna ululante"}},d445bb78={q="Isso é parte de um problema maior nos Sertões?",a="Sim. Os canais subterrâneos sob essas cavernas alimentam os oásis de superfície por todos os Sertões. A mancha do Emerald Nightmare corrompendo as águas dentro das cavernas começou a transbordar para a paisagem ao redor, fazendo com que criaturas selvagens como raptores e crocoliscos sofram mutações e transformando o Oásis das Águas Claras em um criadouro para estranhas formas de vida anormais.",al={"problema no oásis dos sertões","corrupção anormal nos sertões","a caverna ululante está afetando os sertões"}},["038fd1cf"]={q="Os anormais estão se espalhando para fora das cavernas?",a="Eles já estão. As nascentes subterrâneas fluem diretamente para oásis de superfície como o Oásis das Águas Claras, trazendo crescimento antinatural e criaturas mutantes para a savana aberta. Criaturas estranhas como Peixe Anormal podem ser pescadas nas águas do lado de fora, e predadores mutantes agressivos assediam cada vez mais os viajantes entre os oásis e a Encruzilhada.",al={"os anormais estão se espalhando","feras anormais nos sertões","peixe anormal do lado de fora"}},["8502642f"]={q="Quem está no comando aqui embaixo?",a="Enquanto Naralex jaz preso em seu sono corrompido nas profundezas das cavernas, o governo diário das cavernas pertence aos Druidas da Presa. Eles são liderados pelo Lorde Serpentis, outrora o melhor aluno de Naralex, que reuniu seus irmãos distorcidos para refazer a terra em seu próprio paraíso deturpado, ao lado de outros lordes dos presas como Lorde Cobrahn, Lorde Pítias e Lady Sucurina.",al={"quem lidera a caverna ululante","líder da caverna ululante","chefe da caverna ululante"}},["32be29c8"]={q="O que é o Sonho Esmeralda e como ele se conecta a esta caverna?",a="O Sonho Esmeralda é um vasto reino espiritual que representa Azeroth intocada e selvagem, cuidado pela revoada dragônica verde e acessível aos druidas. Naralex acreditava que poderia canalizar as energias puras e restauradoras do Sonho para os aquíferos subterrâneos da Caverna Ululante para restaurar a vida vegetal exuberante aos Sertões. No entanto, quando ele acessou o Sonho, foi aprisionado pelo Emerald Nightmare, projetando uma versão distorcida da natureza nas cavernas físicas.",al={"conexão com o sonho esmeralda","caverna ululante e sonho esmeralda","naralex e sonho esmeralda"}},["38e519c2"]={q="Por que todo mundo está tão preocupado com este lugar?",a="As nascentes subterrâneas nas cavernas alimentam os oásis principais que sustentam a vida por todos os áridos Sertões. Se a mancha do Emerald Nightmare continuar a infiltrar-se naqueles cursos d'água sem controle, as mutações distorcidas e a loucura que corrompem a flora e a fauna da caverna podem se espalhar por toda a região, transformando a terra em um horror desperto.",al={"por que se preocupar com a caverna ululante","ameaça da caverna ululante aos sertões","quão ruim é a caverna ululante"}},["81917ac6"]={q="Como fui parar na Caverna Ululante?",a="Você viajou para o sul da Encruzilhada até o Oásis das Águas Claras, seguindo relatos de feras bizarras e águas corrompidas infiltrando-se pelos Sertões. Escondida atrás da folhagem exuberante e dos acampamentos dos centauros Kolkar, fica uma caverna maciça em forma de crânio esculpida na rocha. Atraído por pedidos de ajuda de Penhasco do Trovão, goblins de Vila Catraca buscando essências estranhas, ou discípulos acampados no olho do crânio acima, você desceu pelas fissuras sinuosas e pelo silvo dos gêiseres subterrâneos até as profundezas gementes abaixo.",al={"como cheguei aqui","como chego à caverna ululante","de onde vim para chegar aqui"}},["28a012f3"]={q="O que eu devo fazer na Caverna Ululante?",a="Você está aqui para expurgar a corrupção que se apoderou desta nascente subterrânea. O druida elfo noturno Naralex caiu em um sono de pesadelo tentando revitalizar os Sertões, distorcendo as criaturas lá dentro e transformando seus discípulos nos venenosos Druidas da Presa. Você deve caçar os quatro lordes dos presas — Lady Sucurina, Lorde Cobrahn, Lorde Pítias e Lorde Serpentis — para quebrar o domínio deles, e então ajudar o discípulo restante a despertar Naralex antes que seu pesadelo febril consuma o oásis completamente.",al={"qual é meu objetivo aqui","por que estou na caverna ululante","o que estou fazendo aqui embaixo"}}},fp="15,426,31.680.0,22.528.0,24.592.1,37.248.0,50.267.0,31.252.0,51.137.1,39.130.1,52.232.0"}
P.entries["zone:warsonggulch"] = {n="Ravina Brado Guerreiro",s="A Ravina Brado Guerreiro é um vale arborizado na fronteira do Vale Gris com os Sertões, e o cenário de uma batalha entre a Horda e a Aliança que nunca para de verdade. Orcs do clã Brado Guerreiro cortam a madeira do Vale Gris ali para a Horda, e os elfos noturnos de Silverwing Hold lutam para expulsá-los da floresta sagrada. Combatentes de todas as raças vêm prestar sua espada ou feitiço, cada lado invadindo a fortaleza do outro para levar sua bandeira.",h="A Ravina Brado Guerreiro é um vale arborizado na fronteira do Vale Gris com os Sertões, e o cenário de uma...",kw={"ravina brado guerreiro","campo de batalha","pioneiros do brado guerreiro","sentinelas da asa de prata","silverwing hold","warsong mill","bandeira","madeira","vale gris","grom hellscream"},ang={["faction:Alliance"]="Soldados da Aliança lutam aqui por seus aliados elfos noturnos, cuja floresta sagrada cai uma árvore por vez sob os machados do clã Brado Guerreiro.",["faction:Horde"]="Cada tora que deixa a Warsong Mill ergue uma muralha da Horda em algum lugar de Kalimdor; controlar a ravina mantém a Horda construindo.",["race:NightElf"]="Estes bosques conhecem os passos dos kaldorei há dez mil anos. Cada orc expulso da ravina é um pedaço do Vale Gris reconquistado.",["race:Orc"]="O clã Brado Guerreiro é o próprio povo de Grom Hellscream, e a ravina é onde seus guerreiros ainda honram seu nome, machado em punho contra as Sentinelas."},sec={{t="Madeira e Sangue",b="A Horda construiu seu novo lar em Kalimdor com madeira, e grande parte dessa madeira vem do Vale Gris. O clã Brado Guerreiro, guerreiros de Grom Hellscream, cortam a floresta desde o primeiro desembarque da Horda, e sua Warsong Mill no fim da ravina abastece os acampamentos e muralhas da Horda. Para os elfos noturnos, cada árvore derrubada fere uma floresta que eles guardam há dez mil anos, e eles não esqueceram que os guerreiros de Grom outrora mataram Cenarius nestes bosques."},{t="Pioneiros e Sentinelas",b="Os combatentes da Horda aqui são os Pioneiros do Brado Guerreiro, abastecidos a partir do Campo-base Mor'shan, na extremidade norte dos Sertões, onde Kelm Hargunth os mantém armados e alimentados. Contra eles estão as Sentinelas da Asa de Prata de Silverwing Hold, guerreiras elfas noturnas juradas a expulsar todos os invasores do Vale Gris, abastecidas por Iliana Fulgiluna no Bosque Asa de Prata. Aliados de ambos acorrem à ravina: anões e humanos ao lado das Sentinelas; taurens, trolls e Renegados ao lado dos Pioneiros."},{t="A Luta pelos Estandartes",b="Cada lado mantém uma fortaleza em uma das extremidades da ravina, a Warsong Mill para a Horda e Silverwing Hold para os elfos noturnos, e cada um guarda sua bandeira ali. A batalha é uma disputa de invasões: combatentes invadem a fortaleza inimiga, capturam sua bandeira e correm de volta para a sua própria enquanto os defensores os caçam. Cada bandeira levada para a base é um golpe no orgulho do inimigo, e o lado que capturar mais vence o dia."}},faq={{q="O que é a Ravina Brado Guerreiro?",a="A Ravina Brado Guerreiro é um campo de batalha em um vale arborizado entre o Vale Gris e os Sertões. Os Pioneiros do Brado Guerreiro da Horda e as Sentinelas da Asa de Prata dos elfos noturnos lutam ali pela extração de madeira do Vale Gris pela Horda, com cada lado tentando capturar a bandeira do outro.",al={"o que é a ravina brado guerreiro","campo de batalha ravina brado guerreiro","rbg"}},{q="Por que a Horda luta na Ravina Brado Guerreiro?",a="A Horda precisa da madeira do Vale Gris para construir e manter seu lar em Kalimdor. A serraria do clã Brado Guerreiro na ravina é uma de suas principais fontes, e os Pioneiros a defendem para que os acampamentos e muralhas da Horda continuem a se erguer.",al={"interesses da horda na ravina brado guerreiro","por que os orcs extraem madeira no vale gris","motivo dos pioneiros do brado guerreiro"}},{q="Por que os elfos noturnos lutam na Ravina Brado Guerreiro?",a="Para os elfos noturnos, o Vale Gris é uma floresta sagrada que eles guardam há dez mil anos, e o clã Brado Guerreiro outrora matou o semideus Cenarius ali. As Sentinelas da Asa de Prata lutam para deter a extração de madeira e expulsar os orcs de seus bosques, e o restante da Aliança está ao lado delas.",al={"interesses da aliança na ravina brado guerreiro","por que as sentinelas lutam","motivo das sentinelas da asa de prata"}},{q="Quem são os Pioneiros do Brado Guerreiro?",a="Os Pioneiros do Brado Guerreiro são os combatentes da Horda na Ravina Brado Guerreiro, originários do clã Brado Guerreiro outrora liderado por Grom Hellscream. Eles são abastecidos a partir do Campo-base Mor'shan, no norte dos Sertões, onde Kelm Hargunth equipa aqueles que lutam por eles.",al={"pioneiros do brado guerreiro","combatentes do clã brado guerreiro","kelm hargunth"}},{q="Quem são as Sentinelas da Asa de Prata?",a="As Sentinelas da Asa de Prata são guerreiras elfas noturnas de Silverwing Hold, juradas a expulsar a Horda do Vale Gris. Iliana Fulgiluna, no Bosque Asa de Prata, abastece os campeões da Aliança que lutam ao lado delas na ravina.",al={"sentinelas da asa de prata","silverwing hold","iliana fulgiluna"}},{q="Como a batalha na Ravina Brado Guerreiro é vencida?",a="Cada lado mantém sua bandeira em sua própria fortaleza. Os combatentes invadem a base inimiga, capturam sua bandeira e a levam de volta para a sua própria enquanto defendem seu estandarte, e o lado que trouxer mais bandeiras para a base vence.",al={"objetivos da ravina brado guerreiro","capturar a bandeira brado guerreiro","como vencer na ravina brado guerreiro"}}},fp="13,433,16.453.0,23.468.0,28.423.0,22.256.0,42.211.0,46.284.0,30.241.0,33.217.0,39.206.0"}
P.entries["zone:westernplaguelands"] = {n="Terras Pestilentas Ocidentais",s="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob uma névoa tóxica e legiões de mortos-vivos. Embora os caldeirões de Kel'Thuzad tenham arruinado as fazendas e cidades da região, o solo ainda se apega tenazmente à vida. A Aurora Argêntea, a Aliança, os Renegados e a Cruzada Escarlate travam campanhas desesperadas por seus campos assolados.",h="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob...",kw={"andorhal","o baluarte","castro das flechas","caldeirões","acampamento ventogelante","amparo","bastilha mardenforte","scolomântia","tumba de uther","terras pestilentas ocidentais"},ang={["class:Paladin"]="Os campos profanados de Lordaeron são uma prova sombria para guerreiros sagrados, oferecendo peregrinação à Tumba de Uther, bem como uma guerra justa contra os horrores de Scolomântia e os fanáticos corrompidos de Amparo.",["faction:Alliance"]="O Acampamento Ventogelante serve como a guarnição avançada da Aliança, onde o Comandante Ashlam Punhovalor lidera campanhas para neutralizar os caldeirões da peste e vingar as cidades caídas de Lordaeron.",["faction:Horde"]="O Baluarte marca a fronteira da soberania dos Renegados; a partir daqui, a Horda avança para o leste para neutralizar comandantes do Flagelo e combater os fanáticos Escarlates ao longo de seu flanco vulnerável.",["profession:Herbalism"]="A mácula persistente faz da região um dos poucos lugares onde flora rara e perigosa, como Pragônia e Lágrimas-de-arthas, consegue criar raízes entre os pinheirais assolados."},sec={{t="O Celeiro de Lordaeron",b="Antes da Terceira Guerra, esta terra era um corredor verdejante de fazendas que se estendia a leste das Clareiras de Tirisfal até o Lago das Flechas. Amparo governava a administração do norte a partir da Bastilha Mardenforte, enquanto a vasta cidade de Andorhal orquestrava o armazenamento e a exportação de grãos por todo o reino. Esse papel agrícola crucial tornou a região o alvo principal de Kel'Thuzad. Ao introduzir a Peste da Morte-viva diretamente nas remessas de grãos em Andorhal, a Seita dos Malditos transformou o sustento de Lordaeron em sua ruína."},{t="Uma Terra Sob Cerco",b="Para envenenar o solo de forma permanente, o Flagelo ergueu quatro enormes caldeirões da peste pelas maiores propriedades agrícolas: Campo Pedravil, Lágrimas de Dalson, o Antro Repelente e a Aridez de Garrão. Hoje, monstruosos Senhores dos Caldeirões mantêm essas cubas nocivas, bombeando névoa venenosa na atmosfera. As árvores ao redor se retorcem com crescimentos tumorais inchados, e animais selvagens corrompidos vagam descontrolados pela vegetação. Sob o Castro das Flechas, no Lago das Flechas, o Umbromestre Gandling treina necromantes dentro de Scolomântia, agravando a ameaça dos mortos-vivos."},{t="Facções Divididas",b="Apesar da onipresença do Flagelo, várias facções mantêm posições disputadas. a Cruzada Escarlate controla a fortaleza de Amparo no norte, expurgando com zelo raivoso qualquer coisa que considerem contaminada. Ao sul, as forças da Aliança se organizam a partir do Acampamento Ventogelante, enquanto os Renegados defendem suas fronteiras no Baluarte. Mediando e liderando a luta contra os caldeirões dos mortos-vivos está a neutra Aurora Argêntea, que ajuda campeões de ambas as facções e guarda a Tumba de Uther — o último solo verdadeiramente santificado da região."}},faq={{q="Por que a Peste atingiu esta área com tanta força?",a="Andorhal era o centro de distribuição agrícola do norte de Lordaeron. Kel'Thuzad atacou intencionalmente o suprimento regional, infectando silos de grãos e instalando enormes caldeirões da peste em quatro grandes propriedades rurais para espalhar rapidamente a morte-viva por meio de remessas de alimentos por todo o reino.",al={"por que as terras pestilentas ocidentais foram assoladas","o que aconteceu com andorhal","por que caldeirões aqui"}},{q="Quem controla Amparo no norte?",a="Amparo e sua fortaleza, a Bastilha Mardenforte, são governadas pela Cruzada Escarlate. Embora originalmente tenha sido um centro administrativo regional de Lordaeron, os fanáticos agora executam qualquer forasteiro que se aproxime de suas fronteiras, vendo todos os não membros da cruzada com suspeita.",al={"facção de amparo","quem vive na bastilha mardenforte","amparo é amigável"}},{q="Onde os jogadores da Aliança e da Horda podem encontrar postos avançados seguros?",a="A Aliança mantém o Acampamento Ventogelante perto da fronteira sul com as Montanhas de Alterac, oferecendo um mestre de voo e aliados da Aurora Argêntea. A Horda opera a partir d'O Baluarte, na fronteira oeste com as Clareiras de Tirisfal.",al={"onde ficam as rotas de voo","acampamento da horda tpo","acampamento da aliança tpo"}},{q="Qual é o objetivo dos caldeirões da peste nos campos?",a="Erigidos pela Seita dos Malditos no Campo Pedravil, nas Lágrimas de Dalson, n'O Antro Repelente e na Aridez de Garrão, esses caldeirões bombeiam vapores constantes da peste para o ar e o solo. Agentes da Aurora Argêntea recrutam aventureiros para abater os Senhores dos Caldeirões e neutralizar as misturas tóxicas.",al={"o que são os caldeirões","objetivo dos caldeirões","caldeirão de pedravil"}},{q="O que é Scolomântia e onde ela fica?",a="Scolomântia é uma academia subterrânea de necromancia administrada pelo Flagelo e pela Seita dos Malditos. Ela fica escondida sob as ruínas do Castro das Flechas, uma fortaleza insular situada nas águas a sudeste do Lago das Flechas.",al={"localização de scolomântia","onde fica scolomântia","masmorra castro das flechas"}},{q="Alguma parte das Terras Pestilentas Ocidentais permaneceu pura?",a="A Tumba de Uther, localizada na Colina do Pesar perto do limite sul da zona, permanece totalmente sagrada e intocada pela praga. Ela se ergue como um memorial consagrado ao falecido Alto-general Uther, o Arauto da Luz, e à perdida Ordem do Punho de Prata.",al={"solo sagrado em tpo","a tumba de uther está limpa","a tumba de uther é segura"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:westfall"] = {n="Cerro Oeste",s="Outrora o fértil celeiro do Reino de Ventobravo, Cerro Oeste entrou em colapso, tornando-se um território esquecido e fustigado pelo vento, dominado por foras da lei. Desprovidos do apoio oficial da coroa e de guarnições militares, seus colonos sobreviventes se apegam às suas fazendas enquanto a Irmandade Défias aperta o cerco a partir da cidade mineradora abandonada de Arroio da Lua.",h="Outrora o fértil celeiro do Reino de Ventobravo, Cerro Oeste entrou em colapso, tornando-se um território...",kw={"minas mortas","défias","golem de colheita","milícia","arroio da lua","saldanha","morro da sentinela","stoutmantle","vancleef","cerro oeste"},ang={["class:Rogue"]="A guerra nas sombras em Cerro Oeste coloca espiões da AVIN diretamente contra batedores, ladrões e assassinos astutos da Irmandade Défias.",["faction:Alliance"]="Sem a People's Militia mantendo Morro da Sentinela, a Irmandade Défias controlaria os acessos ao sul direto para a Floresta de Elwynn.",["profession:Cooking"]="Os colonos sitiados na Fazenda dos Saldanha se viram com as feras resistentes locais, ensinando viajantes a preparar o prato substancial conhecido como Westfall Stew.",["race:Human"]="Cerro Oeste é um doloroso reflexo da decadência política de Ventobravo; os fazendeiros passando fome na terra foram abandonados pela mesmíssima nobreza que trabalhavam duro para alimentar."},sec={{t="Uma terra deixada para trás",b="Por gerações, Cerro Oeste alimentou o Reino de Ventobravo. Suas pastagens verdejantes e campos de trigo floresciam até que as consequências da Segunda Guerra trouxeram exaustão financeira e negligência política. Quando o reino concentrou seus recursos em outros lugares e deixou de manter suas guarnições, o território ficou em pousio. Hoje, pastagens estéreis, rajadas costeiras uivantes, golens de colheita desgovernados e gnolls Patarrívia saqueadores fazem da sobrevivência diária uma provação constante para os poucos obstinados que se recusam a abandonar seus lares."},{t="A ascensão da Irmandade",b="O colapso de Cerro Oeste se acelerou quando a Guilda dos Pedreiros, tendo o pagamento pela reconstrução de Ventobravo negado, entrou em revolta aberta. Declarados foras da lei e exilados sob o comando de Edwin VanCleef, os pedreiros se reconstituíram como a Irmandade Défias. Eles reivindicaram Cerro Oeste como sua fortaleza, queimando as plantações dos fazendeiros obstinados, salgando a terra e tomando minas abandonadas. Operando a partir da cidade-fantasma de Arroio da Lua, a Irmandade agora governa a maior parte do campo em quase tudo, menos no nome."},{t="Milícia Popular",b="Com a Casa dos Nobres ignorando a situação desesperadora de Cerro Oeste, os habitantes locais assumiram a própria defesa. Com base no posto fortificado de Morro da Sentinela, Gryan Stoutmantle organizou a People's Militia — uma força voluntária que tenta manter a linha contra gnolls e bandidos. Sem soldados formais e suprimentos de Ventobravo, a Militia depende de aventureiros errantes para conter a maré Défias e proteger as fazendas restantes."},{t="A conspiração das Minas Mortas",b="A verdadeira escala da ameaça Défias permanece oculta sob a superfície. Nas profundezas dos poços de ouro abandonados das Minas Mortas, sob Arroio da Lua, Edwin VanCleef reuniu um exército de degoladores, goblins e renegados. Em vez de mero banditismo, a Irmandade está construindo um colossal encouraçado projetado para navegar pela costa e bombardear Ventobravo diretamente."}},faq={{q="Por que tantas fazendas estão abandonadas em Cerro Oeste?",a="Ventobravo retirou suas guarnições militares quando os custos de manutenção se tornaram caros demais, deixando a região desprotegida. Pouco depois, a Irmandade Défias assumiu o controle do campo, expulsando colonos, queimando plantações e reprogramando vigias da colheita mecânicos em sentinelas letais.",al={"fazendas abandonadas","por que cerro oeste morreu","por que em pousio"}},{q="Por que Ventobravo não envia tropas para ajudar Cerro Oeste?",a="O tesouro do reino está esgotado, e a Casa dos Nobres considera as ameaças em outras terras como prioridades maiores. Além disso, manipulações na corte silenciosamente privaram Cerro Oeste de atenção e suprimentos, forçando os moradores locais a se defenderem completamente por conta própria.",al={"por que nenhum exército de ventobravo","onde estão os guardas","ajuda de ventobravo"}},{q="O que é a People's Militia?",a="A People's Militia é uma organização de defesa voluntária criada por Gryan Stoutmantle em Morro da Sentinela. Como a coroa se recusou a enviar soldados para Cerro Oeste, os fazendeiros e colonos restantes se uniram para combater a Irmandade Défias e os gnolls Patarrívia.",al={"Milícia Popular","milícia de morro da sentinela","exército de gryan stoutmantle"}},{q="Quem lidera a Irmandade Défias em Cerro Oeste?",a="Edwin VanCleef, o antigo grão-mestre da Guilda dos Pedreiros que supervisionou a reconstrução de Ventobravo. Após uma disputa amarga sobre pagamentos resultar em motins, VanCleef liderou seus trabalhadores até Cerro Oeste e partiu para a insurreição armada.",al={"líder défias","quem lidera os défias","vancleef"}},{q="O que está escondido dentro de Arroio da Lua?",a="Sob um celeiro discreto em Arroio da Lua fica a entrada para as Minas Mortas, uma extensa mina de ouro abandonada que a Irmandade Défias converteu em fortaleza subterrânea e estaleiro para sua guerra contra Ventobravo.",al={"segredo de arroio da lua","o que há nas minas mortas","mina de arroio da lua"}},{q="Por que os espantalhos mecânicos estão atacando as pessoas?",a="Originalmente construídos para cuidar das plantações e afastar pragas, esses vigias da colheita mecânicos foram capturados e adaptados por funileiros goblins aliados aos Défias para patrulhar os campos e assassinar invasores.",al={"golens de colheita atacando","vigias da colheita","espantalhos malignos"}}},fx={cd1e134e={q="O que é o Cerro Oeste?",a="Cerro Oeste é o território ocidental varrido pelos ventos do Reino de Ventobravo, situado a oeste da Floresta de Elwynn e ao sul do mar. Outrora o celeiro fértil do reino, suas colinas ondulantes e vastas pastagens alimentaram Ventobravo por gerações. Hoje, negligenciado pela coroa e devastado pelo conflito, deteriorou-se em planícies de poeira improdutivas, propriedades rurais arruinadas e território de fora da lei.",al={"que zona é esta","fale-me sobre o cerro oeste","lore do cerro oeste"}},["44cadea7"]={q="Por que é tão vazio por aqui?",a="Uma combinação composta de seca, negligência e banditismo esvaziou o campo. Após a Segunda Guerra, Ventobravo concentrou seus soldados em outros lugares, deixando as propriedades locais indefesas. Quando a Irmandade Défias se levantou, eles expulsaram fazendeiros, queimaram plantações e salgaram campos. Sem guarnições reais para protegê-los, a maioria dos habitantes fugiu ou morreu de fome.",al={"por que o cerro oeste é estéril","por que tão vazio","por que não há ninguém aqui"}},["1a97e791"]={q="O Cerro Oeste sempre foi tão pobre?",a="De jeito nenhum. Por gerações, o Cerro Oeste foi o orgulhoso coração agrícola de Ventobravo, celebrado por campos de trigo dourados, solo rico e minas de ouro abundantes como Jangolode e as Minas Mortas. Sua comida alimentava a capital, e suas minas enchiam os tesouros reais antes que guerras e agitação doméstica o deixassem estéril.",al={"o cerro oeste sempre foi pobre","o cerro oeste era rico antes","passado do cerro oeste"}},["1d4a9481"]={q="O que é a Irmandade Défias?",a="A Irmandade Défias é uma organização criminosa massiva composta por pedreiros rebeldes, ladrões, bandoleiros e párias. Liderados por Edwin VanCleef, eles tomaram as fazendas e minas abandonadas do Cerro Oeste para travar uma amarga guerra das sombras contra o Reino de Ventobravo, com a intenção de exigir retribuição por dívidas não pagas e traições percebidas.",al={"quem são os defias","o que é a Irmandade Défias","quem são esses bandidos"}},b6953315={q="Por que os Defias usam bandanas vermelhas?",a="Bandanas vermelhas são a marca registrada da Irmandade Défias, e o material indica a patente de um membro. Red Silk Bandanas identificam membros de patente mais alta; a Batedora Riell pede que aventureiros as coletem como prova de suas mortes.",al={"por que bandanas vermelhas","máscaras vermelhas defias","significado das máscaras vermelhas"}},["908b4fe1"]={q="O que os Defias querem no Cerro Oeste?",a="Eles tratam o Cerro Oeste como sua fortaleza soberana e base de operações. Ao controlar suas minas de ouro, apreender suprimentos de comida e expulsar fazendeiros legalistas, eles podem secretamente construir suas forças e maquinário longe da vista direta de Ventobravo enquanto tramam a queda do reino.",al={"o que os defias querem","objetivos dos defias no cerro oeste","por que os defias estão no cerro oeste"}},d384bc2d={q="Por que fui enviado para o Cerro Oeste?",a="Você foi enviado para cá porque o exército regular de Ventobravo se recusa a mobilizar tropas para o Cerro Oeste, ou falha em fazê-lo, deixando o território à beira de cair completamente no banditismo. As autoridades da Floresta de Elwynn redirecionam aventureiros capazes para o oeste para reforçar os habitantes locais, que estão desesperados por ajuda.",al={"por que estou no cerro oeste","quem me enviou para o cerro oeste","por que me enviar para cá"}},d59f010f={q="Quem é Gryan Stoutmantle?",a="Gryan Stoutmantle é um paladino da Mão de Prata e natural do Cerro Oeste. Ao retornar para casa após lutar em Lordaeron durante a Terceira Guerra, ele encontrou sua terra natal invadida por bandidos e abandonada pelo exército de Ventobravo. Em resposta, ele reuniu defensores locais para estabelecer a Milícia Popular no Morro da Sentinela.",al={"quem é stoutmantle","gryan stoutmantle","quem lidera o morro da sentinela"}},af1c3ddb={q="Gryan Stoutmantle está realmente no comando do Cerro Oeste?",a="Na prática, sim. Embora o rei-menino em Ventobravo detenha a reivindicação legal do Cerro Oeste, a coroa quase não exerce autoridade real aqui. Stoutmantle e sua milícia voluntária no Morro da Sentinela representam a única defesa e força policial funcional que resta no reino.",al={"quem governa o cerro oeste","stoutmantle é o líder","quem está no comando"}},c01912f7={q="O que aconteceu com a Guilda dos Alvenéis?",a="Sob o comando do Grão-mestre Edwin VanCleef, a Guilda dos Alvenéis passou anos reconstruindo Ventobravo após a Primeira Guerra. Quando o trabalho foi concluído, a Câmara dos Nobres recusou-se a pagar a quantia combinada. Após o fracasso de apelos pacíficos, a guilda foi dissolvida à força, desencadeando tumultos furiosos que levaram os pedreiros ao exílio.",al={"o que aconteceu com os alvenéis","história da guilda dos alvenéis","quem eram os alvenéis"}},ec2fd06e={q="Ventobravo realmente se recusou a pagar os Pedreiros?",a="Sim. A Câmara dos Nobres havia acumulado dívidas impressionantes expandindo expedições militares em outros lugares, deixando o reino quase falido. Influenciados por intrigas da corte e pela arrogância aristocrática, os nobres ofereceram apenas trocados por um trabalho colossal, recusando-se abertamente a honrar os contratos completos.",al={"ventobravo enganou os pedreiros","por que os nobres não pagaram","disputa de pagamento dos pedreiros"}},cf60f690={q="Por que há tantos gnolls no Cerro Oeste?",a="Os gnolls da matilha Pata-de-Rio migraram através da fronteira para explorar a ausência de soldados de Ventobravo. Pior, a Irmandade Défias os contratou ativamente como mercenários, posicionando-os pelas colinas e planícies para emboscar viajantes e assediar quaisquer propriedades que ainda resistissem.",al={"por que há gnolls aqui","gnolls pata-de-rio cerro oeste","gnolls de danuvin"}},e40fa3bd={q="O que é Arroio da Lua?",a="Arroio da Lua já foi o principal mercado e cidade mineradora do sul do Cerro Oeste. Situada acima da entrada antiga para as Minas Mortas, foi completamente tomada e esvaziada pela Irmandade Défias, que agora usa seus prédios vazios como um perímetro de guarda para sua fortaleza subterrânea.",al={"o que é arroio da lua","lore de arroio da lua","conte-me sobre arroio da lua"}},["46f1c864"]={q="Para onde leva a investigação da Defias?",a="Sua investigação revela o coração secreto da Irmandade sob Arroio da Lua, nas Minas Mortas. Lá, nas profundezas das cavernas subterrâneas, Edwin VanCleef supervisiona a construção de um enorme navio de guerra revestido de ferro, destinado a bombardear Ventobravo a partir do mar, o que leva a um ataque direto ao próprio mestre da guilda.",al={"para onde vai a série de missões da défias","como termina a história da défias","conclusão das minas mortas"}},["27471424"]={q="Como eu vim parar no Cerro Oeste?",a="Você provavelmente atravessou a ponte do rio vindo da Floresta de Elwynn seguindo a estrada para o oeste, enviado por autoridades ou amigos do Morro da Sentinela. Com as forças de Ventobravo reduzidas e incapazes de poupar tropas reais, espalhou-se pelas terras vizinhas que Gryan Stoutmantle e os fazendeiros locais precisam desesperadamente de mãos capazes. Quer você tenha chegado atendendo a um chamado por ajuda ou simplesmente seguido a estrada real em busca de trabalho, você entrou em um reino que os soldados do reino praticamente abandonaram.",al={"como cheguei aqui","como cheguei ao cerro oeste","como vim parar aqui"}},["6324593c"]={q="O que eu devo fazer no Cerro Oeste?",a="Sua missão principal é ajudar a Milícia Popular no Morro da Sentinela a repelir a miríade de ameaças que sufocam a província. Gryan Stoutmantle precisa de voluntários para eliminar a vida selvagem agressiva, silenciar os vigias da colheita renegados que rondam os campos em pousio e repelir os gnolls Pata-de-Rio. Acima de tudo, você tem a tarefa de caçar a esquiva Irmandade Défias, descobrir onde eles estão se escondendo e quebrar seu domínio sobre o que resta das fazendas em dificuldade do Cerro Oeste.",al={"o que devo fazer aqui","o que estou fazendo no cerro oeste","por que estou aqui"}}},fp="8,337,18.502.0,27.479.0,20.427.0,24.379.1,44.289.0,52.262.0,29.269.0,45.237.0,32.226.1,51.200.0"}
P.entries["zone:wetlands"] = {n="Pantanal",s="O Pantanal é um pântano vasto e envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da Baía de Baradin. Historicamente castigado por guerras dos anões e invasões órquicas, serve como uma zona de amortecimento rústica entre Altaforja e as terras do norte de Lordaeron. O porto fortificado do Porto de Menethil ergue-se como a principal tábua de salvação da Aliança em uma vastidão empapada dominada por orcs Presa do Dragão, murlocs e gnolls.",h="O Pantanal é um pântano vasto e envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da...",kw={"baía de baradin","presa do dragão","dun algaz","dun modr","grim batol","menethil","porto de menethil","ponte thandol","pantanal"},ang={["faction:Alliance"]="O Porto de Menethil serve como a principal porta de entrada em águas profundas da Aliança através do Grande Oceano, ligando os reinos do leste a postos avançados expedicionários em Kalimdor.",["profession:Mining"]="As colinas e profundezas cavernosas da Rocha de Thelgen guardam ricos veios minerais, incluindo depósitos raros de Minério de Incendicita cobiçados por mineradores e engenheiros anões.",["race:Dwarf"]="Para os anões, o Pantanal é um lugar agridoce marcado pela perda de Dun Modr, pela antiga tragédia de Grim Batol e pelo trabalho contínuo de defender a rota comercial do Rei Magni para o norte."},sec={{t="Uma Terra de Água e Ruína",b="Espalhando-se sob o precipício imponente do Dique Lapidado, o Pantanal é uma extensão fria e encharcada, coberta por névoa perpétua e céus cinzentos uniformes. Embora outrora tenha sido o lar de prósperos assentamentos de anões, os pântanos agora estão repletos de ruínas de pedra afundadas, charcos empapados e atoleiros traiçoeiros. Os aventureiros que entram na região precisam navegar por desfiladeiros estreitos, seja vindo para o norte através do desfiladeiro barricado de Dun Algaz, vindo de Loch Modan, ou cruzando os imponentes arcos da Ponte Thandol, a partir do Planalto Arathi."},{t="As Cicatrizes de Grim Batol",b="Os limites orientais do pântano são dominados pela presença sombria de Grim Batol, a antiga fortaleza dos Martelo Selvagem. Após sua profanação durante a Guerra dos Três Martelos, tornou-se o reduto fortificado do clã Presa do Dragão durante a Segunda Guerra. Quando a revoada dragônica vermelha se libertou do cativeiro órquico, sua vingança ardente despedaçou as forças órquicas e devastou as encostas ao redor. Hoje, draconianos vermelhos guardam os Portões Presa do Dragão contra todos os invasores, enquanto remanescentes selvagens do clã Presa do Dragão habitam em acampamentos espalhados pelas colinas, continuando a atormentar os viajantes pelo pântano."},{t="Porto da Costa Oeste",b="Empoleirado na borda da Baía de Baradin, o Porto de Menethil é o coração pulsante do comércio e da logística da Aliança em Khaz Modan. Batizado em homenagem ao Rei Terenas Menethil II, este porto resoluto conecta os Reinos do Leste à distante Kalimdor por meio de navios de transporte regulares que navegam para a Ilha Theramore e, passando pela Costa Sul, para Auberdine. Apesar de sua importância militar estratégica e sólida arquitetura anã, o porto está perpetuamente sob ameaça de murlocs costeiros, criaturas do pântano e saqueadores costeiros que atacam embarcações navegando pelos canais rochosos."},{t="Fronteiras Sitiadas",b="O Pantanal é uma zona de guerra em várias frentes. No extremo norte, anões Ferro Negro sob o comando do bruxo Balgaras, o Asqueroso, sabotaram a Ponte Thandol com explosivos e invadiram Dun Modr, interrompendo as rotas de abastecimento por terra. Enquanto isso, gnolls Pelemusgo assolam os pântanos centrais e ameaçam até guardiões antigos como Rethiel, o Verdião. Entre bandos de orcs renegados, infiltrados Ferro Negro e naufrágios amaldiçoados na costa, manter a região segura exige vigilância constante."}},faq={{q="Como viajo para o Pantanal a pé?",a="Os aventureiros da Aliança geralmente viajam para o norte a partir de Loch Modan através da passagem montanhosa de Dun Algaz. Os viajantes da Horda que vêm do norte podem cruzar a Ponte Thandol a partir do Planalto Arathi. Tome cuidado, pois ambas as passagens são disputadas por forças hostis, como orcs Presa do Dragão e anões Ferro Negro.",al={"como chegar ao pantanal","caminho para o pantanal","correr para o pantanal"}},{q="Para onde vão os barcos no Porto de Menethil?",a="As docas no Porto de Menethil operam duas rotas principais de balsa para Kalimdor: um navio atraca na Costa Sul, no Contraforte de Eira dos Montes, e então navega pelo Grande Oceano até Auberdine, nas margens da Costa Negra, enquanto o outro navega para o sul até a Ilha Theramore, no Pântano Vadeoso.",al={"barcos de menethil","navios do porto de menethil","para onde vai o barco no pantanal"}},{q="O que é Grim Batol e por que é guardado?",a="Grim Batol é uma antiga fortaleza dos anões abandonada após a Guerra dos Três Martelos e mais tarde ocupada pelo clã Presa do Dragão. Após a Segunda Guerra, a revoada dragônica vermelha libertada expulsou os orcs e selou a montanha. Poderosos draconídeos e draconianos vermelhos patrulham os Portões Presa do Dragão para impedir que alguém entre nos salões amaldiçoados.",al={"por que há dragões em grim batol","dragões vermelhos de grim batol","portões presa do dragão"}},{q="O que aconteceu com Dun Modr?",a="Dun Modr era uma fortaleza anã do norte que protegia a Ponte Thandol. Recentemente, foi atacada e tomada por anões Ferro Negro liderados por Balgaras, o Asqueroso. Os sobreviventes, comandados por Rhag Garmason, mantêm um acampamento sitiado nas proximidades enquanto tentam recuperar a cidade.",al={"quem destruiu dun modr","ruínas de dun modr","ferro negro em dun modr"}},{q="Quem é Rethiel, o Verdião?",a="Rethiel é uma antiga besta do pântano que reside na Zona Verde do Pantanal. Ele busca a ajuda de viajantes para conter a investida dos agressivos gnolls Pelemusgo e abater Rastejantes do Pântano doentes para que os pântanos possam se recuperar.",al={"Cinturão Verde","Rethiel no Pantanal","quem é Rethiel, o Verdião"}},{q="De onde vieram todos os orcs no pântano?",a="Os orcs pertencem ao clã Presa do Dragão, que originalmente se fortificou em Grim Batol durante a Segunda Guerra. Depois de serem devastados pela revoada dragônica vermelha libertada, os orcs sobreviventes fugiram para o pântano e para as colinas, onde ainda realizam ataques em estradas e contra viajantes.",al={"por que há orcs no pantanal","presa do dragão pantanal","clã presa do dragão pantanal"}}},fx={["2cd88152"]={q="O que é o Pantanal?",a="O Pantanal é um pântano frio e vasto, aninhado entre as montanhas de Khaz Modan e o mar ocidental. Envolto em névoas cinzentas perpétuas, situa-se imediatamente ao norte de Loch Modan e ao sul do Planalto Arathi. Antigamente lar de inúmeros assentamentos anões, a região foi devastada por guerras passadas e agora é uma região selvagem, bruta e indomada, que divide os reinos anões das Ruínas de Lordaeron.",al={"o que é o pantanal","lore do pantanal","conte-me sobre o pantanal"}},["4984d286"]={q="Por que tudo aqui é pântano?",a="O Pantanal fica em uma bacia baixa, delimitada em três lados por cordilheiras imponentes, captando o escoamento e a drenagem das alturas acima. É alimentado por inúmeros rios, lagos e riachos que descem em direção à Baía de Baradin, mantendo a terra perpetuamente saturada e fria.",al={"por que o pantanal é um pântano","geografia do pantanal","por que tanta água no pantanal"}},["60c5b961"]={q="Quem vive no Pantanal?",a="A principal presença civilizada é a Aliança no Porto de Menethil, ao lado de montanheses anões que lutam para manter postos avançados importantes. No entanto, a região selvagem é dominada por forças hostis: orcs do clã Focodragão renegados escondidos nas colinas orientais, gnolls Pele-de-Musgo rondando os pântanos, murlocs rastejando ao longo da costa e anões Ferro Negro violentos avançando para o sul a partir de Dun Modr.",al={"quem vive aqui","facções do pantanal","habitantes do pantanal"}},["8d21dccb"]={q="O que é o Porto de Menethil e quem o administra?",a="O Porto de Menethil é uma cidade portuária fortemente fortificada, construída em uma ilha na Baía de Baradin, servindo como o principal portal costeiro da Aliança em Khaz Modan. Nomeado em homenagem ao Rei Terenas Menethil II de Lordaeron, é mantido por anões e humanos aliados, protegido pelas paredes de pedra robustas da Bastilha Menethil e guardado pela guarnição do Capitão Punhoforte.",al={"porto de menethil","quem administra menethil","cidade de menethil"}},fd9bb568={q="Por que os anões construíram um porto aqui?",a="Durante a Segunda Guerra, Orgrim Martelo da Perdição construiu um estaleiro aqui para transportar a Horda através da Baía de Baradin para Lordaeron. Depois de expulsar os orcs, a Aliança recuperou o local e o reconstruiu em um porto próspero, estabelecendo rotas de abastecimento marítimo essenciais que ligam Khaz Modan tanto aos aliados humanos quanto a terras distantes do outro lado do mar.",al={"por que o porto de menethil","por que construir um porto no pântano","razão para o porto de menethil"}},["4cff40a7"]={q="O Porto de Menethil é território da Aliança?",a="Sim. O Porto de Menethil é um reduto oficial da Aliança. Embora seja uma cidade portuária agitada e rústica, cheia de marinheiros, mercadores, viajantes e estivadores brutos, ela hasteia a bandeira da Aliança e é defendida pelas forças de Altaforja.",al={"menethil é aliança","facção do porto de menethil","quem é dono do porto de menethil"}},["6dc9c02b"]={q="Quem está no comando por aqui?",a="Não há um governante único sobre a região pantanosa indomada. A autoridade da Aliança está concentrada no Porto de Menethil sob o Capitão Punhoforte e a guarnição dentro da Bastilha Menethil. Fora das muralhas do porto, o pântano é uma fronteira sem lei disputada por patrulhas militares, senhores da guerra orcs e bestas primitivas.",al={"quem lidera o pantanal","comandante do pantanal","quem é o chefe aqui"}},b8a9f96f={q="Quem é o Capitão Punhoforte?",a="O Capitão Punhoforte é o comandante anão encarregado da guarnição no Porto de Menethil. Da segurança do porto, ele coordena as operações defensivas por todo o pântano, encarregando aventureiros capazes de conter os ataques implacáveis dos orcs Focodragão próximos.",al={"capitão punhoforte pantanal","lore de punhoforte","quem é punhoforte"}},["38351a9f"]={q="Quem são os orcs Focodragão e por que estão aqui?",a="Os Focodragão são um clã de orcs brutal que usou a Alma Demoníaca para escravizar Alexstrasza e a revoada dragônica vermelha durante a Segunda Guerra, governando a partir das alturas de Grim Batol. Quando a Rainha dos Dragões foi libertada, os dragões vingativos destruíram o clã, espalhando os sobreviventes pelos pântanos e montanhas do Pantanal, onde permanecem como uma ameaça violenta e persistente.",al={"focodragão pantanal","por que os focodragão estão no pantanal","orcs focodragão"}},ecc875bb={q="Quem são os anões Ferro Negro e por que estão atacando Dun Modr?",a="Os Ferro Negro são um clã de anões traiçoeiros que dominam as sombras e há muito tempo estão exilados de Altaforja. Aproveitando o deslocamento das forças da Aliança para terras distantes, avançaram rumo ao norte, tomando Dun Modr e sabotando a Ponte Thandol para cortar comunicações vitais e recuperar territórios em Khaz Modan.",al={"ferro negro dun modr","por que os ferro negro estão no pantanal","ataque dos ferro negro ao pantanal"}},["0f0d7fa8"]={q="O que é a Ponte Thandol e por que ela é importante?",a="A Ponte Thandol é um par magnífico de enormes pontes de pedra anãs que atravessam o abismo entre o norte de Khaz Modan e o Planalto Arathi. Construída após a Guerra dos Três Martelos para facilitar o comércio e a união com os Martelo Feroz, ela continua sendo a única ligação terrestre entre os reinos do sul e o norte de Lordaeron.",al={"ponte thandol","por que a ponte thandol é importante"}},faff9f74={q="Por que os Ferro Negro querem explodi-la?",a="Ao destruir a Ponte Thandol, os Ferro Negro pretendem isolar completamente Altaforja e Khaz Modan dos aliados da Aliança em Lordaeron. Cortar essa linha vital terrestre impede que reforços marchem para o sul para retomar Dun Modr ou ajudar contra novas incursões dos Ferro Negro.",al={"por que destruir a ponte thandol","trama dos ferro negro na ponte","explodir a ponte thandol"}},eabba297={q="Como vim parar no Pantanal e para onde devo ir depois?",a="A maioria dos viajantes chega marchando para o norte através da passagem montanhosa de Dun Algaz, vindo de Loch Modan, ou fazendo a longa viagem de barco até o Porto de Menethil. A partir daqui, a estrada continua para o norte através da Ponte Thandol até o Planalto Arathi, enquanto os navios que partem dos ancoradouros levam os aventureiros para o oeste, atravessando O Grande Oceano.",al={"para onde ir depois do pantanal","próxima zona do pantanal","caminho do pantanal"}},["75fb0ece"]={q="Esta é a estrada para Altaforja?",a="Sim. Seguir a estrada para o sul, saindo do pântano, leva você diretamente aos túneis estreitos de Dun Algaz. Passar pelas montanhas leva você a Loch Modan, de onde a estrada principal segue para o oeste pelo Desfiladeiro do Portão Norte diretamente para as neves de Dun Morogh e Altaforja.",al={"estrada para altaforja pantanal","como ir para altaforja a partir do pantanal","caminho para altaforja"}},["78aee5e0"]={q="Como vim parar no Pantanal?",a="A maioria dos viajantes da Aliança chega ao Pantanal indo para o norte de Loch Modan, enfrentando os estreitos túneis montanhosos de Dun Algaz para descer até os pântanos enevoados abaixo. Outros chegam de navio de além de O Grande Oceano, navegando até o Porto de Menethil vindo das costas de Kalimdor. Aqueles que se aventuram ao sul do Planalto Arathi devem, em vez disso, navegar pelas perigosas passagens da arruinada Ponte Thandol.",al={"como cheguei aqui","como cheguei ao pantanal","de onde eu vim"}},["87ca94d2"]={q="O que devo fazer no Pantanal?",a="O pântano é uma fronteira sitiada onde a Aliança se mantém em uma posição frágil. Do Porto de Menethil, você é chamado para proteger rotas comerciais essenciais e repelir os orcs Presa de Dragão remanescentes que atacam as terras baixas. Mais a leste e ao norte, os montanhistas anões precisam do seu aço para conter bandos hostis de gnolls, ajudar locais de escavação sitiados e repelir os anões Ferro Negro que ameaçam cortar a Ponte Thandol por completo.",al={"o que devo fazer aqui","por que estou aqui","qual é minha missão no pantanal"}}},fp="8,418,24.524.0,23.601.0,22.553.0,18.503.0,40.301.0,41.269.0,41.343.0,26.268.0,31.214.0,46.277.0"}
P.entries["zone:winterspring"] = {n="Hibérnia",s="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima das florestas encantadas da Clareira da Lua e da Selva Maleva. Conhecida por seu frio congelante, ruínas ancestrais de Altaneiros e predadores de topo errantes, a região tem como ponto central o posto avançado goblin neutro de Visteterna. O local segue sendo uma terra de perigos naturais ferozes, abrigando resquícios da revoada dragônica azul enquanto enfrenta a corrupção demoníaca ao longo de suas elevações ao sul.",h="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima...",kw={"dragões azuis","garganta do sussurro sombrio","bruna covaneve","visteterna","sabre-de-gelo","chapéu-de-gelo","kel'theril","mazthoril","presamatos","hibérnia"},ang={["class:Druid"]="Localizada bem acima da Clareira da Lua, Hibérnia guarda grande importância sagrada como o local onde Malfurion Tempesfúria despertou os Druidas da Garra de seu sono ancestral durante a Terceira Guerra.",["faction:Alliance"]="Heróis da Aliança visitam com frequência Ripárion Glaciares na Pedra Sabre-de-gelo, trabalhando sem parar no frio extremo para conquistar a lealdade das prestigiosas montarias de Sabre-de-gelo de Hibérnia.",["profession:Herbalism"]="Hibérnia é o único habitat conhecido do Chapéu-de-gelo, uma erva alpina indispensável e muito visada para poções alquímicas avançadas, junto com pés espalhados de Sálvia-prata-da-montanha e raras flores de Lótus Preto.",["profession:Mining"]="Os penhascos congelados e as paredes de cavernas por todo o vale são ricos em minerais valiosos, frequentemente abrigando Pequenas Veias de Tório e Veias Ricas de Tório, além de raros depósitos de Veraprata.",["race:NightElf"]="Hibérnia está intimamente ligada à história élfica, abrigando os túmulos subterrâneos onde os Druidas da Garra repousaram por milênios, as trágicas Ruínas de Kel'Theril e raízes expostas de Nordrassil danificadas durante a Batalha do Monte Hyjal."},sec={{t="Um Reino de Gelo Perpétuo",b="Erguida milhares de metros acima da natureza ao redor, Hibérnia repousa sob o ar puro da montanha e nevascas implacáveis. Enormes raízes expostas da Árvore do Mundo, Nordrassil, cortam os montes de neve como imponentes arcos de madeira, retorcidas e deformadas durante as lutas decisivas da Terceira Guerra. Embora grande parte do norte de Kalimdor seja dominada por florestas densas e climas quentes, Hibérnia é uma terra tranquila de matas alpinas moderadas, escarpas rochosas e lagos congelados, lar de formidáveis sabres-de-gelo, quimeras, iétis e ursos invernais de pelagem espessa."},{t="Encruzilhadas e Postos Avançados",b="Chegar a este planalto elevado exige atravessar as antigas passagens esculpidas do Domínio dos Presamatos, guardadas por urscabos não corrompidos que examinam de perto quaisquer viajantes vindos da Selva Maleva ou da Clareira da Lua. No centro do vale fica Visteterna, uma próspera cidade comercial operada pelo Cartel Bondebico. Os goblins recebem aventureiros tanto da Aliança quanto da Horda de caixas abertos, atuando como um refúgio indispensável de engenharia, comércio e fogueiras acolhedoras contra o frio cortante da montanha."},{t="Velhos Fantasmas e Dracos Azuis",b="Séculos antes do surgimento dos povoados modernos, elfos ancestrais ergueram a cidade lacustre de Kel'Theril. Depois que feiticeiros Altaneiros imprudentes estilhaçaram o maldito Cristal de Zin-Malor, a loucura os consumiu, deixando fantasmas inquietos a vagar pelos pilares em ruínas e pelas águas congeladas até hoje. Mais ao sul erguem-se as alturas cavernosas de Mazthoril, a tradicional fortaleza da revoada dragônica azul em Kalimdor. Ali, a ninhada do Tecelão de Feitiços Malygos, sob a vigilância da matrona protetora Haleh, guarda as correntes arcanas e contesta ameaças locais."},{t="A Sombra Iminente da Garganta",b="A serenidade de Hibérnia é bruscamente rompida ao longo de sua fronteira mais ao sul, na Garganta do Sussurro Sombrio. Ali, forças demoníacas de elite, legiões remanescentes da Terceira Guerra, rastejam por desfiladeiros irregulares bloqueando os caminhos superiores rumo ao cume do Monte Hyjal. Enquanto isso, os urscabos Quedinverno nativos sucumbiram a corrupções vis, levando pesquisadores independentes como Bruna Covaneve a investigar a mácula que avança antes que toda a vida selvagem do vale seja consumida."}},faq={{q="Como chego a Hibérnia?",a="Os viajantes devem passar pelo Domínio dos Presamatos, uma rede subterrânea de túneis localizada no nordeste da Selva Maleva. Cruzar as cavernas pacificamente exige conquistar a confiança dos urscabos Presamatos nativos, que atacam quaisquer invasores que considerem hostis. Ao passar pela saída leste, as encostas nevadas de Hibérnia surgem imediatamente.",al={"como chegar em hibérnia","como entrar em hibérnia","entrada de hibérnia","túnel dos presamatos hibérnia"}},{q="Quem governa a cidade de Visteterna?",a="Visteterna é administrada pelo Cartel Bondebico, o conglomerado mercantil goblin. Por causa do estrito foco no lucro e da neutralidade dos goblins, tanto viajantes da Horda quanto da Aliança podem utilizar seus mestres de voo, comerciantes de reparo, cofres bancários e mercadorias, desde que os visitantes não quebrem a paz dentro dos limites da cidade.",al={"quem controla visteterna","facção de visteterna","visteterna é neutra"}},{q="O que são os fantasmas que assombram o Lago Kel'Theril?",a="São os espíritos dos Elfos Noturnos Altaneiros que habitaram a antiga cidade de Kel'Theril dez mil anos atrás. Quando seus feiticeiros mexeram no roubado Cristal de Zin-Malor, sua destruição desencadeou uma maldição catastrófica. Expedições posteriores de altos-elfos séculos depois também foram levadas à loucura, fadadas a assombrar as ruínas congeladas ao lado de seus ancestrais.",al={"fantasmas do lago kel'theril","espíritos das ruínas de kel'theril","quem está em kel'theril"}},{q="Por que os urscabos Quedinverno são agressivos?",a="Os urscabos Quedinverno sucumbiram a uma corrupção não natural que se alastrou e levou o clã à hostilidade enlouquecida. Enquanto os Presamatos próximos mantêm com firmeza a sanidade, os Quedinverno caíram sob influências sombrias, motivando pesquisadores como Bruna Covaneve a estudar a mácula e limpar seus acampamentos.",al={"por que os quedinverno são hostis","corrupção da tribo quedinverno","bruna covaneve urscabos"}},{q="O que vive dentro de Mazthoril?",a="Mazthoril é o principal ninho e santuário da revoada dragônica azul em Kalimdor. Nas profundezas de suas agulhas cavernosas, dracônicos, filhotes de elite e dracos ancestrais guardam relíquias dracônicas poderosas e segredos arcanos sob o olhar atento de Haleh, consorte do Aspecto Malygos.",al={"dragões de mazthoril","o que é mazthoril","dragões azuis em hibérnia"}},{q="O que é a Garganta do Sussurro Sombrio?",a="A Garganta do Sussurro Sombrio é um desfiladeiro traiçoeiro nos confins meridionais do vale, ocupado por poderosos demônios de elite remanescentes da Terceira Guerra. O local serve como um perímetro pesadamente vigiado ao longo das trilhas traiçoeiras que levam às alturas do Monte Hyjal.",al={"demônios da garganta do sussurro sombrio","o que há na garganta do sussurro sombrio","portão de hyjal hibérnia"}},{q="É possível treinar ou domar sabres-de-gelo aqui?",a="Na Pedra Sabre-de-gelo, no extremo norte do vale, o Elfo Noturno Ripárion Glaciares cuida dos felinos brancos nativos. Aventureiros que o ajudam a conseguir suprimentos e a proteger o bando podem provar seu valor para aprender os segredos da criação e montaria de um Sabre-de-gelo.",al={"montaria sabre-de-gelo","ripárion glaciares sabre-de-gelo","como obter sabre-de-gelo"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="Ilha de Zefras",s="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar. Ela serve como o lar ancestral inicial dos Skyborne, cuja sociedade agora enfrenta uma crise existencial à medida que a magia que sustenta a ilha se desgasta continuamente. Com o contato cortado com os reinos celestes vizinhos, seus habitantes lutam contra o colapso elemental e a chegada de refugiados.",h="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar.",kw={"aeronaves","anvilas","plano elemental","siroccas","skyborne","muralha celeste","valanaar","windstones","zefras"},ang={["class:Shaman"]="Existindo diretamente dentro do Plano Elemental do ar, a Ilha de Zefras exemplifica o que acontece com terras elementais quando os espíritos que as equilibram desaparecem de repente.",["race:Skyborne"]="A Ilha de Zefras é o seu lar ancestral e ponto de partida, embora sua beleza remanescente mascare uma crise urgente de terreno em colapso e poder elemental minguante."},sec={{t="Um Reino nas Alturas",b="A Ilha de Zefras é uma massa de terra isolada à deriva nos ventos eternos da Muralha Celeste. Por gerações, os Skyborne viveram aqui ao lado de elementais do ar nativos que ajudavam a preservar as correntes mágicas que mantinham a ilha no alto. No entanto, vários séculos atrás, esses guardiões elementais desapareceram por completo. Privados de sua presença e tutela, os encantamentos latentes que sustentavam a terra começaram a falhar lentamente, fazendo com que Zefras se frature e se desestabilize aos poucos."},{t="Horizontes Interrompidos",b="Zefras não era o único santuário habitado pelos Skyborne dentro do Plano Elemental. Ilhas irmãs conhecidas como Anvilas e Siroccas também flutuavam pela Muralha Celeste, mas as comunicações entre elas cessaram após o desaparecimento dos elementais. Recentemente, refugiados dessas massas de terra vizinhas em ruínas conseguiram chegar a Zefras em busca de segurança, trazendo notícias sombrias de que as outras ilhas estão se desintegrando de vez sob seus pés."},{t="Limiar para Azeroth",b="Com sua própria massa de terra em lenta decadência, os Skyborne de Zefras começaram a olhar além das fronteiras da Muralha Celeste, em direção a Azeroth. Dos ancoradouros celestes de Valanaar, aeronaves agora partem para estabelecer raras conexões vitais com o reino mortal. Essas viagens conectam o domínio aéreo diretamente a pontos em Azeroth, incluindo os arredores de Dalaran nas Montanhas de Alterac e o Platô do Vigia dos Céus em Mulgore."}},faq={{q="Onde fica a Ilha de Zefras?",a="A Ilha de Zefras está situada dentro da Muralha Celeste, o Plano Elemental do ar, em vez de na superfície de Azeroth. Ela flutua em meio às nuvens perpétuas e às correntes de vento deste domínio etéreo.",al={"localização da ilha de zefras","onde fica zefras","em qual plano fica zefras"}},{q="Por que a Ilha de Zefras está se desfazendo?",a="A ilha dependia da presença de elementais do ar nativos que outrora coexistiam com os Skyborne. Vários séculos atrás, esses elementais desapareceram, deixando as fundações mágicas que ancoram e preservam a terra voadora enfraquecerem e se degradarem lentamente ao longo do tempo.",al={"por que zefras está colapsando","destruição da ilha de zefras","ilha moribunda"}},{q="O que são Anvilas e Siroccas?",a="São ilhas voadoras vizinhas na Muralha Celeste, também povoadas pelos Skyborne. A Ilha de Zefras perdeu a comunicação com ambas quando os elementais desapareceram, e refugiados em fuga agora relatam que tanto Anvilas quanto Siroccas estão colapsando no esquecimento.",al={"anvilas","siroccas","outras ilhas dos skyborne"}},{q="Como as pessoas viajam entre a Ilha de Zefras e Azeroth?",a="Os Skyborne operam ancoradouros celestes no assentamento de Valanaar. Aeronaves partem dessas docas através da fronteira planar em direção a Azeroth, pousando perto de Dalaran nas Montanhas de Alterac e no Platô do Vigia dos Céus em Mulgore.",al={"como sair de zefras","aeronaves de zefras","viajar para azeroth"}},{q="Quem são os Skyborne?",a="Os Skyborne são os habitantes que vivem na Ilha de Zefras e em seus reinos celestes irmãos. Tendo habitado a Muralha Celeste por gerações, eles agora enfrentam a lenta destruição de sua terra natal voadora à medida que sua magia de sustentação se dissipa.",al={"raça skyborne","quem vive em zefras"}},{q="Quem vive na Ilha de Zefras além dos Skyborne?",a="Além de aldeias pacíficas e refugiados visitantes, a ilha é assolada por bandidos locais, noctigarras que vivem em cavernas e feras que habitam áreas como o Covil dos Guinchotes e a Caverna dos Noctigarra.",al={"habitantes de zefras","inimigos em zefras"}}},fx={["1fd88046"]={q="O que é a Ilha de Zefras?",a="A Ilha de Zefras é uma massa de terra flutuante que paira dentro da Muralha Celeste, o Plano Elemental do Ar. Milênios atrás, elfos noturnos exilados que fugiam da perseguição em Eldre'Thalas negociaram com espíritos do vento nativos, que elevaram a ilha aos céus para mantê-los em segurança. Ela serve como o santuário ancestral de seus descendentes, os Nascidos do Céu.",al={"o que é zefras","sobre a ilha de zefras","informações sobre a ilha de zefras"}},["7ea7c85c"]={q="O que aconteceu na Ilha de Zefras?",a="A Ilha de Zefras foi elevada à Muralha Celeste depois que ancestrais elfos superiores se separaram do reinado sangrento do Príncipe Tortheldrin em Eldre'Thalas. Os Nascidos do Céu viveram em harmonia com elementais do ar por milhares de anos, mas, séculos atrás, esses patronos elementais desapareceram sem explicação. Sem sua magia contínua, os pilares que ancoravam a ilha começaram a se deteriorar, e refugiados de ilhas vizinhas em colapso fugiram para cá enquanto facções internas disputam recursos cada vez menores.",al={"história de zefras","o que aconteceu aqui em zefras","lore de zefras"}},["70a3c6ae"]={q="A Ilha de Zefras é perigosa?",a="Sim. Além da ameaça física iminente da própria ilha se desestabilizar e cair dos céus, o desaparecimento dos protetores elementais deixou a terra caótica. Acampamentos de bandidos, covis de animais hostis e atritos políticos voláteis entre a Alta Ordem, os Moldavento e os Al'Aketh tornam perigosa qualquer viagem fora dos assentamentos fortificados.",al={"zefras é perigoso","ameaças em zefras","perigos em zefras"}},b4875d06={q="Onde fica a ilha em comparação com o resto de Azeroth?",a="A Ilha de Zefras não repousa sobre a superfície de Azeroth; ela deriva dentro da Muralha Celeste, um domínio dimensional separado criado pelos forjados pelos titãs para conter elementais do ar caóticos. As únicas conexões físicas entre a ilha e o mundo mortal abaixo são dirigíveis especializados que atracam em Valanaar e viajam pela fronteira para locais como Dalaran e Mulgore.",al={"onde fica zefras em relação a azeroth","zefras fica em azeroth","localização de zefras comparada a azeroth"}},["2c89f95d"]={q="Quem são os Al'Aketh?",a="Os Al'Aketh são uma das facções rivais que lutam pelo domínio na Ilha de Zefras, ao lado da Alta Ordem e dos Moldavento. À medida que os pilares que ancoram a ilha falham e a sobrevivência se torna desesperadora, os Al'Aketh competem ativamente pela supremacia e pelo controle dos recursos místicos restantes da ilha.",al={"o que são os alaketh","facção al'aketh","quem é alaketh"}},["6e14d755"]={q="Vou sair da ilha eventualmente?",a="Sim. Embora a Ilha de Zefras sirva como seu lar e campo de treinamento inicial, aeronaves partem dos ancoradouros em Valanaar através de fendas planares para o continente de Azeroth, conectando-se diretamente a Dalaran nas Montanhas de Alterac e ao Platô do Vigia dos Céus em Mulgore.",al={"vou sair de zefras","sair da ilha de zefras","podemos ir para azeroth"}},["19470e71"]={q="Como vim parar na Ilha de Zefras?",a="Você nasceu entre os Nascidos do Céu, os shen'dorei que habitam este refúgio flutuante no alto da Muralha Celeste, o Plano Elemental do Ar. Milênios atrás, seus ancestrais fugiram do expurgo do Príncipe Tortheldrin em Eldre'Thalas e fizeram um pacto com espíritos do vento que elevaram este santuário aos céus. Enquanto outras ilhas irmãs, como Anvilas e Siroccas, desmoronam ou desaparecem de alcance, a Ilha de Zefras tem sido seu lar desde o início. Você começa sua jornada aqui, entre seu próprio povo.",al={"como cheguei aqui","como cheguei à ilha de zefras","por que acordei aqui","de onde eu vim"}},["5dae6f41"]={q="O que devo fazer na Ilha de Zefras?",a="Seu lar está desmoronando sob seus pés. Séculos atrás, os elementais do ar benevolentes desapareceram, e os pilares arcanos que unem a Ilha de Zefras estão perdendo seu poder. Refugiados chegam de ilhas externas em colapso enquanto facções rivais, incluindo a Alta Ordem, os Moldavento e os Al'Aketh, discutem sobre o que resta. Você deve ajudar seu povo, conter ameaças internas e feras selvagens, ajudar a estabilizar as magias falhas e, finalmente, procurar uma passagem para Azeroth antes que a ilha caia.",al={"o que devo fazer aqui","qual é meu objetivo aqui","o que estou fazendo na ilha de zefras","por que estou aqui"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
